__global__ void triplet_margin_loss_kernel(const float* __restrict__ anchor,
                                           const float* __restrict__ positive,
                                           const float* __restrict__ negative,
                                           const float  margin,
                                           const int    batch_size,
                                           const int    feat_size,
                                           float* __restrict__ losses)
{
    extern __shared__ float sdata[];            // 2 * blockDim.x floats
    float* pbuf = sdata;                        // positive distance square accumulator
    float* nbuf = sdata + blockDim.x;           // negative distance square accumulator

    const int sample_id = blockIdx.x;
    if (sample_id >= batch_size) return;

    const int tid = threadIdx.x;
    const int threads = blockDim.x;
    const int base_idx = sample_id * feat_size;

    float p_acc = 0.0f;
    float n_acc = 0.0f;

    // Strided loop gives fully-coalesced accesses
    for (int fid = tid; fid < feat_size; fid += threads) {
        float a = anchor  [base_idx + fid];
        float p = positive[base_idx + fid];
        float n = negative[base_idx + fid];

        float dp = a - p;
        float dn = a - n;

        p_acc += dp * dp;
        n_acc += dn * dn;
    }

    pbuf[tid] = p_acc;
    nbuf[tid] = n_acc;
    __syncthreads();

    // Block reduction
    for (int stride = threads >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            pbuf[tid] += pbuf[tid + stride];
            nbuf[tid] += nbuf[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float p_dist = sqrtf(pbuf[0]);
        float n_dist = sqrtf(nbuf[0]);
        float loss = fmaxf(0.0f, p_dist - n_dist + margin);
        losses[sample_id] = loss;
    }
}

