/* ------------------------------  KERNEL  ---------------------------------- */
/* Every thread computes TWO output elements (ping-pong), improving arithmetic
   intensity while keeping register pressure reasonable.
   One block = one (n, oc) pair  ==> weights reused from LDS by 256 threads. */
constexpr int THREADS_PER_BLOCK = 256;
constexpr int ELEMENTS_PER_THREAD = 2;   // tweakable

template<int KVAL>
__device__ __forceinline__
bool inside(int pos, int limit) { return (unsigned)pos < (unsigned)limit; }

__launch_bounds__(THREADS_PER_BLOCK, 2)
__global__
void convTranspose3d_kernel(const float *__restrict__ input,     // N, Ci, Di, Hi, Wi
                            const float *__restrict__ weight,    // Co, Ci_g, K, K, K
                            float       *__restrict__ output,    // N, Co, Do, Ho, Wo
                            int N, int Ci, int Co,
                            int Di, int Hi, int Wi,
                            int K, int stride, int padding,
                            int groups,
                            int Do, int Ho, int Wo)
{
    constexpr int Kc = 3;               // kernel == 3 in given model
    const int tid  = threadIdx.x;

    const int n  = blockIdx.x;          // batch
    const int oc = blockIdx.y;          // out-channel

    const int Co_g = Co / groups;
    const int Ci_g = Ci / groups;
    const int g    = oc / Co_g;         // group id

    /* ----------------------------------------------------------------------
       Load weights for this (oc) once into LDS, vectorised (float4) copy.   */
    extern __shared__ float sh_w[];     // size = Ci_g * K^3   (<= 8*27=216)
    const size_t w_per_oc = (size_t)Ci_g * Kc * Kc * Kc;
    const size_t w_offset = (size_t)oc * w_per_oc;

    /* vectorised copy, ensures every thread pulls contiguous values */
    for (size_t idx = tid << 2; idx < w_per_oc; idx += THREADS_PER_BLOCK << 2) {
        float4 v;
        const float4 *src = reinterpret_cast<const float4 *>(weight + w_offset + idx);
        v = *src;
        *reinterpret_cast<float4 *>(sh_w + idx) = v;
    }
    __syncthreads();

    /* ---------------------------------------------------------------------
       Each thread computes ELEMENTS_PER_THREAD distinct spatial positions   */
    const size_t spatial = (size_t)Do * Ho * Wo;
    for (size_t pos = tid; pos < spatial; pos += THREADS_PER_BLOCK) {

        /* ping-pong: current pos + stride == neighbour if inside */
        size_t pos2 = pos + THREADS_PER_BLOCK;
        bool   do_second = (pos2 < spatial);

        /* first element coordinates */
        int w_out =  pos            % Wo;
        size_t t  =  pos            / Wo;
        int h_out =  t              % Ho;
        int d_out =  t              / Ho;

        /* second element coordinates */
        int w_out2, h_out2, d_out2;
        if (do_second) {
            w_out2 =  pos2 % Wo;
            size_t t2 = pos2 / Wo;
            h_out2 =  t2   % Ho;
            d_out2 =  t2   / Ho;
        }

        float acc1 = 0.f, acc2 = 0.f;

        /* ------- iterate over kernel volume & input channels --------------*/
        for (int kd = 0; kd < Kc; ++kd) {
            int td1 = d_out + padding - kd;
            int td2 = d_out2 + padding - kd;

            bool ok1d = inside<Kc>(td1, stride * Di) && (td1 % stride == 0);
            bool ok2d = do_second && inside<Kc>(td2, stride * Di) && (td2 % stride == 0);

            int d_in1 = td1 / stride;
            int d_in2 = td2 / stride;

            if (!ok1d && !ok2d) continue;

            for (int kh = 0; kh < Kc; ++kh) {
                int th1 = h_out + padding - kh;
                int th2 = h_out2 + padding - kh;

                bool ok1h = ok1d && inside<Kc>(th1, stride * Hi) && (th1 % stride == 0);
                bool ok2h = ok2d && inside<Kc>(th2, stride * Hi) && (th2 % stride == 0);

                int h_in1 = th1 / stride;
                int h_in2 = th2 / stride;

                if (!ok1h && !ok2h) continue;

                for (int kw = 0; kw < Kc; ++kw) {
                    size_t k_offset = (size_t)kd * Kc * Kc + kh * Kc + kw;

                    int tw1 = w_out + padding - kw;
                    int tw2 = w_out2 + padding - kw;

                    bool ok1 = ok1h && inside<Kc>(tw1, stride * Wi) && (tw1 % stride == 0);
                    bool ok2 = ok2h && inside<Kc>(tw2, stride * Wi) && (tw2 % stride == 0);

                    if (!ok1 && !ok2) continue;

                    int w_in1 = tw1 / stride;
                    int w_in2 = tw2 / stride;

                    /* loop over Ci_g, unrolled 4-way where possible */
                    for (int ic_g = 0; ic_g < Ci_g; ++ic_g) {
                        int ic = g * Ci_g + ic_g;

                        size_t inp_base = (((((size_t)n * Ci + ic) * Di)));
                        if (ok1) {
                            size_t idx_in1 = (inp_base + d_in1) * Hi * Wi + h_in1 * Wi + w_in1;
                            float x1 = __ldg(input + idx_in1);
                            float w1 = sh_w[ic_g * Kc * Kc * Kc + k_offset];
                            acc1 += x1 * w1;
                        }
                        if (ok2) {
                            size_t idx_in2 = (inp_base + d_in2) * Hi * Wi + h_in2 * Wi + w_in2;
                            float x2 = __ldg(input + idx_in2);
                            float w2 = sh_w[ic_g * Kc * Kc * Kc + k_offset];
                            acc2 += x2 * w2;
                        }
                    }
                }
            }
        }

        /* write back */
        size_t out_idx1 = (((((size_t)n * Co + oc) * Do + d_out ) * Ho + h_out ) * Wo + w_out );
        output[out_idx1] = acc1;

        if (do_second) {
            size_t out_idx2 = (((((size_t)n * Co + oc) * Do + d_out2) * Ho + h_out2) * Wo + w_out2);
            output[out_idx2] = acc2;
        }
    }
}

