int main() {
    /* Parameters matching the PyTorch example */
    const int N  = 16;
    const int Ci = 32;
    const int Co = 64;
    const int K  = 3;
    const int Di = 16;
    const int Hi = 32;
    const int Wi = 32;
    const int stride  = 2;
    const int padding = 3;
    const int groups  = 4;

    const int Do = (Di - 1) * stride - 2 * padding + K;
    const int Ho = (Hi - 1) * stride - 2 * padding + K;
    const int Wo = (Wi - 1) * stride - 2 * padding + K;

    size_t in_size   = (size_t)N * Ci * Di * Hi * Wi;
    size_t w_size    = (size_t)Co * (Ci / groups) * K * K * K;
    size_t out_size  = (size_t)N * Co * Do * Ho * Wo;

    std::vector<float> h_in(in_size);
    std::vector<float> h_w (w_size);
    std::vector<float> h_out(out_size, 0.f);

    std::mt19937 gen(0);
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
    for (auto& v : h_in) v = dist(gen);
    for (auto& v : h_w)  v = dist(gen);

    float *d_in, *d_w, *d_out;
    CHECK(hipMalloc(&d_in,  in_size  * sizeof(float)));
    CHECK(hipMalloc(&d_w,   w_size   * sizeof(float)));
    CHECK(hipMalloc(&d_out, out_size * sizeof(float)));

    CHECK(hipMemcpy(d_in, h_in.data(), in_size * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_w,  h_w.data(),  w_size  * sizeof(float), hipMemcpyHostToDevice));

    dim3 grid(N, Co);
    dim3 block(THREADS_PER_BLOCK);
    size_t shared_bytes = (size_t)(Ci / groups) * K * K * K * sizeof(float);

    hipLaunchKernelGGL(convTranspose3d_kernel,
                       grid, block, shared_bytes, 0,
                       d_in, d_w, d_out,
                       N, Ci, Co,
                       Di, Hi, Wi,
                       K, stride, padding,
                       groups,
                       Do, Ho, Wo);

    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(h_out.data(), d_out, out_size * sizeof(float), hipMemcpyDeviceToHost));
    std::cout << "First output element: " << h_out[0] << std::endl;

    CHECK(hipFree(d_in));
    CHECK(hipFree(d_w));
    CHECK(hipFree(d_out));
    return 0;
}

