/* --- Tunables for gfx942 --------------------------------------------- */
constexpr int TILE_M = 64;   // rows of C per block
constexpr int TILE_N = 64;   // cols of C per block
constexpr int TILE_K = 32;   // reduction size per iteration

constexpr int THR_M  = 4;    // rows per thread
constexpr int THR_N  = 4;    // cols per thread

constexpr int BLK_DIM_X = 16;   // 16 x 16 = 256 threads
constexpr int BLK_DIM_Y = 16;   

constexpr int THREADS_PER_BLOCK = BLK_DIM_X * BLK_DIM_Y;

/* --------------------------------------------------------------------- */
__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void batched_gemm_kernel(const float* __restrict__ A,
                         const float* __restrict__ B,
                         float* __restrict__ C,
                         int batch,
                         int M, int N, int K)
{
    /* Block indices --------------------------------------------------- */
    const int blkCol = blockIdx.x;   // along N
    const int blkRow = blockIdx.y;   // along M
    const int bid    = blockIdx.z;   // batch id

    /* Starting indices for this block --------------------------------- */
    const int rowBase = blkRow * TILE_M;
    const int colBase = blkCol * TILE_N;

    const int tid   = threadIdx.y * BLK_DIM_X + threadIdx.x;   // 0..255
    const int laneR = tid / BLK_DIM_X;                         // 0..15
    const int laneC = tid % BLK_DIM_X;                         // 0..15

    const int thrRowBase = laneR * THR_M;  // 4 rows per thread
    const int thrColBase = laneC * THR_N;  // 4 cols per thread

    /* Per-batch base pointers ----------------------------------------- */
    const float* __restrict__ Ab = A + static_cast<size_t>(bid) * M * K;
    const float* __restrict__ Bb = B + static_cast<size_t>(bid) * K * N;
    float*       __restrict__ Cb = C + static_cast<size_t>(bid) * M * N;

    /* Shared memory tiles --------------------------------------------- */
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N + 1];  // +1 to skirt bank conflicts

    /* Accumulator register file --------------------------------------- */
    float acc[THR_M][THR_N] = {0.0f};

    /* Loop over K dimension ------------------------------------------- */
    for (int k0 = 0; k0 < K; k0 += TILE_K) {

        /* ---- Load tile of A into shared ----------------------------- */
        for (int idx = tid; idx < TILE_M * TILE_K; idx += THREADS_PER_BLOCK) {
            int r = idx / TILE_K;
            int c = idx % TILE_K;
            int g_r = rowBase + r;
            int g_c = k0 + c;
            As[r][c] = (g_r < M && g_c < K) ? Ab[g_r * K + g_c] : 0.0f;
        }

        /* ---- Load tile of B into shared ----------------------------- */
        for (int idx = tid; idx < TILE_K * TILE_N; idx += THREADS_PER_BLOCK) {
            int r = idx / TILE_N;
            int c = idx % TILE_N;
            int g_r = k0 + r;
            int g_c = colBase + c;
            Bs[r][c] = (g_r < K && g_c < N) ? Bb[g_r * N + g_c] : 0.0f;
        }
        __syncthreads();

        /* ---- Compute THR_M x THR_N micro-tile ----------------------- */
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {

            float a_frag[THR_M];
            float b_frag[THR_N];

            #pragma unroll
            for (int i = 0; i < THR_M; ++i)
                a_frag[i] = As[thrRowBase + i][kk];

            #pragma unroll
            for (int j = 0; j < THR_N; ++j)
                b_frag[j] = Bs[kk][thrColBase + j];

            #pragma unroll
            for (int i = 0; i < THR_M; ++i)
                #pragma unroll
                for (int j = 0; j < THR_N; ++j)
                    acc[i][j] += a_frag[i] * b_frag[j];
        }
        __syncthreads();
    }

    /* ---- Write C ---------------------------------------------------- */
    #pragma unroll
    for (int i = 0; i < THR_M; ++i) {
        int g_r = rowBase + thrRowBase + i;
        if (g_r < M) {
            #pragma unroll
            for (int j = 0; j < THR_N; ++j) {
                int g_c = colBase + thrColBase + j;
                if (g_c < N)
                    Cb[g_r * N + g_c] = acc[i][j];
            }
        }
    }
}

/* ------------------------------ Host stub ----------------------------- */
int main() {
    const int batch = 128;
    const int M = 128;
    const int K = 256;
    const int N = 512;

    const size_t sizeA = static_cast<size_t>(batch) * M * K;
    const size_t sizeB = static_cast<size_t>(batch) * K * N;
    const size_t sizeC = static_cast<size_t>(batch) * M * N;

    std::vector<float> hA(sizeA), hB(sizeB), hC(sizeC);
    std::mt19937 gen(0);
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
    for (auto& v : hA) v = dist(gen);
    for (auto& v : hB) v = dist(gen);

    float *dA, *dB, *dC;
    CHECK(hipMalloc(&dA, sizeA * sizeof(float)));
    CHECK(hipMalloc(&dB, sizeB * sizeof(float)));
    CHECK(hipMalloc(&dC, sizeC * sizeof(float)));

    CHECK(hipMemcpy(dA, hA.data(), sizeA * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(dB, hB.data(), sizeB * sizeof(float), hipMemcpyHostToDevice));

    dim3 blockDim(BLK_DIM_X, BLK_DIM_Y);
    dim3 gridDim((N + TILE_N - 1) / TILE_N,
                 (M + TILE_M - 1) / TILE_M,
                 batch);

    hipLaunchKernelGGL(batched_gemm_kernel, gridDim, blockDim, 0, 0,
                       dA, dB, dC, batch, M, N, K);
    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(hC.data(), dC, sizeC * sizeof(float), hipMemcpyDeviceToHost));

    /* Reference check -------------------------------------------------- */
    bool ok = true;
    for (int b = 0; b < batch && ok; ++b)
        for (int i = 0; i < M && ok; ++i)
            for (int j = 0; j < N && ok; ++j) {
                float ref = 0.0f;
                for (int kk = 0; kk < K; ++kk)
                    ref += hA[b * M * K + i * K + kk] *
                           hB[b * K * N + kk * N + j];
                if (std::fabs(ref - hC[b * M * N + i * N + j]) > 1e-3f) {
                    ok = false;
                    break;
                }
            }

    std::cout << (ok ? "PASSED" : "FAILED") << std::endl;

    CHECK(hipFree(dA));
    CHECK(hipFree(dB));
    CHECK(hipFree(dC));
    return ok ? 0 : 1;
}

