#define WARP_SIZE   64
#define BLOCK_SIZE  512              // 8 waves/block -> good CU occupancy
#define VEC_LOAD    4                // float4 vectorization
#define EPS         1e-5f

// ------------------------------------------------------------
// HIP error-checking macro
// ------------------------------------------------------------
#define CHECK_HIP(cmd)                                                        \
    do {                                                                      \
        hipError_t e = (cmd);                                                 \
        if (e != hipSuccess) {                                                \
            std::cerr << "HIP error: " << hipGetErrorString(e)                \
                      << " (" << e << ") at " << __FILE__ << ":" << __LINE__  \
                      << std::endl;                                           \
            std::exit(EXIT_FAILURE);                                          \
        }                                                                     \
    } while (0)

// ------------------------------------------------------------
// Warp-level reduction (gfx9 wavefront = 64)
// ------------------------------------------------------------
__device__ __forceinline__ float warp_reduce_sum(float v)
{
    #pragma unroll
    for (int offset = WARP_SIZE >> 1; offset > 0; offset >>= 1)
        v += __shfl_down(v, offset);
    return v;
}

// Block reduction (sum / sumsq) using 64-thread warps
template<int NWARPS>
__device__ __forceinline__ void block_reduce(float& s, float& s2)
{
    s  = warp_reduce_sum(s);
    s2 = warp_reduce_sum(s2);

    __shared__ float sh_s [NWARPS];
    __shared__ float sh_s2[NWARPS];

    const int lane = threadIdx.x & (WARP_SIZE - 1);
    const int warp = threadIdx.x >> 6;

    if (lane == 0) {
        sh_s [warp] = s;
        sh_s2[warp] = s2;
    }
    __syncthreads();

    if (warp == 0) {
        s  = (lane < NWARPS) ? sh_s [lane] : 0.f;
        s2 = (lane < NWARPS) ? sh_s2[lane] : 0.f;

        s  = warp_reduce_sum(s);
        s2 = warp_reduce_sum(s2);
    }
    __syncthreads();
}

// ------------------------------------------------------------
// Group Normalization kernel
// ------------------------------------------------------------
__launch_bounds__(BLOCK_SIZE)
__global__ void group_norm_kernel(const float* __restrict__ input,
                                  float* __restrict__ output,
                                  const float* __restrict__ gamma,   // length C or nullptr
                                  const float* __restrict__ beta,    // length C or nullptr
                                  int N, int C, int H, int W, int G,
                                  float eps)
{
    constexpr int NWARPS = BLOCK_SIZE / WARP_SIZE;

    const int ng = blockIdx.x;           // block per (n, g)
    const int n  = ng / G;
    const int g  = ng % G;

    const int Cpg = C / G;               // channels per group
    const int HW  = H * W;
    const int M   = Cpg * HW;            // elements per (n, g)

    const size_t group_off = ( ( (size_t)n * C + g * Cpg ) * HW );

    // --------------------------------------------------------
    // Pass 1 : compute mean & variance
    // --------------------------------------------------------
    float sum   = 0.f;
    float sumsq = 0.f;

    // Vectorized loading
    size_t idx = threadIdx.x * VEC_LOAD;
    const size_t stride = BLOCK_SIZE * VEC_LOAD;

    for (; idx + VEC_LOAD - 1 < (size_t)M; idx += stride)
    {
        float4 v4 = *reinterpret_cast<const float4*>(input + group_off + idx);
        sum   += v4.x + v4.y + v4.z + v4.w;
        sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }

    // Scalar tail
    for (; idx < (size_t)M; idx += BLOCK_SIZE)
    {
        float v = input[group_off + idx];
        sum   += v;
        sumsq += v * v;
    }

    block_reduce<NWARPS>(sum, sumsq);

    const float mean    = sum / M;
    const float var     = sumsq / M - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    __syncthreads(); // ensure mean/var visible to all threads

    // --------------------------------------------------------
    // Pass 2 : normalize & affine
    // --------------------------------------------------------
    idx = threadIdx.x * VEC_LOAD;
    for (; idx + VEC_LOAD - 1 < (size_t)M; idx += stride)
    {
        // Compute channel index for this packed load
        int c_local = (idx            ) / HW;   // channel of first element
        int c_global = g * Cpg + c_local;

        float4 v4    = *reinterpret_cast<const float4*>(input + group_off + idx);
        float4 out4;

        float gamma_v0 = gamma ? gamma[c_global    ] : 1.f;
        float beta_v0  = beta  ? beta [c_global    ] : 0.f;

        float gamma_v1 = gamma ? gamma[c_global    ] : 1.f; // same channel, reused
        float beta_v1  = beta  ? beta [c_global    ] : 0.f;

        // As all four elements share same channel (contiguous HW), we reuse gamma/beta
        out4.x = (v4.x - mean) * inv_std * gamma_v0 + beta_v0;
        out4.y = (v4.y - mean) * inv_std * gamma_v0 + beta_v0;
        out4.z = (v4.z - mean) * inv_std * gamma_v0 + beta_v0;
        out4.w = (v4.w - mean) * inv_std * gamma_v0 + beta_v0;

        *reinterpret_cast<float4*>(output + group_off + idx) = out4;
    }

    // Scalar tail
    for (; idx < (size_t)M; idx += BLOCK_SIZE)
    {
        int c_local  = idx / HW;
        int c_global = g * Cpg + c_local;

        float gamma_v = gamma ? gamma[c_global] : 1.f;
        float beta_v  = beta  ? beta [c_global] : 0.f;

        float v = input[group_off + idx];
        output[group_off + idx] = (v - mean) * inv_std * gamma_v + beta_v;
    }
}

