/* ---------------------------------------------------------------------------
 *  Tunable parameters – selected for gfx942
 * -------------------------------------------------------------------------*/
constexpr int TILE_M        = 64;   // rows of C per block
constexpr int TILE_N        = 64;   // cols of C per block
constexpr int TILE_K        = 16;   // reduction depth per iteration
constexpr int BLK_THREADS_X = 16;   // 16×16 = 256 threads / block
constexpr int BLK_THREADS_Y = 16;

static_assert(TILE_M % 4 == 0 && TILE_N % 4 == 0,
              "TILE_M and TILE_N must be multiples of 4");

/* ---------------------------------------------------------------------------
 *  Kernel :  C = Aᵀ · Bᵀ
 *  A stored row–major (K, M)
 *  B stored row–major (N, K)
 * -------------------------------------------------------------------------*/
__launch_bounds__(BLK_THREADS_X * BLK_THREADS_Y, 2)
__global__ void gemm_AT_BT_fast(
        const float *__restrict__ A,
        const float *__restrict__ B,
        float       *__restrict__ C,
        const int M,
        const int N,
        const int K)
{
    /* ---- thread identifiers -------------------------------------------*/
    const int tx  = threadIdx.x;                  // 0..15
    const int ty  = threadIdx.y;                  // 0..15
    const int tid = ty * BLK_THREADS_X + tx;      // 0..255

    /* ---- block origin in C --------------------------------------------*/
    const int m_tile = blockIdx.y * TILE_M;
    const int n_tile = blockIdx.x * TILE_N;

    /* ---- shared memory tiles (bank-conflict free by +1 padding) --------*/
    __shared__ float sA[TILE_K][TILE_M + 1];
    __shared__ float sB[TILE_K][TILE_N + 1];

    /* ---- per-thread accumulator (4 × 4) -------------------------------*/
    const int local_m_base = ty * 4;              // each thread handles 4 rows
    const int local_n_base = tx * 4;              // and 4 cols
    float acc[4][4] = { {0} };

    /* ---- loop over K dimension ----------------------------------------*/
    for (int k0 = 0; k0 < K; k0 += TILE_K)
    {
        /* ---------------- load A tile ----------------------------------*/
        for (int idx = tid; idx < TILE_K * TILE_M; idx += BLK_THREADS_X * BLK_THREADS_Y)
        {
            const int l_k = idx / TILE_M;         // 0..TILE_K-1
            const int l_m = idx % TILE_M;         // 0..TILE_M-1
            const int g_k = k0 + l_k;
            const int g_m = m_tile + l_m;
            sA[l_k][l_m] = (g_k < K && g_m < M) ? A[g_k * M + g_m] : 0.0f;
        }

        /* ---------------- load B tile ----------------------------------*
         *  Re-index so that threads read contiguous elements along K
         *  (better coalescing for row-major B).
         *  idx   : 0..TILE_K*TILE_N-1
         *  l_n   : idx / TILE_K   (row in shared mem)
         *  l_k   : idx % TILE_K   (col in shared mem)
         * ----------------------------------------------------------------*/
        for (int idx = tid; idx < TILE_K * TILE_N; idx += BLK_THREADS_X * BLK_THREADS_Y)
        {
            const int l_n = idx / TILE_K;         // 0..TILE_N-1
            const int l_k = idx % TILE_K;         // 0..TILE_K-1
            const int g_n = n_tile + l_n;
            const int g_k = k0 + l_k;
            sB[l_k][l_n] = (g_n < N && g_k < K) ? B[g_n * K + g_k] : 0.0f;
        }

        __syncthreads();

        /* ---------------- compute --------------------------------------*/
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k)
        {
            float a0 = sA[k][local_m_base + 0];
            float a1 = sA[k][local_m_base + 1];
            float a2 = sA[k][local_m_base + 2];
            float a3 = sA[k][local_m_base + 3];

            float b0 = sB[k][local_n_base + 0];
            float b1 = sB[k][local_n_base + 1];
            float b2 = sB[k][local_n_base + 2];
            float b3 = sB[k][local_n_base + 3];

            acc[0][0] += a0 * b0;
            acc[0][1] += a0 * b1;
            acc[0][2] += a0 * b2;
            acc[0][3] += a0 * b3;

            acc[1][0] += a1 * b0;
            acc[1][1] += a1 * b1;
            acc[1][2] += a1 * b2;
            acc[1][3] += a1 * b3;

            acc[2][0] += a2 * b0;
            acc[2][1] += a2 * b1;
            acc[2][2] += a2 * b2;
            acc[2][3] += a2 * b3;

            acc[3][0] += a3 * b0;
            acc[3][1] += a3 * b1;
            acc[3][2] += a3 * b2;
            acc[3][3] += a3 * b3;
        }
        __syncthreads();
    }

    /* ---- write back ----------------------------------------------------*/
    const int g_m0 = m_tile + local_m_base;
    const int g_n0 = n_tile + local_n_base;

    #pragma unroll
    for (int im = 0; im < 4; ++im)
    {
        int gm = g_m0 + im;
        if (gm < M)
        {
            #pragma unroll
            for (int in = 0; in < 4; ++in)
            {
                int gn = g_n0 + in;
                if (gn < N)
                    C[gm * N + gn] = acc[im][in];
            }
        }
    }
}

