constexpr int WAVE_SIZE = 64;          // AMD wavefront size
constexpr int WAVES_PER_BLOCK = 4;     // 256 threads / block
constexpr int THREADS_PER_BLOCK = WAVE_SIZE * WAVES_PER_BLOCK;
constexpr int TILE_W = 8;              // each thread computes 8 consecutive output x

/*-------------------------------------------------------------------------------------
 * Transposed-convolution kernel
 * – wavefront-level tiling in X
 * – optional fast path for stride==1
 * – reads/writes fully coalesced
 *------------------------------------------------------------------------------------*/
template<bool STRIDE1>
__launch_bounds__(THREADS_PER_BLOCK, 4)
__global__ void conv2d_transpose_kernel(
        const float *__restrict__ inp,     // [N, Ci, Hi, Wi]
        const float *__restrict__ wgt,     // [Ci, Co/groups, kH, kW]
        const float *__restrict__ bias,    // [Co] – can be nullptr
        float       *__restrict__ out,     // [N, Co, Ho, Wo]
        int N, int Ci, int Hi, int Wi,
        int Co, int Ho, int Wo,
        int kH, int kW,
        int stride_h, int stride_w,
        int pad_h, int pad_w,
        int out_pad_h, int out_pad_w,
        int groups)
{
    const int tid      = threadIdx.x;        // 0..255
    const int wave_id  = tid >> 6;           // 0..3
    const int lane     = tid & 63;           // 0..63

    const int ox0 = (blockIdx.x * THREADS_PER_BLOCK / WAVE_SIZE * TILE_W)   // blocks before this one
                  + (wave_id * WAVE_SIZE * TILE_W)                          // waves inside block
                  + (lane    * TILE_W);                                    // lanes inside wave

    const int oy = blockIdx.y;
    const int n  = blockIdx.z / Co;
    const int oc = blockIdx.z % Co;

    if (n >= N || oy >= Ho || oc >= Co) return;

    float acc[TILE_W];
#pragma unroll
    for (int t = 0; t < TILE_W; ++t)
        acc[t] = (bias ? bias[oc] : 0.0f);

    const int Co_per_g = Co / groups;
    const int Ci_per_g = Ci / groups;
    const int g        = oc / Co_per_g;
    const int oc_in_g  = oc % Co_per_g;

    /* ---------------- main accumulation loop ---------------- */
    for (int ic_in_g = 0; ic_in_g < Ci_per_g; ++ic_in_g) {
        const int ic = g * Ci_per_g + ic_in_g;
        const float *w_base = wgt + (((ic * Co_per_g + oc_in_g) * kH) * kW);

        for (int kh = 0; kh < kH; ++kh) {
            int in_y_src = oy + pad_h - kh;
            int in_y;
            bool valid_row = false;

            if constexpr (STRIDE1) {
                in_y = in_y_src;
                valid_row = (in_y_src >= 0 && in_y_src < Hi);
            } else {
                if (in_y_src >= 0 && (in_y_src % stride_h) == 0) {
                    in_y = in_y_src / stride_h;
                    valid_row = (in_y < Hi);
                }
            }
            if (!valid_row) continue;

            const float *in_row = inp + (((n * Ci + ic) * Hi + in_y) * Wi);

            for (int kw = 0; kw < kW; ++kw) {
                const float w_val = w_base[kh * kW + kw];

#pragma unroll
                for (int t = 0; t < TILE_W; ++t) {
                    const int ox = ox0 + t;
                    if (ox >= Wo) continue;

                    int in_x_src = ox + pad_w - kw;
                    int in_x;
                    bool valid_col = false;

                    if constexpr (STRIDE1) {
                        in_x = in_x_src;
                        valid_col = (in_x_src >= 0 && in_x_src < Wi);
                    } else {
                        if (in_x_src >= 0 && (in_x_src % stride_w) == 0) {
                            in_x = in_x_src / stride_w;
                            valid_col = (in_x < Wi);
                        }
                    }
                    if (!valid_col) continue;

                    const float v = in_row[in_x];
                    acc[t] += v * w_val;
                }
            }
        }
    }

    /* ---------------- write results ---------------- */
#pragma unroll
    for (int t = 0; t < TILE_W; ++t) {
        const int ox = ox0 + t;
        if (ox >= Wo) continue;
        out[ (((n * Co + oc) * Ho + oy) * Wo) + ox ] = acc[t];
    }
}

