    CHECK(hipMemcpy(h_out, d_out, out_sz, hipMemcpyDeviceToHost));

    double l1 = 0.0;
    for (size_t i = 0; i < out_sz / sizeof(float); ++i) l1 += fabs(h_out[i]);
    printf("Output L1 = %lf\n", l1);

