#define BLOCK_SIZE 256               // must be power-of-two ≤ 1024

#define HIP_CHECK(stmt)                                                   \
    do {                                                                  \
        hipError_t err = (stmt);                                          \
        if (err != hipSuccess) {                                          \
            fprintf(stderr, "HIP error %s at %s:%d\n",                    \
                    hipGetErrorString(err), __FILE__, __LINE__);          \
            exit(EXIT_FAILURE);                                           \
        }                                                                 \
    } while (0)

__attribute__((amdgpu_flat_work_group_size(64, BLOCK_SIZE)))
__global__ void exclusive_cumsum_dim1(const float *__restrict__ in,
                                      float *__restrict__ out,
                                      const int rows, const int cols)
{
    __shared__ float sh_totals[BLOCK_SIZE];   // per-thread partial sums

    const int tid   = threadIdx.x;
    const int row   = blockIdx.x;
    const int nthr  = blockDim.x;

    const int chunk = (cols + nthr - 1) / nthr;        // contiguous segment size
    const int start = tid * chunk;
    int       end   = start + chunk;
    if (end > cols) end = cols;

    const int row_off = row * cols;

    // ---- Pass 1 : local exclusive prefix + running total --------------------
    float running = 0.0f;

    // unroll by 4 when possible
    int idx = start;
    for (; idx + 3 < end; idx += 4) {
        float v0 = in[row_off + idx    ];
        out [row_off + idx    ] = running;
        running += v0;

        float v1 = in[row_off + idx + 1];
        out [row_off + idx + 1] = running;
        running += v1;

        float v2 = in[row_off + idx + 2];
        out [row_off + idx + 2] = running;
        running += v2;

        float v3 = in[row_off + idx + 3];
        out [row_off + idx + 3] = running;
        running += v3;
    }
    for (; idx < end; ++idx) {                       // tail
        out[row_off + idx] = running;
        running += in[row_off + idx];
    }

    // store per-thread subtotal
    sh_totals[tid] = running;
    __syncthreads();

    // ---- Pass 2 : block-level exclusive scan over thread totals ------------
    // Hillis-Steele on shared memory
    for (int offset = 1; offset < nthr; offset <<= 1) {
        float addend = 0.0f;
        if (tid >= offset)
            addend = sh_totals[tid - offset];
        __syncthreads();
        if (tid >= offset)
            sh_totals[tid] += addend;
        __syncthreads();
    }

    const float thread_offset = (tid == 0) ? 0.0f : sh_totals[tid - 1];

    // ---- Pass 3 : add offset to previously written partial prefixes --------
    for (int j = start; j < end; ++j)
        out[row_off + j] += thread_offset;
}

