    const int rows = 128;
    const int cols = 4000;
    const size_t total = static_cast<size_t>(rows) * cols;

    float *h_in  = static_cast<float*>(malloc(total * sizeof(float)));
    float *h_out = static_cast<float*>(malloc(total * sizeof(float)));
    if (!h_in || !h_out) { fprintf(stderr, "host alloc failed\n"); return 1; }

    for (size_t i = 0; i < total; ++i)
        h_in[i] = static_cast<float>((i % 17) - 8);

    float *d_in, *d_out;
    HIP_CHECK(hipMalloc(&d_in,  total * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_out, total * sizeof(float)));

    HIP_CHECK(hipMemcpy(d_in, h_in, total * sizeof(float), hipMemcpyHostToDevice));

    dim3 grid(rows);
    dim3 block(BLOCK_SIZE);

    hipLaunchKernelGGL(exclusive_cumsum_dim1, grid, block, 0, 0,
                       d_in, d_out, rows, cols);
    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    HIP_CHECK(hipMemcpy(h_out, d_out, total * sizeof(float), hipMemcpyDeviceToHost));

    // verify
    bool ok = true;
    for (int r = 0; r < rows && ok; ++r) {
        float acc = 0.0f;
        for (int c = 0; c < cols; ++c) {
            if (fabs(h_out[r * cols + c] - acc) > 1e-3f) { ok = false; break; }
            acc += h_in[r * cols + c];
        }
    }
    printf("Result %s\n", ok ? "PASSED" : "FAILED");

    free(h_in);
    free(h_out);
    HIP_CHECK(hipFree(d_in));
    HIP_CHECK(hipFree(d_out));
    return ok ? 0 : 1;
}

