//-----------------------------------------------------------------------------
// Vectorized MaxPool1d kernel
//-----------------------------------------------------------------------------
template <typename T, int VEC, bool ReturnIndices>
__launch_bounds__(256, 2)
__global__ void maxpool1d_kernel(const T* __restrict__ x,
                                 T* __restrict__ y,
                                 int64_t* __restrict__ ind,
                                 const int N, const int C, const int L,
                                 const int K, const int S, const int P, const int D,
                                 const int outL)
{
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int base_out = tid * VEC;                // first output index this thread is responsible for
    const int total_out = N * C * outL;

    #pragma unroll
    for (int v = 0; v < VEC; ++v) {
        const int gid = base_out + v;
        if (gid >= total_out) break;

        int tmp   = gid;
        const int l_out = tmp % outL;  tmp /= outL;
        const int c     = tmp % C;     tmp /= C;
        const int n     = tmp;         // remaining dimension is batch

        const int in_start = l_out * S - P;
        const int in_base  = (n * C + c) * L;

        T max_val = -std::numeric_limits<T>::infinity();
        int max_idx = -1;

        #pragma unroll
        for (int k = 0; k < K; ++k) {
            const int in_idx = in_start + k * D;
            if (in_idx >= 0 && in_idx < L) {
                T val = x[in_base + in_idx];
                if (val > max_val) {
                    max_val = val;
                    max_idx = in_idx;
                }
            }
        }

        y[gid] = max_val;
        if (ReturnIndices)
            ind[gid] = static_cast<int64_t>(max_idx);
    }
}

//-----------------------------------------------------------------------------
// Host helper
//-----------------------------------------------------------------------------
void maxpool1d(const float* h_x, float* h_y,
               int N, int C, int L,
               int K, int S, int P, int D,
               bool return_indices = false)
{
    const int outL = static_cast<int>(std::floor((L + 2 * P - D * (K - 1) - 1) / static_cast<float>(S) + 1));

    const size_t in_size  = static_cast<size_t>(N) * C * L    * sizeof(float);
    const size_t out_size = static_cast<size_t>(N) * C * outL * sizeof(float);

    float*  d_x   = nullptr;
    float*  d_y   = nullptr;
    int64_t* d_ind = nullptr;

    CHECK(hipMalloc(&d_x, in_size));
    CHECK(hipMalloc(&d_y, out_size));
    if (return_indices)
        CHECK(hipMalloc(&d_ind, out_size / sizeof(float) * sizeof(int64_t)));

    CHECK(hipMemcpy(d_x, h_x, in_size, hipMemcpyHostToDevice));

    constexpr int VEC = 4;                          // outputs processed per thread
    const int threads_per_block = 256;
    const int total_threads = ( (N * C * outL) + VEC - 1 ) / VEC;
    const int blocks = (total_threads + threads_per_block - 1) / threads_per_block;

    if (return_indices) {
        hipLaunchKernelGGL((maxpool1d_kernel<float, VEC, true>),
                           dim3(blocks), dim3(threads_per_block), 0, 0,
                           d_x, d_y, d_ind, N, C, L, K, S, P, D, outL);
    } else {
        hipLaunchKernelGGL((maxpool1d_kernel<float, VEC, false>),
                           dim3(blocks), dim3(threads_per_block), 0, 0,
                           d_x, d_y, nullptr, N, C, L, K, S, P, D, outL);
    }
    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(h_y, d_y, out_size, hipMemcpyDeviceToHost));

    CHECK(hipFree(d_x));
    CHECK(hipFree(d_y));
    if (d_ind) CHECK(hipFree(d_ind));
}

