constexpr float INV_SQRT_2 = 0.70710678118654752440f;

__device__ __forceinline__ float gelu(float x) {
    return 0.5f * x * (1.0f + erff(x * INV_SQRT_2));
}

extern "C" __global__ __launch_bounds__(256) void gelu_kernel_vec4(const float4* __restrict__ x,
                                                                  float4* __restrict__ out,
                                                                  int n_pack) {
    int idx    = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    for (int i = idx; i < n_pack; i += stride) {
        float4 v = x[i];
        float4 r;
        r.x = gelu(v.x);
        r.y = gelu(v.y);
        r.z = gelu(v.z);
        r.w = gelu(v.w);
        out[i] = r;
    }
}

extern "C" __global__ __launch_bounds__(256) void gelu_kernel_scalar(const float* __restrict__ x,
                                                                     float* __restrict__ out,
                                                                     int n) {
    int idx    = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    for (int i = idx; i < n; i += stride) {
        out[i] = gelu(x[i]);
    }
}

int main() {
    const int batch_size = 16;
    const int dim        = 16384;
    const int n          = batch_size * dim;
    const size_t bytes   = static_cast<size_t>(n) * sizeof(float);

    /* Host data */
    std::vector<float> h_x(n);
    std::vector<float> h_out(n);

    std::mt19937                 gen(0);
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
    for (float& v : h_x) { v = dist(gen); }

    /* Device data */
    float* d_x   = nullptr;
    float* d_out = nullptr;
    HIP_CHECK(hipMalloc(&d_x, bytes));
    HIP_CHECK(hipMalloc(&d_out, bytes));

    HIP_CHECK(hipMemcpy(d_x, h_x.data(), bytes, hipMemcpyHostToDevice));

    const int threads = 256;

    /* Vectorized kernel launch */
    const int n_pack = n / 4;
    int blocks_vec4  = (n_pack + threads - 1) / threads;
    HIP_CHECK(hipOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_vec4,
                                                           gelu_kernel_vec4,
                                                           threads,
                                                           0));
    int device;
    HIP_CHECK(hipGetDevice(&device));
    hipDeviceProp_t prop;
    HIP_CHECK(hipGetDeviceProperties(&prop, device));
    blocks_vec4 *= prop.multiProcessorCount;
    blocks_vec4  = std::min(blocks_vec4, (n_pack + threads - 1) / threads);
    hipLaunchKernelGGL(gelu_kernel_vec4,
                       dim3(blocks_vec4),
                       dim3(threads),
                       0,
                       0,
                       reinterpret_cast<const float4*>(d_x),
                       reinterpret_cast<float4*>(d_out),
                       n_pack);

    /* Scalar tail (if any) */
    const int tail_start = n_pack * 4;
    const int tail       = n - tail_start;
    if (tail > 0) {
        int blocks_tail = (tail + threads - 1) / threads;
        hipLaunchKernelGGL(gelu_kernel_scalar,
                           dim3(blocks_tail),
                           dim3(threads),
                           0,
                           0,
                           d_x + tail_start,
                           d_out + tail_start,
                           tail);
    }

    HIP_CHECK(hipDeviceSynchronize());
    HIP_CHECK(hipMemcpy(h_out.data(), d_out, bytes, hipMemcpyDeviceToHost));

    for (int i = 0; i < 5; ++i) {
        printf("x=%f  gelu=%f\n", h_x[i], h_out[i]);
    }

    HIP_CHECK(hipFree(d_x));
    HIP_CHECK(hipFree(d_out));

    return 0;
}

