// Tile width (number of output pixels each thread computes along X)
constexpr int TILE_W = 4;
constexpr int THREADS = 64;        // 64 threads (one wavefront)

// Kernel: grouped, NCHW, float32, arbitrary asymmetric params, no bias
extern "C" __global__
__launch_bounds__(THREADS, 4)
void conv_transpose2d_grouped_kernel_v2(
    const float* __restrict__ input,          // [N, Cin,  Hin, Win]
    const float* __restrict__ weight,         // [Cin, Cout/G, kH, kW]
    float*       __restrict__ output,         // [N, Cout, Hout, Wout]
    int N,
    int Cin,
    int Hin,
    int Win,
    int Cout,
    int kH,
    int kW,
    int strideH,
    int strideW,
    int padH,
    int padW,
    int dilH,
    int dilW,
    int groups,
    int Hout,
    int Wout)
{
    extern __shared__ float sWeight[]; // dynamic shared memory per block

    // Decode block / thread indices
    int tx = threadIdx.x;

    int block_w_base = (blockIdx.x * THREADS + tx) * TILE_W; // starting w_out for this thread
    int h_out = blockIdx.y;
    int tmp   = blockIdx.z;
    int n     = tmp / Cout;
    int co    = tmp % Cout;

    if (n >= N || h_out >= Hout) return;

    const int cout_per_grp = Cout / groups;
    const int cin_per_grp  = Cin  / groups;
    const int gid          = co / cout_per_grp;
    const int co_in_grp    = co % cout_per_grp;

    // ------------------------------------------------------------------
    // Stage 1: load weights for (co) into shared memory
    // ------------------------------------------------------------------
    int weight_elems_per_co = cin_per_grp * kH * kW;

    for (int idx = tx; idx < weight_elems_per_co; idx += THREADS) {
        int tmp_idx  = idx;
        int kw       = tmp_idx % kW;      tmp_idx /= kW;
        int kh       = tmp_idx % kH;      tmp_idx /= kH;
        int ci_grp   = tmp_idx;           // 0..cin_per_grp-1
        int ci       = gid * cin_per_grp + ci_grp;

        size_t w_idx = ((size_t)ci * cout_per_grp + co_in_grp) * kH * kW +
                       (size_t)kh * kW + kw;

        sWeight[idx] = weight[w_idx];
    }
    __syncthreads();

    // ------------------------------------------------------------------
    // Stage 2: compute TILE_W outputs per thread
    // ------------------------------------------------------------------
    float accum[TILE_W] = {0.f};

    // iterate over kernel
    for (int kh = 0; kh < kH; ++kh) {
        int in_h = h_out + padH - kh * dilH;
        if (in_h < 0) continue;
        if (in_h % strideH) continue;
        in_h /= strideH;
        if (in_h >= Hin) continue;

        for (int kw = 0; kw < kW; ++kw) {
            int kernel_offset = (kh * kW + kw) * cin_per_grp;

            // precompute w positions for TILE_W
            int in_w_base = block_w_base + padW - kw * dilW;
            int strideW_mod = in_w_base % strideW;

            // iterate over input channels in this group
            for (int ci_grp = 0; ci_grp < cin_per_grp; ++ci_grp) {
                int ci = gid * cin_per_grp + ci_grp;
                size_t base_in_idx =
                    ((size_t)n * Cin + ci) * Hin * Win +
                    (size_t)in_h * Win;

                float w_val = sWeight[kernel_offset + ci_grp];

                #pragma unroll
                for (int t = 0; t < TILE_W; ++t) {
                    int w_out = block_w_base + t;
                    if (w_out >= Wout) continue;

                    int in_w = in_w_base + t; // = w_out + padW - kw*dilW

                    if (in_w < 0) continue;
                    // Check stride condition efficiently
                    if ((strideW_mod + t) % strideW) continue;

                    int iw_div = in_w / strideW;
                    if (iw_div >= Win) continue;

                    size_t in_idx = base_in_idx + iw_div;
                    float in_val = __ldg(input + in_idx);
                    accum[t] += in_val * w_val;
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // Stage 3: write results
    // ------------------------------------------------------------------
    size_t out_base =
        ((size_t)n * Cout + co) * Hout * Wout +
        (size_t)h_out * Wout;

    #pragma unroll
    for (int t = 0; t < TILE_W; ++t) {
        int w_out = block_w_base + t;
        if (w_out >= Wout) break;
        output[out_base + w_out] = accum[t];
    }
}

