int main() {
    // Problem dimensions (match PyTorch example)
    const int N   = 16;
    const int Cin = 32;
    const int Cout= 64;
    const int kH  = 3;
    const int kW  = 5;
    const int sH  = 2;
    const int sW  = 3;
    const int pH  = 1;
    const int pW  = 2;
    const int dH  = 2;
    const int dW  = 1;
    const int G   = 4;

    const int Hin = 128;
    const int Win = 256;

    const int Hout = (Hin - 1) * sH - 2 * pH + dH * (kH - 1) + 1;
    const int Wout = (Win - 1) * sW - 2 * pW + dW * (kW - 1) + 1;

    size_t in_size   = (size_t)N * Cin * Hin * Win;
    size_t wt_size   = (size_t)Cin * (Cout / G) * kH * kW;
    size_t out_size  = (size_t)N * Cout * Hout * Wout;

    float *h_in  = (float*)malloc(in_size  * sizeof(float));
    float *h_wt  = (float*)malloc(wt_size  * sizeof(float));
    float *h_out = (float*)malloc(out_size * sizeof(float));

    for (size_t i = 0; i < in_size; ++i)  h_in[i] = sinf(i * 0.001f);
    for (size_t i = 0; i < wt_size; ++i)  h_wt[i] = cosf(i * 0.002f);

    float *d_in, *d_wt, *d_out;
    CHECK(hipMalloc(&d_in,  in_size  * sizeof(float)));
    CHECK(hipMalloc(&d_wt,  wt_size  * sizeof(float)));
    CHECK(hipMalloc(&d_out, out_size * sizeof(float)));

    CHECK(hipMemcpy(d_in, h_in, in_size * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_wt, h_wt, wt_size * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemset(d_out, 0, out_size * sizeof(float)));

    dim3 block(THREADS);
    dim3 grid((Wout + THREADS * TILE_W - 1) / (THREADS * TILE_W),
              Hout,
              N * Cout);

    size_t shmem_bytes = (Cin / G) * kH * kW * sizeof(float);

    hipLaunchKernelGGL(conv_transpose2d_grouped_kernel_v2,
                       grid,
                       block,
                       shmem_bytes,
                       0,
                       d_in, d_wt, d_out,
                       N, Cin, Hin, Win, Cout,
                       kH, kW, sH, sW, pH, pW, dH, dW,
                       G, Hout, Wout);

    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(h_out, d_out, out_size * sizeof(float), hipMemcpyDeviceToHost));

    double acc = 0.0;
    for (size_t i = 0; i < out_size; ++i) acc += h_out[i];
    printf("Accumulated output value: %f\n", acc);

    (void)hipFree(d_in);
    (void)hipFree(d_wt);
    (void)hipFree(d_out);
    free(h_in); free(h_wt); free(h_out);
    return 0;
}

