constexpr int N                 = 2048;   // matrix order
constexpr int TILE              = 32;     // tile edge length
constexpr int THREADS_X         = 8;      // 8 × 8 = 64 threads  = 1 wavefront
constexpr int THREADS_Y         = 8;
constexpr int THREADS_PER_BLOCK = THREADS_X * THREADS_Y;

// -----------------------------------------------------------------------------
// HIP kernel
// -----------------------------------------------------------------------------
__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)   // 2 waves / CU target
void matmul_kernel(const float* __restrict__ A,
                   const float* __restrict__ B,
                   float*       __restrict__ C,
                   const int    lda)                // == N
{
    // +1 column padding eliminates shared-memory bank conflicts
    __shared__ float As[TILE][TILE + 1];
    __shared__ float Bs[TILE][TILE + 1];

    // Local thread coordinates
    const int tx = threadIdx.x;              // 0..7
    const int ty = threadIdx.y;              // 0..7

    // Global coordinates of the 4×4 micro-tile this thread produces
    const int rowBase = (blockIdx.y * TILE) + (ty << 2);   // ty*4
    const int colBase = (blockIdx.x * TILE) + (tx << 2);   // tx*4

    // Register-resident accumulators
    float4 acc0{0.f, 0.f, 0.f, 0.f};
    float4 acc1{0.f, 0.f, 0.f, 0.f};
    float4 acc2{0.f, 0.f, 0.f, 0.f};
    float4 acc3{0.f, 0.f, 0.f, 0.f};

    // Iterate over all K-tiles
    for (int t = 0; t < lda; t += TILE)
    {
        // ---------------------------------------------------------------------
        // Cooperative, fully coalesced loads into LDS
        // ---------------------------------------------------------------------
        const int lane   = ty * THREADS_X + tx;   // 0..63
        const int offset = lane << 2;             // ×4 contiguous floats

        const int lrow = offset >> 5;             // /32  -> 0..31
        const int lcol = offset & 31;             // %32  -> 0..31

        // Global indices for the 4-float vector this thread reads
        const int gAr = blockIdx.y * TILE + lrow;
        const int gAc = t + lcol;

        const int gBr = t + lrow;
        const int gBc = blockIdx.x * TILE + lcol;

        const float4* srcA =
            reinterpret_cast<const float4*>(A + gAr * lda + gAc);
        const float4* srcB =
            reinterpret_cast<const float4*>(B + gBr * lda + gBc);

        // Vectorised global reads
        float4 aVec = *srcA;
        float4 bVec = *srcB;

        // Store into conflict-free LDS
        *reinterpret_cast<float4*>(&As[lrow][lcol]) = aVec;
        *reinterpret_cast<float4*>(&Bs[lrow][lcol]) = bVec;
        __syncthreads();

        // ---------------------------------------------------------------------
        // Compute this thread's 4×4 C sub-tile
        // ---------------------------------------------------------------------
        #pragma unroll
        for (int k = 0; k < TILE; ++k)
        {
            const float a0 = As[(ty << 2) + 0][k];
            const float a1 = As[(ty << 2) + 1][k];
            const float a2 = As[(ty << 2) + 2][k];
            const float a3 = As[(ty << 2) + 3][k];

            const float4 bRow =
                *reinterpret_cast<const float4*>(&Bs[k][tx << 2]);  // 4 cols

            acc0.x = fmaf(a0, bRow.x, acc0.x);
            acc0.y = fmaf(a0, bRow.y, acc0.y);
            acc0.z = fmaf(a0, bRow.z, acc0.z);
            acc0.w = fmaf(a0, bRow.w, acc0.w);

            acc1.x = fmaf(a1, bRow.x, acc1.x);
            acc1.y = fmaf(a1, bRow.y, acc1.y);
            acc1.z = fmaf(a1, bRow.z, acc1.z);
            acc1.w = fmaf(a1, bRow.w, acc1.w);

            acc2.x = fmaf(a2, bRow.x, acc2.x);
            acc2.y = fmaf(a2, bRow.y, acc2.y);
            acc2.z = fmaf(a2, bRow.z, acc2.z);
            acc2.w = fmaf(a2, bRow.w, acc2.w);

            acc3.x = fmaf(a3, bRow.x, acc3.x);
            acc3.y = fmaf(a3, bRow.y, acc3.y);
            acc3.z = fmaf(a3, bRow.z, acc3.z);
            acc3.w = fmaf(a3, bRow.w, acc3.w);
        }
        __syncthreads();
    }

    // -------------------------------------------------------------------------
    // Write back the 4×4 micro-tile
    // -------------------------------------------------------------------------
    float* dst0 = C + (rowBase + 0) * lda + colBase;
    float* dst1 = dst0 + lda;
    float* dst2 = dst1 + lda;
    float* dst3 = dst2 + lda;

    *reinterpret_cast<float4*>(dst0) = acc0;
    *reinterpret_cast<float4*>(dst1) = acc1;
    *reinterpret_cast<float4*>(dst2) = acc2;
    *reinterpret_cast<float4*>(dst3) = acc3;
}

