    dim3 block(THREADS_X, THREADS_Y);         // 8 × 8 = 64 threads
    dim3 grid (N / TILE,  N / TILE);

    hipLaunchKernelGGL(matmul_kernel, grid, block, 0, 0, dA, dB, dC, N);
    HIP_CHECK(hipGetLastError());
