// -----------------------------------------------------------------------------
// Tunables for gfx942  (wave = 64 threads)
// -----------------------------------------------------------------------------
constexpr int KERNEL_SZ  = 3;       // 3x3x3 window
constexpr int THREADS_BL = 256;     // 4 waves per block
constexpr int OUTS_PER_T = 2;       // contiguous outputs computed by a thread

// -----------------------------------------------------------------------------
// Utility: convert linear output index -> n,c,d,h,w
// -----------------------------------------------------------------------------
__device__ __forceinline__
void decode_out_idx(unsigned long long lin,
                    int Wo, int Ho, int Do, int C,
                    int &n, int &c, int &d, int &h, int &w)
{
    w =         lin % Wo;            lin /= Wo;
    h =         lin % Ho;            lin /= Ho;
    d =         lin % Do;            lin /= Do;
    c =         lin % C;             lin /= C;
    n = static_cast<int>(lin);
}

// -----------------------------------------------------------------------------
// Main 3-D max-pool kernel
// -----------------------------------------------------------------------------
__global__ __launch_bounds__(THREADS_BL, 2)
void maxpool3d_kernel(const float *__restrict__ in,
                      float *__restrict__ out,
                      int N, int C,
                      int Di, int Hi, int Wi,
                      int stride, int pad, int dil,
                      int Do, int Ho, int Wo)
{
    const unsigned long long tot_out =
        static_cast<unsigned long long>(N) * C * Do * Ho * Wo;

    const unsigned long long ltid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long first_idx = ltid * OUTS_PER_T;

    // Strides (input tensor)
    const unsigned long long sN = static_cast<unsigned long long>(C)  * Di * Hi * Wi;
    const unsigned long long sC = static_cast<unsigned long long>(Di) * Hi * Wi;
    const unsigned long long sD = static_cast<unsigned long long>(Hi) * Wi;
    const unsigned long long sH = Wi;

    // Grid-stride loop : each iteration handles OUTS_PER_T outputs
    for (; first_idx < tot_out; first_idx +=
         static_cast<unsigned long long>(gridDim.x) * blockDim.x * OUTS_PER_T)
    {
        int n0, c0, d0, h0, w0;
        decode_out_idx(first_idx, Wo, Ho, Do, C, n0, c0, d0, h0, w0);

        const bool have_second = (first_idx + 1ull) < tot_out;

        int n1 = n0, c1 = c0, d1 = d0, h1 = h0, w1 = w0 + 1;
        if (have_second && w1 == Wo) {
            w1 = 0; h1++;
            if (h1 == Ho) { h1 = 0; d1++;
                if (d1 == Do) { d1 = 0; c1++;
                    if (c1 == C) { c1 = 0; n1++; } } }
        }

        const float *base0 = in +
            static_cast<unsigned long long>(n0) * sN +
            static_cast<unsigned long long>(c0) * sC;
        const float *base1 = in +
            static_cast<unsigned long long>(n1) * sN +
            static_cast<unsigned long long>(c1) * sC;

        const int d_start0 = d0 * stride - pad;
        const int h_start0 = h0 * stride - pad;
        const int w_start0 = w0 * stride - pad;

        const int d_start1 = d1 * stride - pad;
        const int h_start1 = h1 * stride - pad;
        const int w_start1 = w1 * stride - pad;

        float max0 = -FLT_MAX;
        float max1 = -FLT_MAX;

        #pragma unroll
        for (int kd = 0; kd < KERNEL_SZ; ++kd) {
            const int id0 = d_start0 + kd * dil;
            const int id1 = d_start1 + kd * dil;
            const bool vd0 = (id0 >= 0 && id0 < Di);
            const bool vd1 = (id1 >= 0 && id1 < Di);
            if (!vd0 && !vd1) continue;

            const unsigned long long offD0 = static_cast<unsigned long long>(id0) * sD;
            const unsigned long long offD1 = static_cast<unsigned long long>(id1) * sD;

            #pragma unroll
            for (int kh = 0; kh < KERNEL_SZ; ++kh) {
                const int ih0 = h_start0 + kh * dil;
                const int ih1 = h_start1 + kh * dil;
                const bool vh0 = (ih0 >= 0 && ih0 < Hi);
                const bool vh1 = (ih1 >= 0 && ih1 < Hi);
                if (!vh0 && !vh1) continue;

                const unsigned long long offH0 = static_cast<unsigned long long>(ih0) * sH;
                const unsigned long long offH1 = static_cast<unsigned long long>(ih1) * sH;

                const float *row0 = base0 + offD0 + offH0;
                const float *row1 = base1 + offD1 + offH1;

                #pragma unroll
                for (int kw = 0; kw < KERNEL_SZ; ++kw) {
                    const int iw0 = w_start0 + kw * dil;
                    if (vd0 && vh0 && iw0 >= 0 && iw0 < Wi) {
                        float v = row0[iw0];
                        max0 = fmaxf(max0, v);
                    }

                    if (have_second) {
                        const int iw1 = w_start1 + kw * dil;
                        if (vd1 && vh1 && iw1 >= 0 && iw1 < Wi) {
                            float v = row1[iw1];
                            max1 = fmaxf(max1, v);
                        }
                    }
                }
            }
        }

        out[first_idx] = max0;
        if (have_second)
            out[first_idx + 1ull] = max1;
    }
}

