constexpr int   BLOCK_SIZE = 1024;          // 16 wavefronts
constexpr int   VEC_UNROLL = 4;             // process 4 x float4 per iteration
constexpr float EPSILON    = 1e-5f;

// -----------------------------------------------------------------------------
// LayerNorm kernel – more parallelism & unrolling
// -----------------------------------------------------------------------------
__global__ __launch_bounds__(BLOCK_SIZE, 1)
void layernorm_kernel(const float* __restrict__ x,
                      float*       __restrict__ y,
                      const float* __restrict__ gamma,
                      const float* __restrict__ beta,
                      int N)                     // elements per sample
{
    extern __shared__ float shm[];               // 2 * BLOCK_SIZE floats
    float* shm_sum   = shm;
    float* shm_sumsq = shm + blockDim.x;

    const int row        = blockIdx.x;           // sample index
    const size_t row_off = static_cast<size_t>(row) * N;
    const int tid        = threadIdx.x;

    // ---------------------------------------------------------------------
    // Pass 1 : accumulate statistics
    // ---------------------------------------------------------------------
    float local_sum   = 0.0f;
    float local_sumsq = 0.0f;

    const int n_vec      = N >> 2;               // # float4 items
    const int vec_stride = blockDim.x * VEC_UNROLL;
    const float4* x4_base = reinterpret_cast<const float4*>(x + row_off);

    int idx4 = tid;
#pragma unroll
    for (int u = 0; u < VEC_UNROLL; ++u) {
        if (idx4 < n_vec) {
            float4 v4 = x4_base[idx4];
            local_sum   += v4.x + v4.y + v4.z + v4.w;
            local_sumsq += v4.x*v4.x + v4.y*v4.y + v4.z*v4.z + v4.w*v4.w;
        }
        idx4 += blockDim.x;
    }

    for (int base = vec_stride + tid; base < n_vec; base += vec_stride) {
#pragma unroll
        for (int u = 0; u < VEC_UNROLL; ++u) {
            int pos = base + u * blockDim.x;
            if (pos < n_vec) {
                float4 v4 = x4_base[pos];
                local_sum   += v4.x + v4.y + v4.z + v4.w;
                local_sumsq += v4.x*v4.x + v4.y*v4.y + v4.z*v4.z + v4.w*v4.w;
            }
        }
    }

    // Remainder (<4 elements)
    for (int idx = (n_vec << 2) + tid; idx < N; idx += blockDim.x) {
        float v = x[row_off + idx];
        local_sum   += v;
        local_sumsq += v * v;
    }

    // Block reduction
    shm_sum  [tid] = local_sum;
    shm_sumsq[tid] = local_sumsq;
    __syncthreads();

    for (int offset = blockDim.x >> 1; offset > 0; offset >>= 1) {
        if (tid < offset) {
            shm_sum  [tid] += shm_sum  [tid + offset];
            shm_sumsq[tid] += shm_sumsq[tid + offset];
        }
        __syncthreads();
    }

    const float mean    = shm_sum[0]   / static_cast<float>(N);
    const float var     = shm_sumsq[0] / static_cast<float>(N) - mean * mean;
    const float inv_std = rsqrtf(var + EPSILON);
    __syncthreads();

    // ---------------------------------------------------------------------
    // Pass 2 : normalize & scale/shift
    // ---------------------------------------------------------------------
    const float4* g4_base = reinterpret_cast<const float4*>(gamma);
    const float4* b4_base = reinterpret_cast<const float4*>(beta);
    float4*       y4_base = reinterpret_cast<float4*>(y + row_off);

    idx4 = tid;
#pragma unroll
    for (int u = 0; u < VEC_UNROLL; ++u) {
        if (idx4 < n_vec) {
            float4 v4 = x4_base[idx4];

            v4.x = (v4.x - mean) * inv_std;
            v4.y = (v4.y - mean) * inv_std;
            v4.z = (v4.z - mean) * inv_std;
            v4.w = (v4.w - mean) * inv_std;

            float4 g4 = g4_base[idx4];
            float4 b4 = b4_base[idx4];

            v4.x = v4.x * g4.x + b4.x;
            v4.y = v4.y * g4.y + b4.y;
            v4.z = v4.z * g4.z + b4.z;
            v4.w = v4.w * g4.w + b4.w;

            y4_base[idx4] = v4;
        }
        idx4 += blockDim.x;
    }

    for (int base = vec_stride + tid; base < n_vec; base += vec_stride) {
#pragma unroll
        for (int u = 0; u < VEC_UNROLL; ++u) {
            int pos = base + u * blockDim.x;
            if (pos < n_vec) {
                float4 v4 = x4_base[pos];

                v4.x = (v4.x - mean) * inv_std;
                v4.y = (v4.y - mean) * inv_std;
                v4.z = (v4.z - mean) * inv_std;
                v4.w = (v4.w - mean) * inv_std;

                float4 g4 = g4_base[pos];
                float4 b4 = b4_base[pos];

                v4.x = v4.x * g4.x + b4.x;
                v4.y = v4.y * g4.y + b4.y;
                v4.z = v4.z * g4.z + b4.z;
                v4.w = v4.w * g4.w + b4.w;

                y4_base[pos] = v4;
            }
        }
    }

    for (int idx = (n_vec << 2) + tid; idx < N; idx += blockDim.x) {
        float v = (x[row_off + idx] - mean) * inv_std;
        y[row_off + idx] = v * gamma[idx] + beta[idx];
    }
}

// -----------------------------------------------------------------------------
// Host helper
// -----------------------------------------------------------------------------
void layernorm_forward(const float* h_x,
                       float*       h_y,
                       const float* h_gamma,
                       const float* h_beta,
                       int M,        // batch size
                       int N)        // elements per sample
{
    const size_t data_bytes  = static_cast<size_t>(M) * N * sizeof(float);
    const size_t param_bytes = static_cast<size_t>(N) * sizeof(float);

    float *d_x=nullptr, *d_y=nullptr, *d_gamma=nullptr, *d_beta=nullptr;

    CHECK(hipMalloc(&d_x,     data_bytes));
    CHECK(hipMalloc(&d_y,     data_bytes));
    CHECK(hipMalloc(&d_gamma, param_bytes));
    CHECK(hipMalloc(&d_beta,  param_bytes));

    CHECK(hipMemcpy(d_x,     h_x,     data_bytes,  hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_gamma, h_gamma, param_bytes, hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_beta,  h_beta,  param_bytes, hipMemcpyHostToDevice));

    dim3 grid(M);
    size_t shmem_bytes = 2 * BLOCK_SIZE * sizeof(float);

    hipLaunchKernelGGL(layernorm_kernel, grid, BLOCK_SIZE, shmem_bytes, 0,
                       d_x, d_y, d_gamma, d_beta, N);
    CHECK(hipGetLastError());

    CHECK(hipMemcpy(h_y, d_y, data_bytes, hipMemcpyDeviceToHost));

    CHECK(hipFree(d_x));
    CHECK(hipFree(d_y));
    CHECK(hipFree(d_gamma));
    CHECK(hipFree(d_beta));
}

