constexpr int THREADS_PER_BLOCK = 256;  // 4 full wavefronts on gfx942

__device__ __forceinline__ float softsign(float x) {
    return x / (1.0f + fabsf(x));
}

template<bool VEC4>
__launch_bounds__(THREADS_PER_BLOCK, 4)
__global__ void softsign_kernel(const float* __restrict__ in,
                                float* __restrict__ out,
                                size_t n)
{
    constexpr int VEC_LEN = VEC4 ? 4 : 1;
    const size_t gid = blockIdx.x * blockDim.x + threadIdx.x;
    const size_t gsz = gridDim.x * blockDim.x;

    if constexpr (VEC4) {
        const size_t vecN = n / VEC_LEN;  // number of float4s
        const float4* __restrict__ vin  = reinterpret_cast<const float4*>(in);
        float4* __restrict__ vout       = reinterpret_cast<float4*>(out);

        for (size_t i = gid; i < vecN; i += gsz) {
            float4 v = vin[i];
#pragma unroll
            for (int k = 0; k < 4; ++k) {
                reinterpret_cast<float*>(&v)[k] =
                    softsign(reinterpret_cast<float*>(&v)[k]);
            }
            vout[i] = v;
        }

        // process remaining scalars if n not multiple of 4
        const size_t remStart = vecN * VEC_LEN;
        for (size_t i = remStart + gid; i < n; i += gsz) {
            out[i] = softsign(in[i]);
        }
    } else {
        for (size_t i = gid; i < n; i += gsz) {
            out[i] = softsign(in[i]);
        }
    }
}

int main() {
    constexpr int batch = 16;
    constexpr int dim   = 16384;
    const size_t N      = static_cast<size_t>(batch) * dim;
    const size_t bytes  = N * sizeof(float);

    // Host buffers
    std::vector<float> h_in(N);
    std::vector<float> h_out(N);

    std::mt19937 rng(42);
    std::uniform_real_distribution<float> dist(-10.0f, 10.0f);
    for (size_t i = 0; i < N; ++i) h_in[i] = dist(rng);

    // Device buffers
    float *d_in = nullptr, *d_out = nullptr;
    HIP_CHECK(hipMalloc(&d_in,  bytes));
    HIP_CHECK(hipMalloc(&d_out, bytes));

    HIP_CHECK(hipMemcpy(d_in, h_in.data(), bytes, hipMemcpyHostToDevice));

    // Decide whether we can use vectorized kernel (16-byte alignment)
    bool vecOK = (reinterpret_cast<uintptr_t>(d_in)  & 0xF) == 0 &&
                 (reinterpret_cast<uintptr_t>(d_out) & 0xF) == 0;

    // Calculate launch configuration
    const int blocks = static_cast<int>((N + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK);

    if (vecOK) {
        hipLaunchKernelGGL(HIP_KERNEL_NAME(softsign_kernel<true>),
                           dim3(blocks), dim3(THREADS_PER_BLOCK), 0, 0,
                           d_in, d_out, N);
    } else {
        hipLaunchKernelGGL(HIP_KERNEL_NAME(softsign_kernel<false>),
                           dim3(blocks), dim3(THREADS_PER_BLOCK), 0, 0,
                           d_in, d_out, N);
    }
    HIP_CHECK(hipGetLastError());

    HIP_CHECK(hipMemcpy(h_out.data(), d_out, bytes, hipMemcpyDeviceToHost));

    bool ok = true;
    for (size_t i = 0; i < N; ++i) {
        float ref = h_in[i] / (1.0f + fabsf(h_in[i]));
        if (fabsf(ref - h_out[i]) > 1e-5f) {
            printf("Mismatch @ %zu: %f vs %f\n", i, ref, h_out[i]);
            ok = false;
            break;
        }
    }
    printf(ok ? "PASSED\n" : "FAILED\n");

    HIP_CHECK(hipFree(d_in));
    HIP_CHECK(hipFree(d_out));
    return ok ? 0 : 1;
}

