constexpr float kSlope = 1.0f / 6.0f;  // 0.16666667f

__device__ __forceinline__ float hardsigmoid_scalar(float x) {
  x = x * kSlope + 0.5f;
  x = fmaxf(0.0f, x);
  x = fminf(1.0f, x);
  return x;
}

__global__ __launch_bounds__(256, 4)
void hardsigmoid_vec4_kernel(const float* __restrict__ in,
                             float* __restrict__ out,
                             int n) {
  constexpr int VEC = 4;
  using vec_t = float4;

  int tid     = blockIdx.x * blockDim.x + threadIdx.x;
  int stride  = gridDim.x * blockDim.x;

  for (int vec_idx = tid; vec_idx * VEC < n; vec_idx += stride) {
    int base = vec_idx * VEC;

    if (base + VEC - 1 < n) {
      vec_t v = *reinterpret_cast<const vec_t*>(in + base);

      v.x = hardsigmoid_scalar(v.x);
      v.y = hardsigmoid_scalar(v.y);
      v.z = hardsigmoid_scalar(v.z);
      v.w = hardsigmoid_scalar(v.w);

      *reinterpret_cast<vec_t*>(out + base) = v;
    } else {  // tail
      for (int i = base; i < n; ++i) {
        out[i] = hardsigmoid_scalar(in[i]);
      }
    }
  }
}

