constexpr int THREADS_PER_BLOCK = 256;   // multiple of 64 for full wave utilisation
constexpr int VEC               = 4;     // each thread computes VEC output elements

/*  Kernel implements 1-D transposed convolution.

    – each thread computes up to VEC output points that are strided by blockDim.x
    – linearised indexing (n, oc, xout) → contiguous xout per wave -> coalesced writes
    – read-only data (in, weight, bias) accessed via __ldg to leverage L2/RD caches
*/
template<int V>
__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void conv1d_transpose_kernel(const float* __restrict__ in,      // [N, Cin, Lin]
                             const float* __restrict__ weight,  // [Cin, Cout, K]  (Cin major, K minor)
                             const float* __restrict__ bias,    // [Cout] or nullptr
                             float* __restrict__ out,           // [N, Cout, Lout]
                             int N,
                             int Cin,
                             int Lin,
                             int Cout,
                             int K,
                             int stride,
                             int padding,
                             int dilation,
                             int Lout)
{
    const long long total_elems = static_cast<long long>(N) * Cout * Lout;

    // starting logical element for this thread-vector
    long long linear_base = (static_cast<long long>(blockIdx.x) * blockDim.x + threadIdx.x) * V;

    #pragma unroll
    for (int v = 0; v < V; ++v) {
        long long linear_idx = linear_base + v;
        if (linear_idx >= total_elems) continue;

        // decode linear index -> (n, oc, xout)
        long long tmp  = linear_idx;
        int n          = tmp / (Cout * static_cast<long long>(Lout));
        tmp           -= static_cast<long long>(n) * Cout * Lout;
        int oc         = tmp / Lout;
        int xout       = tmp - oc * Lout;

        float acc = bias ? __ldg(&bias[oc]) : 0.0f;

        // accumulate over input channels and kernel taps
        for (int ic = 0; ic < Cin; ++ic) {
            const float* w_ptr = weight + (ic * Cout + oc) * K;         // contiguous K
            const float* in_ptr = in + (static_cast<long long>(n) * Cin + ic) * Lin;

            #pragma unroll
            for (int k = 0; k < K; ++k) {
                int numer = xout + padding - k * dilation;
                if (numer < 0)            continue;
                if (numer % stride != 0)  continue;

                int xin = numer / stride;
                if (xin >= Lin)           continue;

                acc += __ldg(&in_ptr[xin]) * __ldg(&w_ptr[k]);
            }
        }

        out[linear_idx] = acc;
    }
}

