constexpr int   WAVE             = 64;
constexpr int   BLOCK_SIZE       = 256;
constexpr int   BLOCKS_PER_CH    = 8;          // increase parallelism
constexpr float EPS              = 1e-5f;

/* -------------------------------------------------------------------------- */
/*  Kernel 1: accumulate per–channel partial sums/ square sums                */
/* -------------------------------------------------------------------------- */
__launch_bounds__(BLOCK_SIZE, 2)
__global__ void compute_stats_partial_kernel(const float* __restrict__ x,
                                             float* __restrict__ g_sum,
                                             float* __restrict__ g_sq,
                                             int   N, int C, int H, int W)
{
    const int c   = blockIdx.x;          // channel handled
    const int blk = blockIdx.y;          // reduction-block id 0..BLOCKS_PER_CH-1

    const size_t elems_per_ch = static_cast<size_t>(N) * H * W;
    const size_t chunk        = (elems_per_ch + gridDim.y - 1) / gridDim.y;
    const size_t start        = blk * chunk;
    const size_t end          = min(start + chunk, elems_per_ch);

    float thread_sum    = 0.0f;
    float thread_sq_sum = 0.0f;

    for (size_t idx = start + threadIdx.x; idx < end; idx += blockDim.x) {
        size_t n  = idx / (H * W);
        size_t hw = idx % (H * W);
        size_t h  = hw / W;
        size_t w  = hw % W;

        size_t g_idx = (((static_cast<size_t>(n) * C + c) * H + h) * W) + w;

        float v      = x[g_idx];
        thread_sum   += v;
        thread_sq_sum += v * v;
    }

    __shared__ float sh_sum[BLOCK_SIZE];
    __shared__ float sh_sq [BLOCK_SIZE];
    sh_sum[threadIdx.x] = thread_sum;
    sh_sq [threadIdx.x] = thread_sq_sum;
    __syncthreads();

    // reduction within block
    for (int stride = BLOCK_SIZE >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sh_sum[threadIdx.x] += sh_sum[threadIdx.x + stride];
            sh_sq [threadIdx.x] += sh_sq [threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        atomicAdd(g_sum + c, sh_sum[0]);
        atomicAdd(g_sq  + c, sh_sq [0]);
    }
}

/* -------------------------------------------------------------------------- */
/*  Kernel 2: finalize mean/var and build scale & bias                        */
/* -------------------------------------------------------------------------- */
__launch_bounds__(BLOCK_SIZE, 4)
__global__ void finalize_params_kernel(const float* __restrict__ g_sum,
                                       const float* __restrict__ g_sq,
                                       const float* __restrict__ gamma,
                                       const float* __restrict__ beta,
                                       float* __restrict__ scale,
                                       float* __restrict__ bias,
                                       int N, int H, int W,
                                       int C,
                                       float eps)
{
    const int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;

    const float inv_cnt = 1.0f / static_cast<float>(N * H * W);
    const float mean    = g_sum[c] * inv_cnt;
    const float var     = g_sq[c]  * inv_cnt - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    scale[c] = gamma[c] * inv_std;
    bias [c] = beta [c] - mean * scale[c];
}

/* -------------------------------------------------------------------------- */
/*  Kernel 3: y = x * scale[c] + bias[c]                                      */
/* -------------------------------------------------------------------------- */
__launch_bounds__(BLOCK_SIZE, 4)
__global__ void batchnorm_apply_kernel(const float* __restrict__ x,
                                       float* __restrict__ y,
                                       const float* __restrict__ scale,
                                       const float* __restrict__ bias,
                                       size_t total_elems,
                                       int C, int H, int W)
{
    for (size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
         idx < total_elems;
         idx += static_cast<size_t>(blockDim.x) * gridDim.x)
    {
        int c   = static_cast<int>((idx / (H * W)) % C);
        y[idx] = x[idx] * scale[c] + bias[c];
    }
}

/* ========================================================================== */
/*  Minimal host stub                                                         */
/* ========================================================================== */
int main()
{
    const int N = 16;
    const int C = 64;
    const int H = 256;
    const int W = 256;

    const size_t total_elems   = static_cast<size_t>(N) * C * H * W;
    const size_t bytes_tensor  = total_elems * sizeof(float);
    const size_t bytes_channel = C * sizeof(float);

    /* ------------------------- host allocations --------------------------- */
    std::vector<float> h_x(total_elems);
    std::vector<float> h_gamma(C, 1.0f);
    std::vector<float> h_beta (C, 0.0f);
    std::vector<float> h_y(total_elems);

    for (size_t i = 0; i < total_elems; ++i)
        h_x[i] = static_cast<float>(rand()) / (static_cast<float>(RAND_MAX) + 1.0f);

    /* ------------------------- device allocations ------------------------- */
    float *d_x, *d_y, *d_gamma, *d_beta, *d_scale, *d_bias, *d_sum, *d_sq;
    HIP_CHECK(hipMalloc(&d_x,     bytes_tensor));
    HIP_CHECK(hipMalloc(&d_y,     bytes_tensor));
    HIP_CHECK(hipMalloc(&d_gamma, bytes_channel));
    HIP_CHECK(hipMalloc(&d_beta,  bytes_channel));
    HIP_CHECK(hipMalloc(&d_scale, bytes_channel));
    HIP_CHECK(hipMalloc(&d_bias,  bytes_channel));
    HIP_CHECK(hipMalloc(&d_sum,   bytes_channel));
    HIP_CHECK(hipMalloc(&d_sq,    bytes_channel));

    HIP_CHECK(hipMemcpy(d_x,     h_x.data(),     bytes_tensor,  hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_gamma, h_gamma.data(), bytes_channel, hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_beta,  h_beta.data(),  bytes_channel, hipMemcpyHostToDevice));
    HIP_CHECK(hipMemset(d_sum,  0, bytes_channel));
    HIP_CHECK(hipMemset(d_sq,   0, bytes_channel));

    /* ------------------------- Kernel 1 : partial reductions -------------- */
    dim3 grid_stats(C, BLOCKS_PER_CH);
    dim3 block_stats(BLOCK_SIZE);

    hipLaunchKernelGGL(compute_stats_partial_kernel,
                       grid_stats,
                       block_stats,
                       0,
                       0,
                       d_x,
                       d_sum,
                       d_sq,
                       N, C, H, W);
    HIP_CHECK(hipGetLastError());

    /* ------------------------- Kernel 2 : finalize params ----------------- */
    dim3 grid_final((C + BLOCK_SIZE - 1) / BLOCK_SIZE);
    hipLaunchKernelGGL(finalize_params_kernel,
                       grid_final,
                       block_stats,
                       0,
                       0,
                       d_sum,
                       d_sq,
                       d_gamma,
                       d_beta,
                       d_scale,
                       d_bias,
                       N, H, W, C,
                       EPS);
    HIP_CHECK(hipGetLastError());

    /* ------------------------- Kernel 3 : apply --------------------------- */
    const int APPLY_BLOCK = BLOCK_SIZE;
    const int APPLY_GRID  = 8192; // sufficient for large tensors

    hipLaunchKernelGGL(batchnorm_apply_kernel,
                       dim3(APPLY_GRID),
                       dim3(APPLY_BLOCK),
                       0,
                       0,
                       d_x,
                       d_y,
                       d_scale,
                       d_bias,
                       total_elems,
                       C, H, W);
    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    /* ------------------------- copy back & clean -------------------------- */
    HIP_CHECK(hipMemcpy(h_y.data(), d_y, bytes_tensor, hipMemcpyDeviceToHost));

    HIP_CHECK(hipFree(d_x));
    HIP_CHECK(hipFree(d_y));
    HIP_CHECK(hipFree(d_gamma));
    HIP_CHECK(hipFree(d_beta));
    HIP_CHECK(hipFree(d_scale));
    HIP_CHECK(hipFree(d_bias));
    HIP_CHECK(hipFree(d_sum));
    HIP_CHECK(hipFree(d_sq));

    printf("Optimized BatchNorm forward completed.\n");
    return 0;
}

