/*  ---------------------------------  kernel  ------------------------------- */
__launch_bounds__(256, 2)
__global__ void conv1d_transpose_kernel(
        const float* __restrict__ input,     // [N, C_in, L_in]
        const float* __restrict__ weight,    // [C_in, C_out, K]
        const float* __restrict__ bias,      // [C_out]  (can be nullptr)
        float*       __restrict__ output,    // [N, C_out, L_out]
        int  N,
        int  C_in,
        int  C_out,
        int  L_in,
        int  K,
        int  stride,
        int  padding,
        int  dilation,
        int  L_out)
{
    /* thread coordinates */
    const int out_idx = blockIdx.x * blockDim.x + threadIdx.x;  // spatial
    const int c_out   = blockIdx.y * blockDim.y + threadIdx.y;  // channel
    const int n       = blockIdx.z;                             // batch

    if (out_idx >= L_out || c_out >= C_out) return;

    float acc = 0.0f;

    /* iterate kernel taps and input channels */
    for (int k = 0; k < K; ++k)
    {
        int t = out_idx + padding - k * dilation;
        if (t < 0) continue;

        /* ensure t aligns with stride */
        if ((t % stride) != 0) continue;
        int in_idx = t / stride;
        if (in_idx >= L_in) continue;

        const int in_base = (n * C_in * L_in) + in_idx;   // position of c_in=0
        const int w_k_offset = k;                         // k is innermost dim

        for (int c_in = 0; c_in < C_in; ++c_in)
        {
            float in_val = input[in_base + c_in * L_in];  // contiguous along idx
            int   w_idx  = ((c_in * C_out) + c_out) * K + w_k_offset;
            float w_val  = weight[w_idx];
            acc += in_val * w_val;
        }
    }

    if (bias != nullptr)
        acc += bias[c_out];

    output[((n * C_out + c_out) * L_out) + out_idx] = acc;
}

