    const size_t weight_size = static_cast<size_t>(C_in) * C_out * K * sizeof(float);
    const size_t bias_size   = static_cast<size_t>(C_out) * sizeof(float);

    /* allocate & init host memory */
    float *h_in     = (float*)std::malloc(in_size);
    float *h_weight = (float*)std::malloc(weight_size);
    float *h_bias   = use_bias ? (float*)std::malloc(bias_size) : nullptr;
