    if (use_bias) CHECK(hipMalloc(&d_bias, bias_size));

    CHECK(hipMemcpy(d_in,     h_in,     in_size,     hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_weight, h_weight, weight_size, hipMemcpyHostToDevice));
    if (use_bias) CHECK(hipMemcpy(d_bias, h_bias, bias_size, hipMemcpyHostToDevice));

    /* launch configuration */
    dim3 block(64, 4, 1);   // 256 threads
    dim3 grid( (L_out  + block.x - 1) / block.x,
               (C_out  + block.y - 1) / block.y,
