    hipLaunchKernelGGL(conv1d_transpose_kernel, grid, block, 0, 0,
                       d_in, d_weight, use_bias ? d_bias : nullptr, d_out,
                       N, C_in, C_out, L_in, K,
                       stride, padding, dilation, L_out);

    CHECK(hipMemcpy(h_out, d_out, out_size, hipMemcpyDeviceToHost));

    /* simple correctness check */
    double checksum = 0.0;
    for (size_t i = 0; i < out_size / sizeof(float); ++i) checksum += h_out[i];
    printf("Output checksum: %lf\n", checksum);

    CHECK(hipFree(d_in));
    CHECK(hipFree(d_weight));
    CHECK(hipFree(d_out));
    if (use_bias) CHECK(hipFree(d_bias));

    std::free(h_in);
    std::free(h_weight);
    std::free(h_out);
    if (use_bias) std::free(h_bias);

    return 0;
}

