static inline int div_up(int a, int b) { return (a + b - 1) / b; }

// ---------------------------------------------------------------------------
// Vectorised grid-stride kernel (computes VEC consecutive output elements)
// – same algorithm as the first attempt, but slightly cleaner
// – hipFree warnings fixed on host side (CHECK wrapper)
// ---------------------------------------------------------------------------
template<int VEC>
__global__ __launch_bounds__(256, 2)
void conv_transpose2d_kernel_vec(const float *__restrict__ input,   // N, Ci, Hi, Wi
                                 const float *__restrict__ weight,  // Ci, CoG, Kh, Kw
                                 const float *__restrict__ bias,    // Co or nullptr
                                 float       *__restrict__ output,  // N, Co, Ho, Wo
                                 const int N,
                                 const int Ci, const int Co,
                                 const int Hi, const int Wi,
                                 const int Ho, const int Wo,
                                 const int Kh, const int Kw,
                                 const int stride_h, const int stride_w,
                                 const int pad_h, const int pad_w,
                                 const int out_pad_h, const int out_pad_w,
                                 const int dilation_h, const int dilation_w,
                                 const int groups,
                                 const int has_bias,
                                 const long total_outputs_vec)       // = ceil(N*Co*Ho*Wo / VEC)
{
    const int Co_per_group = Co / groups;
    const int Ci_per_group = Ci / groups;

    const long thd_stride = (long)blockDim.x * gridDim.x;       // threads in grid
    const long vec_stride = thd_stride;                         // VEC handled per thread step

    long tid = (long)blockIdx.x * blockDim.x + threadIdx.x;

    for (long base_vec = tid; base_vec < total_outputs_vec; base_vec += thd_stride)
    {
#pragma unroll
        for (int v = 0; v < VEC; ++v)
        {
            long lin = base_vec * VEC + v;
            if (lin >= (long)N * Co * Ho * Wo) break;

            // De-linearise output index
            int wo = lin % Wo;
            lin   /= Wo;
            int ho = lin % Ho;
            lin   /= Ho;
            int co = lin % Co;
            int n  = lin / Co;

            int g             = (co * groups) / Co;
            int co_in_group   = co - g * Co_per_group;
            int ci_group_base = g * Ci_per_group;

            float acc = has_bias ? bias[co] : 0.f;

