                    if (wo_p < 0)          continue;
                    if (wo_p % stride_w)   continue;
                    int wi = wo_p / stride_w;
                    if (wi >= Wi)          continue;

                    const int inp_base = ((n * Ci) * Hi + hi) * Wi + wi;
                    const int w_khkw   = kh * Kw + kw;
                    const int w_spatial_stride = Kh * Kw;

                    // loop Ci with unroll-4
                    int ci = 0;
                    const int w_group_stride = Co_per_group * w_spatial_stride;
#pragma unroll 4
                    for (; ci + 3 < Ci_per_group; ci += 4)
                    {
                        int ci0 = ci_group_base + ci + 0;
                        int ci1 = ci_group_base + ci + 1;
                        int ci2 = ci_group_base + ci + 2;
                        int ci3 = ci_group_base + ci + 3;

                        float in0 = input[inp_base + ci0 * Hi * Wi];
                        float in1 = input[inp_base + ci1 * Hi * Wi];
                        float in2 = input[inp_base + ci2 * Hi * Wi];
                        float in3 = input[inp_base + ci3 * Hi * Wi];

                        long w_base0 = ((long)ci0 * Co_per_group + co_in_group) * w_spatial_stride + w_khkw;
                        float w0 = weight[w_base0];
                        float w1 = weight[w_base0 +        w_group_stride];
                        float w2 = weight[w_base0 + 2LL *  w_group_stride];
                        float w3 = weight[w_base0 + 3LL *  w_group_stride];

