/*  Cosine-similarity loss
 *  One block  : one sample (vector length = vec_dim)
 *  256 threads: 4 full wavefronts ⇒ good latency hiding
 *  Vectorized loads (float4)     : better global-mem BW utilisation
 *  Shared memory reduction       : no global atomics inside loop
 */
template <int THREADS>
__launch_bounds__(THREADS)
__global__ void cosine_loss_kernel(const float* __restrict__ pred,
                                   const float* __restrict__ targ,
                                   int  vec_dim,
                                   float* __restrict__ loss_sum)
{
    extern __shared__ float smem[];
    float* dot_s   = smem;                 // THREADS elements
    float* normp_s = smem + THREADS;       // THREADS elements
    float* normt_s = smem + THREADS * 2;   // THREADS elements

    const int tid       = threadIdx.x;
    const int sample_id = blockIdx.x;
    const int base_idx  = sample_id * vec_dim;

    // Vectorised pointers (16-byte aligned because 4096*4 = 16384 is divisible by 16)
    const float4* __restrict__ p4 = reinterpret_cast<const float4*>(pred + base_idx);
    const float4* __restrict__ t4 = reinterpret_cast<const float4*>(targ + base_idx);

    const int vec4_cnt   = vec_dim >> 2;         // /4
    const int leftover   = vec_dim & 3;          // remaining 0-3 elements

    float dot   = 0.0f;
    float normp = 0.0f;
    float normt = 0.0f;

    // Main loop – float4 loads
    for (int i = tid; i < vec4_cnt; i += THREADS) {
        float4 pv = p4[i];
        float4 tv = t4[i];

        dot   += pv.x * tv.x + pv.y * tv.y + pv.z * tv.z + pv.w * tv.w;
        normp += pv.x * pv.x + pv.y * pv.y + pv.z * pv.z + pv.w * pv.w;
        normt += tv.x * tv.x + tv.y * tv.y + tv.z * tv.z + tv.w * tv.w;
    }

    // Handle tail elements (<=3) – first THREADS threads cover them in coalesced fashion
    if (tid < leftover) {
        int idx = (vec4_cnt << 2) + tid;      // vec4_cnt*4 + tid
        float p = pred[base_idx + idx];
        float t = targ[base_idx + idx];
        dot   += p * t;
        normp += p * p;
        normt += t * t;
    }

    // Store partials to shared memory
    dot_s[tid]   = dot;
    normp_s[tid] = normp;
    normt_s[tid] = normt;

    __syncthreads();

    // Parallel reduction in shared memory (power-of-two THREADS)
    for (int stride = THREADS >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            dot_s[tid]   += dot_s[tid + stride];
            normp_s[tid] += normp_s[tid + stride];
            normt_s[tid] += normt_s[tid + stride];
        }
        __syncthreads();
    }

    // Thread 0 of each block finishes sample loss and atomically accumulates
    if (tid == 0) {
        const float  eps     = 1e-8f;
        const float  denom   = sqrtf(normp_s[0]) * sqrtf(normt_s[0]) + eps;
        const float  cosine  = dot_s[0] / denom;
        const float  loss    = 1.0f - cosine;
        atomicAdd(loss_sum, loss);
    }
}

