__launch_bounds__(256, 4)
__global__ void softplus_kernel_vec(const float* __restrict__ in,
                                    float*       __restrict__ out,
                                    const int n_elements)
{
    const int n_vec   = n_elements >> 2;               // #float4 units (assumes n % 4 == 0)
