        float4 v = in4[idx];         // Coalesced 16-byte load
        v.x = softplus_scalar(v.x);
        v.y = softplus_scalar(v.y);
        v.z = softplus_scalar(v.z);
        v.w = softplus_scalar(v.w);
        out4[idx] = v;               // Coalesced 16-byte store
    }
}

