        const int d2 = idx % D2;

        const size_t base = (static_cast<size_t>(b) * D1) * D2 + d2;

        float local_min = FLT_MAX;
        for (int d1 = tid; d1 < D1; d1 += BLOCK_THREADS) {
            float v = input[base + static_cast<size_t>(d1) * D2];
            local_min = fminf(local_min, v);
        }
        local_min = warp_min(local_min);
        if (tid == 0) output[idx] = local_min;
    }
    else { // dim == 2
        const int outer = B * D1;
        const int idx   = blockIdx.x;
        if (idx >= outer) return;

        const int b  = idx / D1;
        const int d1 = idx % D1;

        const float* row = input + (static_cast<size_t>(b) * D1 + d1) * D2;

        float local_min = FLT_MAX;
        for (int d2 = tid; d2 < D2; d2 += BLOCK_THREADS) {
            float v = row[d2];
            local_min = fminf(local_min, v);
        }
        local_min = warp_min(local_min);
        if (tid == 0) output[idx] = local_min;
    }
}

int main(int argc, char* argv[])
{
    int dim = 0;
    if (argc > 1) dim = std::atoi(argv[1]);
    if (dim < 0 || dim > 2) {
        fprintf(stderr, "Reduce dim must be 0, 1 or 2\n");
        return EXIT_FAILURE;
    }

    const int B  = 16;
    const int D1 = 256;
    const int D2 = 256;

    const size_t num_elems = static_cast<size_t>(B) * D1 * D2;
    std::vector<float> h_in(num_elems);

    std::mt19937 gen(123);
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
    for (size_t i = 0; i < num_elems; ++i) h_in[i] = dist(gen);

    float *d_in, *d_out;
    HIP_CHECK(hipMalloc(&d_in, num_elems * sizeof(float)));
    HIP_CHECK(hipMemcpy(d_in, h_in.data(), num_elems * sizeof(float),
                        hipMemcpyHostToDevice));

    size_t out_elems = (dim == 0) ? static_cast<size_t>(D1) * D2
                     : (dim == 1) ? static_cast<size_t>(B) * D2
                                  : static_cast<size_t>(B) * D1;

    HIP_CHECK(hipMalloc(&d_out, out_elems * sizeof(float)));

    const int block_threads = 64;
    const int grid_size     = static_cast<int>(out_elems);

    hipLaunchKernelGGL(HIP_KERNEL_NAME(min_reduce_dim_kernel<block_threads>),
                       dim3(grid_size), dim3(block_threads), 0, 0,
                       d_in, d_out, B, D1, D2, dim);
    HIP_CHECK(hipDeviceSynchronize());

    std::vector<float> h_out(out_elems);
    HIP_CHECK(hipMemcpy(h_out.data(), d_out, out_elems * sizeof(float),
                        hipMemcpyDeviceToHost));

    for (size_t i = 0; i < 10 && i < h_out.size(); ++i)
        printf("%f ", h_out[i]);
    printf("\n");

    HIP_CHECK(hipFree(d_in));
    HIP_CHECK(hipFree(d_out));
    return 0;
}

#include <hip/hip_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cmath>

#define KH           3        // kernel height  (must match PyTorch model)
#define KW           5        // kernel width
#define VEC          4        // output elements along X per thread
#define BLOCK_W      16       // threads along X  (BLOCK_W * VEC outputs per block-x)
#define BLOCK_H      8        // threads along Y
#define THREADS      (BLOCK_W * BLOCK_H)

#define TILE_H       (BLOCK_H + KH - 1)
#define TILE_W       (BLOCK_W * VEC + KW - 1)

#define HIP_CHECK(cmd) do {                                         \
    hipError_t _e = (cmd);                                          \
    if (_e != hipSuccess) {                                         \
        printf("HIP error %s:%d  %s\n", __FILE__, __LINE__,         \
               hipGetErrorString(_e));                              \
        exit(EXIT_FAILURE);                                         \
    }                                                               \
} while (0)

__global__ __launch_bounds__(THREADS, 4)
void conv2d_kernel_tiled(const float* __restrict__ input,   // [B,Cin,H,W]
                         const float* __restrict__ weight,  // [Cout,Cin,KH,KW]
                         float*       __restrict__ output,  // [B,Cout,Hout,Wout]
                         int B, int Cin, int Cout,
                         int H, int W,
                         int Hout, int Wout)
{
    __shared__ float tile   [TILE_H][TILE_W];   // input tile
    __shared__ float w_sh   [KH][KW];           // kernel weights for (co,ci)

    const int tx = threadIdx.x;                 // 0 .. BLOCK_W-1
    const int ty = threadIdx.y;                 // 0 .. BLOCK_H-1

    const int out_x_start = (blockIdx.x * BLOCK_W + tx) * VEC;
    const int out_y       =  blockIdx.y * BLOCK_H + ty;

    const int bz = blockIdx.z;                  // fused (b,co)
    const int b  = bz / Cout;
    const int co = bz - b * Cout;

    if (b >= B || co >= Cout || out_y >= Hout)  return;

    float acc[VEC] = {0.f};

    /* ---------- loop over input channels ----------------------------- */
    for (int ci = 0; ci < Cin; ++ci)
    {
        /* cooperative load of weights into LDS ------------------------ */
        if (ty < KH && tx < KW)
            w_sh[ty][tx] = weight[((co * Cin + ci) * KH + ty) * KW + tx];
        __syncthreads();

        /* load input tile to LDS -------------------------------------- */
        const float* in_plane = input + ((b * Cin + ci) * H) * W;

        const int in_x0 = blockIdx.x * BLOCK_W * VEC;
        const int in_y0 = blockIdx.y * BLOCK_H;

        for (int ly = ty; ly < TILE_H; ly += BLOCK_H)
        {
            const int in_y = in_y0 + ly;
            const bool y_valid = (in_y < H);

            for (int lx = tx; lx < TILE_W; lx += BLOCK_W)
            {
                const int in_x = in_x0 + lx;
                const bool x_valid = (in_x < W);

                tile[ly][lx] = (x_valid && y_valid) ? in_plane[in_y * W + in_x] : 0.f;
            }
        }
        __syncthreads();

        /* compute partial sums ---------------------------------------- */
        if (out_x_start < Wout)
        {
            #pragma unroll
            for (int kh = 0; kh < KH; ++kh)
            {
                const float* t_row = &tile[ty + kh][tx * VEC];

                #pragma unroll
                for (int kw = 0; kw < KW; ++kw)
                {
                    const float w = w_sh[kh][kw];

                    #pragma unroll
                    for (int vx = 0; vx < VEC; ++vx)
                    {
                        const int ox = out_x_start + vx;
                        if (ox < Wout)
                            acc[vx] += t_row[kw + vx] * w;
                    }
                }
            }
        }
        __syncthreads(); // make sure LDS not in flight before next ci
    }

    /* write results --------------------------------------------------- */
    #pragma unroll
    for (int vx = 0; vx < VEC; ++vx)
    {
        const int ox = out_x_start + vx;
        if (ox < Wout)
            output[((b * Cout + co) * Hout + out_y) * Wout + ox] = acc[vx];
    }
}

