int main()
{
    const int B    = 16;
    const int Cin  = 3;
    const int Cout = 64;
    const int H    = 256;
    const int W    = 256;

    const int Hout = H - KH + 1;   // stride=1, padding=0
    const int Wout = W - KW + 1;

    const size_t in_bytes  = (size_t)B * Cin  * H    * W    * sizeof(float);
    const size_t wt_bytes  = (size_t)Cout * Cin * KH * KW   * sizeof(float);
    const size_t out_bytes = (size_t)B * Cout * Hout * Wout * sizeof(float);

    float* h_in  = (float*)malloc(in_bytes);
    float* h_wt  = (float*)malloc(wt_bytes);
    float* h_out = (float*)malloc(out_bytes);

    for (size_t i = 0; i < in_bytes / sizeof(float);  ++i)
        h_in[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    for (size_t i = 0; i < wt_bytes / sizeof(float);  ++i)
        h_wt[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);

    float *d_in, *d_wt, *d_out;
    HIP_CHECK( hipMalloc(&d_in , in_bytes) );
    HIP_CHECK( hipMalloc(&d_wt , wt_bytes) );
