    HIP_CHECK( hipMemcpy(d_in , h_in, in_bytes , hipMemcpyHostToDevice) );
    HIP_CHECK( hipMemcpy(d_wt , h_wt, wt_bytes , hipMemcpyHostToDevice) );

    dim3 block(BLOCK_W, BLOCK_H, 1);
    dim3 grid( (Wout + BLOCK_W * VEC - 1) / (BLOCK_W * VEC),
               (Hout + BLOCK_H       - 1) /  BLOCK_H,
               B * Cout);

    hipLaunchKernelGGL(conv2d_kernel_tiled,
                       grid, block, 0, 0,
                       d_in, d_wt, d_out,
                       B, Cin, Cout,
                       H, W,
                       Hout, Wout);

    HIP_CHECK( hipGetLastError() );
    HIP_CHECK( hipDeviceSynchronize() );

    HIP_CHECK( hipMemcpy(h_out, d_out, out_bytes, hipMemcpyDeviceToHost) );

    for (int i = 0; i < 5; ++i)
        printf("out[%d] = %f\n", i, h_out[i]);

    HIP_CHECK( hipFree(d_in) );
    HIP_CHECK( hipFree(d_wt) );
    HIP_CHECK( hipFree(d_out) );

    free(h_in);
    free(h_wt);
    free(h_out);
    return 0;
}

