constexpr int MAX_OUT_CHANNELS = 256;   // supported maximum
constexpr int MAX_IN_CHANNELS  = 16;    // adjust if needed

__launch_bounds__(64, 4)
__global__ void depthwise_separable_conv2d_kernel(
        const float* __restrict__ input,      // N * C_in * H * W
        const float* __restrict__ dw_weight,  // C_in * K * K
        const float* __restrict__ pw_weight,  // C_out * C_in
        float* __restrict__ output,           // N * C_out * H_out * W_out
        int N, int C_in, int H, int W,
        int C_out,
        int K, int stride,
        int pad, int dilation,
        int H_out, int W_out)
{
    // coordinates this thread will compute
    const int out_h = blockIdx.y * blockDim.y + threadIdx.y;
    const int out_w = blockIdx.x * blockDim.x + threadIdx.x;
    const int n     = blockIdx.z;

    if (out_h >= H_out || out_w >= W_out) return;

    const int tid = threadIdx.y * blockDim.x + threadIdx.x; // 0..63

    // number of output channels handled by all tiles of this thread
    const int OC_STRIDE = 64;   // one wave covers 64 output channels per iteration

    // buffer to cache depthwise results per input channel
    float dw_val_local[MAX_IN_CHANNELS];

    // iterate over output-channel tiles of 64
    for (int oc_base = 0; oc_base < C_out; oc_base += OC_STRIDE) {

        const int oc = oc_base + tid;          // channel this thread accumulates
        float acc = 0.0f;

        if (oc < C_out) {

            // pre-compute depthwise convolution results for all input channels
            for (int c = 0; c < C_in; ++c) {
                float dw_sum = 0.0f;

                // depthwise conv for this (n,c) at (out_h,out_w)
                for (int kh = 0; kh < K; ++kh) {
                    int in_h = out_h * stride + kh * dilation - pad;
                    if (in_h < 0 || in_h >= H) continue;

                    for (int kw = 0; kw < K; ++kw) {
                        int in_w = out_w * stride + kw * dilation - pad;
                        if (in_w < 0 || in_w >= W) continue;

                        int in_idx = (((n * C_in + c) * H + in_h) * W) + in_w;
                        int w_idx  = (((c * K) + kh) * K) + kw;
                        dw_sum += input[in_idx] * dw_weight[w_idx];
                    }
                }
                dw_val_local[c] = dw_sum;
            }

            // pointwise multiplication & accumulation
            for (int c = 0; c < C_in; ++c) {
                float pw = pw_weight[oc * C_in + c];
                acc += dw_val_local[c] * pw;
            }

            // write to global memory
            int out_idx = ((((n * C_out) + oc) * H_out + out_h) * W_out) + out_w;
            output[out_idx] = acc;
        }
    }
}

int main() {
    const int N = 16;
    const int C_in = 3;
    const int H = 256;
    const int W = 256;
    const int C_out = 64;
    const int K = 3;
    const int stride = 1;
    const int pad = 0;
    const int dilation = 1;

    const int H_out = (H + 2 * pad - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W + 2 * pad - dilation * (K - 1) - 1) / stride + 1;

    const size_t in_size   = static_cast<size_t>(N) * C_in * H * W;
    const size_t dw_w_size = static_cast<size_t>(C_in) * K * K;
    const size_t pw_w_size = static_cast<size_t>(C_out) * C_in;
    const size_t out_size  = static_cast<size_t>(N) * C_out * H_out * W_out;

    float *h_input  = (float*)malloc(in_size  * sizeof(float));
    float *h_dw_w   = (float*)malloc(dw_w_size * sizeof(float));
    float *h_pw_w   = (float*)malloc(pw_w_size * sizeof(float));
    float *h_output = (float*)malloc(out_size * sizeof(float));

    for (size_t i = 0; i < in_size;  ++i) h_input[i] = rand() / (float)RAND_MAX;
    for (size_t i = 0; i < dw_w_size; ++i) h_dw_w[i] = rand() / (float)RAND_MAX;
    for (size_t i = 0; i < pw_w_size; ++i) h_pw_w[i] = rand() / (float)RAND_MAX;

    float *d_input, *d_dw_w, *d_pw_w, *d_output;
    CHECK(hipMalloc(&d_input,  in_size  * sizeof(float)));
    CHECK(hipMalloc(&d_dw_w,   dw_w_size * sizeof(float)));
    CHECK(hipMalloc(&d_pw_w,   pw_w_size * sizeof(float)));
    CHECK(hipMalloc(&d_output, out_size * sizeof(float)));

    CHECK(hipMemcpy(d_input, h_input, in_size * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_dw_w, h_dw_w, dw_w_size * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_pw_w, h_pw_w, pw_w_size * sizeof(float), hipMemcpyHostToDevice));

    dim3 block(8, 8, 1);   // 64 threads (single wavefront)
    dim3 grid((W_out + block.x - 1) / block.x,
              (H_out + block.y - 1) / block.y,
              N);

    hipLaunchKernelGGL(depthwise_separable_conv2d_kernel,
                       grid, block, 0, 0,
                       d_input, d_dw_w, d_pw_w, d_output,
                       N, C_in, H, W,
                       C_out,
                       K, stride,
                       pad, dilation,
                       H_out, W_out);

    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(h_output, d_output, out_size * sizeof(float), hipMemcpyDeviceToHost));

    double checksum = 0.0;
    for (size_t i = 0; i < out_size; ++i) checksum += h_output[i];
    printf("Output checksum: %lf\n", checksum);

    free(h_input);
    free(h_dw_w);
    free(h_pw_w);
    free(h_output);

    CHECK(hipFree(d_input));
    CHECK(hipFree(d_dw_w));
    CHECK(hipFree(d_pw_w));
    CHECK(hipFree(d_output));
    return 0;
}

