#include <iostream>

#define HIP_CHECK(cmd)                                                         \
    do {                                                                       \
        hipError_t e = (cmd);                                                  \
        if (e != hipSuccess) {                                                 \
            std::fprintf(stderr, "HIP error %s:%d : %s\n", __FILE__, __LINE__, \
                         hipGetErrorString(e));                                \
            std::exit(EXIT_FAILURE);                                           \
        }                                                                      \
    } while (0)

/* -------------------------------------------------------------------------- */
/*  Problem sizes                                                             */
/* -------------------------------------------------------------------------- */
constexpr int M_SIZE = 16384;  /* tall dimension                              */
constexpr int K_SIZE = 16;     /* small inner dimension                       */
static_assert(K_SIZE % 4 == 0, "K_SIZE must be divisible by 4");

/* -------------------------------------------------------------------------- */
/*  Tunable tiling parameters – tuned for gfx942                              */
/* -------------------------------------------------------------------------- */
constexpr int BM = 128;  /* rows  per block                                   */
constexpr int BN = 256;  /* cols  per block (wider to raise compute/LD ratio) */
constexpr int BK = K_SIZE;

constexpr int TM = 8;    /* rows  per thread                                  */
constexpr int TN = 8;    /* cols  per thread                                  */

/* Derived                                                         */
constexpr int THREADS_X   = BN / TN;     /* 32                                */
constexpr int THREADS_Y   = BM / TM;     /* 16                                */
constexpr int BLOCK_THREADS = THREADS_X * THREADS_Y; /* 512 threads           */

/* -------------------------------------------------------------------------- */
/*  Shared memory (with padding to kill bank conflicts for A)                 */
/* -------------------------------------------------------------------------- */
constexpr int BK_PAD = BK + 1; /* 17 → each row starts at different bank      */

/* -------------------------------------------------------------------------- */
/*  Vectorised access helpers                                                 */
/* -------------------------------------------------------------------------- */
__device__ __forceinline__ float4 load4(const float* p) {
    return *reinterpret_cast<const float4*>(p);
}
__device__ __forceinline__ void store4(float* p, float4 v) {
    *reinterpret_cast<float4*>(p) = v;
}

/* -------------------------------------------------------------------------- */
/*  Kernel                                                                    */
/* -------------------------------------------------------------------------- */
__global__
__launch_bounds__(BLOCK_THREADS, 1)
void tall_skinny_mm_kernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float*       __restrict__ C,
                           int M)
{
    /* Shared tiles                                                            */
    __shared__ float As[BM * BK_PAD];   /* 128 × 17 = 2176 floats  ~  8.5 KiB */
    __shared__ float Bs[BK * BN];       /* 16  ×256 = 4096 floats  ~ 16.0 KiB */

    const int tx  = threadIdx.x;        /* 0..31                               */
    const int ty  = threadIdx.y;        /* 0..15                               */
    const int tid = ty * THREADS_X + tx;

    /* ---------------------------------------------------------------------- */
    /*  Load A tile (vectorized float4)                                        */
    /* ---------------------------------------------------------------------- */
    constexpr int VEC = 4;
    const int a_vec_total = (BM * BK) / VEC; /* 128*16/4 = 512 vectors         */

    for (int idx4 = tid; idx4 < a_vec_total; idx4 += BLOCK_THREADS) {
        const int lrow     = idx4 / (BK / VEC);           /* 0..127            */
        const int lcol_vec = idx4 - lrow * (BK / VEC);    /* 0..3              */
        const int g_row    = blockIdx.y * BM + lrow;

        float4 val;
        if (g_row < M) {
            const int g_off = g_row * BK + lcol_vec * VEC;
            val = load4(&A[g_off]);
        } else {
            val = make_float4(0.f, 0.f, 0.f, 0.f);
        }
        store4(&As[lrow * BK_PAD + lcol_vec * VEC], val); /* padded ld/st      */
    }

    /* ---------------------------------------------------------------------- */
    /*  Load B tile (vectorized float4)                                        */
    /* ---------------------------------------------------------------------- */
    const int b_vec_total = (BK * BN) / VEC; /* 16*256/4 = 1024 vectors        */
    for (int idx4 = tid; idx4 < b_vec_total; idx4 += BLOCK_THREADS) {
        const int k        = idx4 / (BN / VEC);           /* row inside tile   */
        const int lcol_vec = idx4 - k * (BN / VEC);
        const int g_col    = blockIdx.x * BN + lcol_vec * VEC;

        float4 val;
        float tmp_arr[4];

        if (g_col + VEC - 1 < M) {
            const int g_off = k * M + g_col;
            val = load4(&B[g_off]);
        } else {
#pragma unroll
            for (int c = 0; c < VEC; ++c) {
                int col = g_col + c;
                tmp_arr[c] = (col < M) ? B[k * M + col] : 0.f;
            }
            val = make_float4(tmp_arr[0], tmp_arr[1], tmp_arr[2], tmp_arr[3]);
        }
        store4(&Bs[k * BN + lcol_vec * VEC], val);
    }

    __syncthreads();

    /* ---------------------------------------------------------------------- */
    /*  Compute TM×TN fragment per thread                                      */
    /* ---------------------------------------------------------------------- */
    float acc[TM][TN];
#pragma unroll
    for (int ii = 0; ii < TM; ++ii)
#pragma unroll
        for (int jj = 0; jj < TN; ++jj)
            acc[ii][jj] = 0.f;

#pragma unroll
    for (int k = 0; k < BK; ++k) {
        /* Load A fragment for the TM rows this thread owns                    */
        float a_frag[TM];
#pragma unroll
        for (int i = 0; i < TM; ++i) {
            int lrow = ty * TM + i;
            a_frag[i] = As[lrow * BK_PAD + k];
        }

        /* Load B fragment TN elements for this thread                         */
        float b_frag[TN];
#pragma unroll
        for (int j = 0; j < TN; ++j) {
            int lcol = tx * TN + j;
            b_frag[j] = Bs[k * BN + lcol];
        }

        /* FMA                                                                 */
#pragma unroll
        for (int i = 0; i < TM; ++i) {
#pragma unroll
            for (int j = 0; j < TN; ++j) {
                acc[i][j] = fmaf(a_frag[i], b_frag[j], acc[i][j]);
            }
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Store results (vectorised float4 where safe)                           */
    /* ---------------------------------------------------------------------- */
#pragma unroll
    for (int i = 0; i < TM; ++i) {
        int g_row = blockIdx.y * BM + ty * TM + i;
        if (g_row >= M) continue;

        int g_col0 = blockIdx.x * BN + tx * TN;

#pragma unroll
        for (int j = 0; j < TN; j += VEC) {
            int g_col_vec = g_col0 + j;

            if (g_col_vec + VEC - 1 < M) {
                float4 v = make_float4(acc[i][j], acc[i][j + 1],
                                       acc[i][j + 2], acc[i][j + 3]);
                store4(&C[g_row * M + g_col_vec], v);
            } else {
#pragma unroll
                for (int c = 0; c < VEC; ++c) {
                    int g_col = g_col_vec + c;
                    if (g_col < M) {
                        C[g_row * M + g_col] = acc[i][j + c];
                    }
                }
            }
        }
    }
}

/* -------------------------------------------------------------------------- */
/*  Minimal host driver                                                       */
/* -------------------------------------------------------------------------- */
int main()
{
    const int M = M_SIZE;
    const int K = K_SIZE;

    const size_t szA = (size_t)M * K * sizeof(float);
    const size_t szB = (size_t)K * M * sizeof(float);
    const size_t szC = (size_t)M * M * sizeof(float);

    std::vector<float> hA(M * K);
    std::vector<float> hB(K * M);
    std::vector<float> hC(16);

    std::mt19937 rng(0);
    std::uniform_real_distribution<float> dist(-1.f, 1.f);
    for (auto& v : hA) v = dist(rng);
    for (auto& v : hB) v = dist(rng);

    float *dA, *dB, *dC;
    HIP_CHECK(hipMalloc(&dA, szA));
    HIP_CHECK(hipMalloc(&dB, szB));
    HIP_CHECK(hipMalloc(&dC, szC));

    HIP_CHECK(hipMemcpy(dA, hA.data(), szA, hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(dB, hB.data(), szB, hipMemcpyHostToDevice));

    dim3 block(THREADS_X, THREADS_Y);                 /* 32 × 16 = 512 t     */
    dim3 grid((M + BN - 1) / BN, (M + BM - 1) / BM);  /* 64 × 128 blocks     */

