// -------------------------------------------------------------------------------------------------
// TILED 3x5 CONVOLUTION KERNEL (C=3, stride=1, no padding, dilation=1)
// Each block computes a horizontal tile (64 output pixels) of one output row (H_out)
// for one (N, OutC) pair.
// Shared-memory tile width = 64 + 5 − 1 = 68 to cover halo.
// -------------------------------------------------------------------------------------------------
__global__ __launch_bounds__(64, 4)
void conv2d_3x5_tiled_kernel(const float *__restrict__ input,    // [N, C, H, W]
                             const float *__restrict__ weight,   // [OutC, C, 3, 5]
                             float *__restrict__ output,         // [N, OutC, H_out, W_out]
                             int N,
                             int C,
                             int H,
                             int W,
                             int OutC)
{
    constexpr int KH       = 3;
    constexpr int KW       = 5;
    constexpr int BLOCK_W  = 64;
    constexpr int TILE_W   = BLOCK_W + KW - 1;  // 68

    const int H_out = H - KH + 1;
    const int W_out = W - KW + 1;

    const int tile_x = blockIdx.x * BLOCK_W;   // leftmost output-x of this block
    const int out_y  = blockIdx.y;             // output row
    const int nz     = blockIdx.z;             // combined N/OutC index
    const int n      = nz / OutC;
    const int oc     = nz % OutC;

    const int out_x  = tile_x + threadIdx.x;   // this thread's output-x

    if (out_y >= H_out || n >= N || oc >= OutC) return;

    // Dynamic shared memory: layout [C][KH][TILE_W]
    extern __shared__ float s_data[];

    // Cooperative load of input tile into LDS
    for (int c = 0; c < C; ++c) {
        #pragma unroll
        for (int ky = 0; ky < KH; ++ky) {
            for (int lx = threadIdx.x; lx < TILE_W; lx += BLOCK_W) {
                const int global_x = tile_x + lx;
                float val = 0.0f;
                if (global_x < W) {
                    const size_t idx =
                        (((size_t)n * C + c) * H + (out_y + ky)) * W + global_x;
                    val = input[idx];
                }
                s_data[((c * KH + ky) * TILE_W) + lx] = val;
            }
        }
    }
    __syncthreads();

    if (out_x >= W_out) return;  // right edge guard for compute stage

    const float *w_oc = weight + ((size_t)oc * C * KH * KW);
    float acc = 0.0f;

    #pragma unroll
    for (int c = 0; c < C; ++c) {
        const float *w_c = w_oc + c * KH * KW;
        #pragma unroll
        for (int ky = 0; ky < KH; ++ky) {
            const float *row_s = s_data + ((c * KH + ky) * TILE_W) + threadIdx.x;
            acc += row_s[0] * w_c[ky * KW + 0];
            acc += row_s[1] * w_c[ky * KW + 1];
            acc += row_s[2] * w_c[ky * KW + 2];
            acc += row_s[3] * w_c[ky * KW + 3];
            acc += row_s[4] * w_c[ky * KW + 4];
        }
    }

    const size_t out_idx =
        (((size_t)n * OutC + oc) * H_out + out_y) * W_out + out_x;
    output[out_idx] = acc;
}

