// HOST DRIVER (minimal)
// -------------------------------------------------------------------------------------------------
int main() {
    constexpr int N     = 16;
    constexpr int C_in  = 3;
    constexpr int H     = 256;
    constexpr int W     = 128;
    constexpr int OutC  = 64;
    constexpr int KH    = 3;
    constexpr int KW    = 5;

    const int H_out = H - KH + 1;
    const int W_out = W - KW + 1;

    const size_t bytes_in  = (size_t)N * C_in * H * W * sizeof(float);
    const size_t bytes_w   = (size_t)OutC * C_in * KH * KW * sizeof(float);
    const size_t bytes_out = (size_t)N * OutC * H_out * W_out * sizeof(float);

    std::vector<float> h_input (bytes_in  / sizeof(float));
    std::vector<float> h_weight(bytes_w   / sizeof(float));
    std::vector<float> h_output(bytes_out / sizeof(float), 0.0f);

    std::mt19937 rng(0);
    std::uniform_real_distribution<float> dist(-1.f, 1.f);
    for (auto &v : h_input ) v = dist(rng);
    for (auto &v : h_weight) v = dist(rng);

    auto HIP_CHECK = [](hipError_t e) {
        if (e != hipSuccess) {
            std::cerr << "HIP error: " << hipGetErrorString(e) << std::endl;
            std::exit(EXIT_FAILURE);
        }
    };

    float *d_input  = nullptr;
    float *d_weight = nullptr;
    float *d_output = nullptr;
    HIP_CHECK(hipMalloc(&d_input , bytes_in ));
    HIP_CHECK(hipMalloc(&d_weight, bytes_w  ));
    HIP_CHECK(hipMalloc(&d_output, bytes_out));

    HIP_CHECK(hipMemcpy(d_input , h_input .data(), bytes_in , hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_weight, h_weight.data(), bytes_w  , hipMemcpyHostToDevice));
    HIP_CHECK(hipMemset(d_output, 0, bytes_out));

    dim3 block(64, 1, 1);
    dim3 grid( (W_out + block.x - 1) / block.x,
               H_out,
               N * OutC );

    const size_t sharedBytes = C_in * KH * (block.x + KW - 1) * sizeof(float);

    hipLaunchKernelGGL(conv2d_3x5_tiled_kernel, grid, block, sharedBytes, 0,
                       d_input, d_weight, d_output,
                       N, C_in, H, W, OutC);
    HIP_CHECK(hipDeviceSynchronize());

    HIP_CHECK(hipMemcpy(h_output.data(), d_output, bytes_out, hipMemcpyDeviceToHost));

    HIP_CHECK(hipFree(d_input));
    HIP_CHECK(hipFree(d_weight));
    HIP_CHECK(hipFree(d_output));

    std::cout << "Convolution completed.\n";
    return 0;
}

