static constexpr int BLOCK_THREADS = 256;           // 4 wavefronts per block
static constexpr int VEC           = 4;             // float4 vectorization

//-----------------------------------------------------------------------------
// Warp‐reduce helpers
//-----------------------------------------------------------------------------
__device__ __forceinline__ float warp_reduce_sum(float v)
{
#pragma unroll
    for (int offset = 32 >> 1; offset > 0; offset >>= 1)
        v += __shfl_down(v, offset);
    return v;
}

//-----------------------------------------------------------------------------
// InstanceNorm kernel – one block per (n,c)
//-----------------------------------------------------------------------------
__launch_bounds__(BLOCK_THREADS)
__global__
void instance_norm_kernel(const float *__restrict__ x,
                          float       *__restrict__ y,
                          const float *__restrict__ gamma,
                          const float *__restrict__ beta,
                          int  H, int W, int C,
                          float eps)
{
    extern __shared__ float smem[];      // 2*BLOCK_THREADS floats
    float *s_sum   = smem;
    float *s_sumsq = smem + blockDim.x;

    const int tid    = threadIdx.x;
    const int nc     = blockIdx.x;               // flattened (n,c)
    const int HW     = H * W;
    const size_t base = static_cast<size_t>(nc) * HW;

    // ---------------------------------------------------------------------
    // Pass 1 : partial statistics
    // ---------------------------------------------------------------------
    float sum   = 0.f;
    float sumsq = 0.f;

    int vec_bound = (HW / VEC) * VEC;
    const float *src = x + base;

    // vectorized region
    for (int idx = tid * VEC; idx < vec_bound; idx += blockDim.x * VEC)
    {
        float4 v4 = reinterpret_cast<const float4*>(src + idx)[0];
        sum   += v4.x + v4.y + v4.z + v4.w;
        sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }

    // tail
    for (int idx = vec_bound + tid; idx < HW; idx += blockDim.x)
    {
        float v = src[idx];
        sum   += v;
        sumsq += v * v;
    }

    // store partials
    s_sum  [tid] = sum;
    s_sumsq[tid] = sumsq;
    __syncthreads();

    // reduction in shared memory until <= warp
    for (int stride = blockDim.x >> 1; stride >= 64; stride >>= 1)
    {
        if (tid < stride)
        {
            s_sum  [tid] += s_sum  [tid + stride];
            s_sumsq[tid] += s_sumsq[tid + stride];
        }
        __syncthreads();
    }

    // last warp reduction
    float warp_sum   = s_sum  [tid];
    float warp_sumsq = s_sumsq[tid];

    if (tid < 32)
    {
        warp_sum   = warp_reduce_sum(warp_sum);
        warp_sumsq = warp_reduce_sum(warp_sumsq);
    }

    if (tid == 0)
    {
        s_sum  [0] = warp_sum;
        s_sumsq[0] = warp_sumsq;
    }
    __syncthreads();

    // ---------------------------------------------------------------------
    // Compute mean / variance / scale–shift parameters
    // ---------------------------------------------------------------------
    float mean     = s_sum[0] / static_cast<float>(HW);
    float var      = s_sumsq[0] / static_cast<float>(HW) - mean * mean;
    var            = var < 0.f ? 0.f : var;               // numerical floor
    float inv_std  = rsqrtf(var + eps);

    int c_idx  = nc % C;                                  // channel index
    float g    = gamma ? gamma[c_idx] : 1.f;
    float b    = beta  ? beta [c_idx] : 0.f;

    // ---------------------------------------------------------------------
    // Pass 2 : normalize & affine
    // ---------------------------------------------------------------------
    for (int idx = tid; idx < HW; idx += blockDim.x)
    {
        float v = src[idx];
        float n = (v - mean) * inv_std;
        y[base + idx] = n * g + b;
    }
}

//-----------------------------------------------------------------------------
// Host launcher
//-----------------------------------------------------------------------------
void instance_norm(const float *d_x, float *d_y,
                   const float *d_gamma, const float *d_beta,
                   int N, int C, int H, int W,
                   float eps, hipStream_t stream = nullptr)
{
    int blocks = N * C;
    size_t smem = 2 * BLOCK_THREADS * sizeof(float);
    hipLaunchKernelGGL(instance_norm_kernel,
                       dim3(blocks), dim3(BLOCK_THREADS), smem, stream,
                       d_x, d_y, d_gamma, d_beta, H, W, C, eps);
}

