    CHECK_HIP( hipMalloc(&d_x, bytes) );
    CHECK_HIP( hipMalloc(&d_y, bytes) );
    CHECK_HIP( hipMalloc(&d_gamma, C * sizeof(float)) );
    CHECK_HIP( hipMalloc(&d_beta , C * sizeof(float)) );

    CHECK_HIP( hipMemcpy(d_x, h_x, bytes, hipMemcpyHostToDevice) );
    CHECK_HIP( hipMemcpy(d_gamma, h_gamma, C * sizeof(float), hipMemcpyHostToDevice) );
    CHECK_HIP( hipMemcpy(d_beta , h_beta , C * sizeof(float), hipMemcpyHostToDevice) );

    instance_norm(d_x, d_y, d_gamma, d_beta, N, C, H, W, eps);
    CHECK_HIP( hipDeviceSynchronize() );

