/* ------------------------------------------------------------------------ */
/*                       DEVICE  CONFIGURATION                              */
constexpr int TM = 4;      // rows   each thread computes
constexpr int TN = 4;      // cols   each thread computes
constexpr int BK = 8;      // reduction tile depth
constexpr int THREAD_M = 16;
constexpr int THREAD_N = 16;
constexpr int BM = THREAD_M * TM;   // 64
constexpr int BN = THREAD_N * TN;   // 64

/* ------------------------------------------------------------------------ */
/*                               KERNEL                                     */
__global__
__launch_bounds__(THREAD_M * THREAD_N, 1)
void matmul_AT_B_kernel(const float* __restrict__ A,  // (K, M)
                        const float* __restrict__ B,  // (K, N)
                        float*       __restrict__ C,  // (M, N)
                        int M, int K, int N)
{
    /* Thread identifiers inside block */
    const int tx = threadIdx.x;  // 0..15
    const int ty = threadIdx.y;  // 0..15
    const int flat_tid = ty * blockDim.x + tx; // 0..255

    /* Global coordinates of first output element this thread handles */
    const int row_base = blockIdx.y * BM + ty * TM; // up to +3 later
    const int col_base = blockIdx.x * BN + tx * TN; // up to +3 later

    /* LDS tiles */
    __shared__ float sA[BK][BM];  // 8 × 64 = 512 floats
    __shared__ float sB[BK][BN];  // 8 × 64 = 512 floats

    /* Registers for output tile */
    float acc[TM][TN] = {0.0f};

    /* Loop over K dimension in chunks of BK */
    for (int k0 = 0; k0 < K; k0 += BK)
    {
        /* --------------------------------------------------------------
           Cooperative load of A tile into shared memory
           Each thread loads multiple elements in a strided pattern.
           --------------------------------------------------------------*/
        for (int idx = flat_tid; idx < BK * BM; idx += blockDim.x * blockDim.y)
        {
            int kk = idx / BM;      // 0..BK-1
            int mm = idx % BM;      // 0..BM-1
            int gk = k0 + kk;
            int gm = blockIdx.y * BM + mm;
            sA[kk][mm] = (gk < K && gm < M) ? A[gk * M + gm] : 0.0f;
        }

        /* Load B tile */
        for (int idx = flat_tid; idx < BK * BN; idx += blockDim.x * blockDim.y)
        {
            int kk = idx / BN;
            int nn = idx % BN;
            int gk = k0 + kk;
            int gn = blockIdx.x * BN + nn;
            sB[kk][nn] = (gk < K && gn < N) ? B[gk * N + gn] : 0.0f;
        }

        __syncthreads();

        /* --------------------------------------------------------------
           Compute partial products for this K tile
           --------------------------------------------------------------*/
        #pragma unroll
        for (int k = 0; k < BK; ++k)
        {
            /* Load a vector of A and B elements into registers */
            float a_reg[TM];
            float b_reg[TN];

            #pragma unroll
            for (int i = 0; i < TM; ++i)
                a_reg[i] = sA[k][ty * TM + i];           // continuous in LDS

            #pragma unroll
            for (int j = 0; j < TN; ++j)
                b_reg[j] = sB[k][tx * TN + j];

            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += a_reg[i] * b_reg[j];
        }
        __syncthreads();
    }

    /* --------------------------------------------------------------
       Write the computed C tile to global memory
       --------------------------------------------------------------*/
    #pragma unroll
    for (int i = 0; i < TM; ++i)
    {
        int gm = row_base + i;
        if (gm < M)
        {
            #pragma unroll
            for (int j = 0; j < TN; ++j)
            {
                int gn = col_base + j;
                if (gn < N)
                    C[gm * N + gn] = acc[i][j];
            }
        }
    }
}

