/* ---------------------------------------------------------------------------------- */
/*  ARCH / BLOCK CONFIGURATION                                                         */
/* ---------------------------------------------------------------------------------- */
constexpr int WAVE  = 64;     // AMD wavefront size
constexpr int BLOCK = 256;    // 4 waves  -> plenty ILP, good occupancy
constexpr int VEC4  = 4;      // vector width used when reducing over the last dimension

/* ---------------------------------------------------------------------------------- */
template<typename T>
__device__ __forceinline__ T my_max(const T &a, const T &b) { return a > b ? a : b; }

template<typename T>
__device__ __forceinline__ T wave_max(T v)
{
#pragma unroll
    for (int offset = WAVE >> 1; offset; offset >>= 1)
        v = my_max(v, __shfl_down(v, offset, WAVE));
    return v;
}

/* ================================================================================== */
/*  3-D MAX REDUCTION KERNEL                                                          */
/*     in  : (B, M, N) – contiguous in N                                              */
/*     out :                                                                        */
/*        RDIM = 2 → (B, M)  – reduce N (innermost, fast path)                        */
/*        RDIM = 1 → (B, N)  – reduce M                                              */
/*        RDIM = 0 → (M, N)  – reduce B                                              */
/* ================================================================================== */
template<int RDIM>
__launch_bounds__(BLOCK, 4)
__global__ void max_reduce3d_kernel(const float *__restrict__ in,
                                    float       *__restrict__ out,
                                    const int B, const int M, const int N)
{
    __shared__ float warp_max[BLOCK / WAVE];      // one slot per wave (4)

    const int tid  = threadIdx.x;
    const int lane = tid & (WAVE - 1);
    const int warp = tid >> 6;                    // == tid / 64

    float local_max = -FLT_MAX;

    if constexpr (RDIM == 2)
    {
        /* -------------------------------------------------- */
        /*  Fast path : contiguous reduction over innermost N */
        /* -------------------------------------------------- */
        const int b = blockIdx.x;
        const int m = blockIdx.y;

        const float *base = in + (static_cast<size_t>(b) * M + m) * N;

        /* vectorised main loop  (float4) */
        int k = tid * VEC4;
        for (; k + VEC4 - 1 < N; k += BLOCK * VEC4)
        {
            float4 v4 = reinterpret_cast<const float4*>(base)[k / VEC4];
            local_max = my_max(local_max, v4.x);
            local_max = my_max(local_max, v4.y);
            local_max = my_max(local_max, v4.z);
            local_max = my_max(local_max, v4.w);
        }
        /* handle tail (≤ 3 elements) */
        for (int kk = k; kk < N; kk += BLOCK)
            local_max = my_max(local_max, base[kk]);
    }
    else if constexpr (RDIM == 1)
    {
        /* -------------------------------------------------- */
        /*  Reduce over M:  threads walk M with stride BLOCK */
        /* -------------------------------------------------- */
        const int b = blockIdx.x;
        const int n = blockIdx.y;

        size_t idx = (static_cast<size_t>(b) * M) * N + n; // m = 0 initially
        for (int m = tid; m < M; m += BLOCK)
        {
            local_max = my_max(local_max, in[idx + static_cast<size_t>(m) * N]);
        }
    }
    else
    {
        /* -------------------------------------------------- */
        /*  Reduce over B:  threads walk B with stride BLOCK */
        /* -------------------------------------------------- */
        const int m = blockIdx.x;
        const int n = blockIdx.y;

        size_t idx = static_cast<size_t>(m) * N + n;   // b = 0 initially
        for (int b = tid; b < B; b += BLOCK)
        {
            local_max = my_max(local_max, in[(static_cast<size_t>(b) * M * N) + idx]);
        }
    }

    /* ---------------- WAVE REDUCTION ------------------- */
    local_max = wave_max(local_max);

    /* leader lane writes to shared */
    if (lane == 0) warp_max[warp] = local_max;
    __syncthreads();

    /* first warp reduces partials from all warps */
    if (warp == 0)
    {
        float block_max = (tid < BLOCK / WAVE) ? warp_max[lane] : -FLT_MAX;
        block_max = wave_max(block_max);

        if (lane == 0)
        {
            if constexpr (RDIM == 2)
            {
                out[static_cast<size_t>(blockIdx.x) * M + blockIdx.y] = block_max;
            }
            else if constexpr (RDIM == 1)
            {
                out[static_cast<size_t>(blockIdx.x) * N + blockIdx.y] = block_max;
            }
            else /* RDIM == 0 */
            {
                out[static_cast<size_t>(blockIdx.x) * N + blockIdx.y] = block_max;
            }
        }
    }
}

/* ================================================================================== */
/*  HOST-SIDE LAUNCHER                                                                */
/* ================================================================================== */
void launch_max_reduce(const float *d_in, float *d_out,
                       int B, int M, int N, int dim,
                       hipStream_t stream = nullptr)
{
    dim3 grid;
    switch (dim)
    {
        case 2: grid = dim3(B, M);
                hipLaunchKernelGGL(HIP_KERNEL_NAME(max_reduce3d_kernel<2>),
                                    grid, BLOCK, 0, stream,
                                    d_in, d_out, B, M, N);
                break;
        case 1: grid = dim3(B, N);
                hipLaunchKernelGGL(HIP_KERNEL_NAME(max_reduce3d_kernel<1>),
                                    grid, BLOCK, 0, stream,
                                    d_in, d_out, B, M, N);
                break;
        case 0: grid = dim3(M, N);
                hipLaunchKernelGGL(HIP_KERNEL_NAME(max_reduce3d_kernel<0>),
                                    grid, BLOCK, 0, stream,
                                    d_in, d_out, B, M, N);
                break;
        default:
                fprintf(stderr, "launch_max_reduce : bad dim %d\n", dim);
                exit(EXIT_FAILURE);
    }
}

/* ================================================================================== */
/*  DEMO / SELF-TEST                                                                  */
/* ================================================================================== */
int main(int argc, char **argv)
{
    const int red_dim = (argc > 1) ? atoi(argv[1]) : 2;   // 0,1,2

    const int B = 16, M = 256, N = 256;

    const size_t in_sz  = static_cast<size_t>(B) * M * N;
    const size_t out_sz = (red_dim == 0) ? static_cast<size_t>(M) * N :
                         (red_dim == 1) ? static_cast<size_t>(B) * N :
                                          static_cast<size_t>(B) * M;

    float *h_in  = (float*)malloc(in_sz  * sizeof(float));
    float *h_out = (float*)malloc(out_sz * sizeof(float));

    /* generate reproducible pseudo-random data in range [0,1) */
    srand(0xC0FFEE);
    const float inv_rand_max = 1.0f / static_cast<float>(RAND_MAX);
    for (size_t i = 0; i < in_sz; ++i)
        h_in[i] = static_cast<float>(rand()) * inv_rand_max;

    float *d_in, *d_out;
    CHECK(hipMalloc(&d_in,  in_sz  * sizeof(float)));
    CHECK(hipMalloc(&d_out, out_sz * sizeof(float)));
    CHECK(hipMemcpy(d_in, h_in, in_sz * sizeof(float), hipMemcpyHostToDevice));

    launch_max_reduce(d_in, d_out, B, M, N, red_dim);
    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(h_out, d_out, out_sz * sizeof(float), hipMemcpyDeviceToHost));

    /* verification */
    bool ok = true;

    if (red_dim == 2)
    {
        for (int b = 0; b < B && ok; ++b)
            for (int m = 0; m < M && ok; ++m)
            {
                float ref = -FLT_MAX;
                for (int n = 0; n < N; ++n)
                    ref = fmaxf(ref, h_in[(static_cast<size_t>(b) * M + m) * N + n]);
                if (fabsf(ref - h_out[b * M + m]) > 1e-3f) { ok = false; break; }
            }
    }
    else if (red_dim == 1)
    {
        for (int b = 0; b < B && ok; ++b)
            for (int n = 0; n < N && ok; ++n)
            {
                float ref = -FLT_MAX;
                for (int m = 0; m < M; ++m)
                    ref = fmaxf(ref, h_in[(static_cast<size_t>(b) * M + m) * N + n]);
                if (fabsf(ref - h_out[b * N + n]) > 1e-3f) { ok = false; break; }
            }
    }
    else        /* red_dim == 0 */
    {
        for (int m = 0; m < M && ok; ++m)
            for (int n = 0; n < N && ok; ++n)
            {
                float ref = -FLT_MAX;
                for (int b = 0; b < B; ++b)
                    ref = fmaxf(ref, h_in[(static_cast<size_t>(b) * M + m) * N + n]);
                if (fabsf(ref - h_out[m * N + n]) > 1e-3f) { ok = false; break; }
            }
    }

    printf("Max-reduce (dim=%d) %s\n", red_dim, ok ? "PASSED" : "FAILED");

    free(h_in);
    free(h_out);
    CHECK(hipFree(d_in));
    CHECK(hipFree(d_out));

    return ok ? 0 : 1;
}

