/*--------------------------------------------------------*/
/*                    DEVICE HELPERS                      */
/*--------------------------------------------------------*/
__device__ __forceinline__ float elu_scalar(float x, float a)
{
    return (x >= 0.0f) ? x : a * expm1f(x);
}

__device__ __forceinline__ float4 elu_vec4(float4 v, float a)
{
    v.x = elu_scalar(v.x, a);
    v.y = elu_scalar(v.y, a);
    v.z = elu_scalar(v.z, a);
    v.w = elu_scalar(v.w, a);
    return v;
}

/*--------------------------------------------------------*/
/*                       KERNELS                          */
/*--------------------------------------------------------*/
template<int TPB>
__launch_bounds__(TPB, 2)
__global__ void elu_kernel_scalar(const float *__restrict__ in,
                                  float       *__restrict__ out,
                                  const float  alpha,
                                  const size_t n)
{
    size_t idx    = blockIdx.x * TPB + threadIdx.x;
    size_t stride = gridDim.x * TPB;
    for (; idx < n; idx += stride)
        out[idx] = elu_scalar(in[idx], alpha);
}

template<int TPB>
__launch_bounds__(TPB, 2)
__global__ void elu_kernel_vec4(const float4 *__restrict__ in,
                                float4       *__restrict__ out,
                                const float   alpha,
                                const size_t  n_vec4)
{
    size_t idx    = blockIdx.x * TPB + threadIdx.x;
    size_t stride = gridDim.x * TPB;
#pragma unroll 2
    for (; idx < n_vec4; idx += stride)
        out[idx] = elu_vec4(in[idx], alpha);
}

/*--------------------------------------------------------*/
/*                OCCUPANCY / LAUNCH UTILS                */
/*--------------------------------------------------------*/
template<typename KernelPtr>
static int optimal_blocks(KernelPtr kptr, int tpb)
{
    hipDeviceProp_t prop{};
    int dev = 0;
    HIP_CHECK(hipGetDevice(&dev));
    HIP_CHECK(hipGetDeviceProperties(&prop, dev));

    int blocks_per_mp = 0;
    HIP_CHECK(hipOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_mp,
                                                           (const void*)kptr,
                                                           tpb,
                                                           0));
    return blocks_per_mp * prop.multiProcessorCount;
}

static void launch_elu(const float *d_in,
                       float       *d_out,
                       float        alpha,
                       size_t       n,
                       hipStream_t  stream = nullptr)
{
    constexpr int TPB = 256;
    const bool use_vec4 = ((reinterpret_cast<uintptr_t>(d_in)  & 0xF) == 0) &&
                          ((reinterpret_cast<uintptr_t>(d_out) & 0xF) == 0) &&
                          (n % 4 == 0);

    if (use_vec4)
    {
        const size_t n_vec4 = n / 4;
        int blocks = std::min<int>((n_vec4 + TPB - 1) / TPB,
                                   optimal_blocks(elu_kernel_vec4<TPB>, TPB));
        hipLaunchKernelGGL(elu_kernel_vec4<TPB>,
                           dim3(blocks),
                           dim3(TPB),
                           0,
                           stream,
                           reinterpret_cast<const float4*>(d_in),
                           reinterpret_cast<float4*>(d_out),
                           alpha,
                           n_vec4);
    }
    else
    {
        int blocks = std::min<int>((n + TPB - 1) / TPB,
                                   optimal_blocks(elu_kernel_scalar<TPB>, TPB));
        hipLaunchKernelGGL(elu_kernel_scalar<TPB>,
                           dim3(blocks),
                           dim3(TPB),
                           0,
                           stream,
                           d_in,
                           d_out,
                           alpha,
                           n);
    }
}

/*--------------------------------------------------------*/
/*                        MAIN                            */
/*--------------------------------------------------------*/
int main()
{
    constexpr size_t batch = 16;
    constexpr size_t feat  = 16384;
    constexpr size_t N     = batch * feat;
    constexpr float  alpha = 1.0f;

    std::srand(42);

    float *h_in  = static_cast<float*>(malloc(N * sizeof(float)));
    float *h_out = static_cast<float*>(malloc(N * sizeof(float)));

    for (size_t i = 0; i < N; ++i)
    {
        float r = static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX);
        h_in[i] = r * 2.0f - 1.0f;
    }

    float *d_in = nullptr, *d_out = nullptr;
    HIP_CHECK(hipMalloc(&d_in,  N * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_out, N * sizeof(float)));

    HIP_CHECK(hipMemcpy(d_in, h_in, N * sizeof(float), hipMemcpyHostToDevice));

    launch_elu(d_in, d_out, alpha, N);

    HIP_CHECK(hipMemcpy(h_out, d_out, N * sizeof(float), hipMemcpyDeviceToHost));

    size_t mism = 0;
    for (size_t i = 0; i < N; ++i)
    {
        float ref = (h_in[i] >= 0.0f) ? h_in[i] : alpha * (std::exp(h_in[i]) - 1.0f);
        if (std::fabs(ref - h_out[i]) > 1e-4f)
        {
            if (mism < 10)
                printf("Mismatch at %zu : ref=%f  gpu=%f\n", i, ref, h_out[i]);
            ++mism;
        }
    }
    printf(mism ? "FAIL (%zu mismatches)\n" : "PASS\n", mism);

    HIP_CHECK(hipFree(d_in));
    HIP_CHECK(hipFree(d_out));
    free(h_in);
    free(h_out);

    return mism ? EXIT_FAILURE : EXIT_SUCCESS;
}

