#define THREADS_PER_BLOCK 256

inline void hipCheck(hipError_t e, const char *file, int line)
{
    if (e != hipSuccess)
    {
        fprintf(stderr, "HIP error %s:%d  %s\n", file, line, hipGetErrorString(e));
        std::abort();
    }
}
