/* ------------------------------------------------------------------------- */
/*                             DEVICE KERNEL                                 */
/* ------------------------------------------------------------------------- */

template<bool HAS_BIAS>
__global__ __launch_bounds__(THREADS_PER_BLOCK)
void conv1x1_pointwise_kernel(const float * __restrict__ input,
                              const float * __restrict__ weight,
                              const float * __restrict__ bias,
                              float * __restrict__ output,
                              int N, int C_in, int C_out, int H, int W)
{
    extern __shared__ float s_weight[];    // size = C_in

    /* ------------------------ identify indices --------------------------- */
    int w = blockIdx.x * blockDim.x + threadIdx.x;      // spatial X (width)
    if (w >= W) return;

    int h  = blockIdx.y;                               // one block per row
    if (h >= H) return;

    int nc = blockIdx.z;                               // fused (N, C_out)
    int n  = nc / C_out;
    int co = nc - n * C_out;
    if (n >= N) return;

    /* ------------------------ load weights into LDS ---------------------- */
    for (int ci = threadIdx.x; ci < C_in; ci += blockDim.x)
        s_weight[ci] = weight[co * C_in + ci];
    __syncthreads();

    /* ------------------------ compute address bases ---------------------- */
    const size_t HW   = static_cast<size_t>(H) * W;
    const size_t in_base  = static_cast<size_t>(n) * C_in * HW + h * W + w;

    float acc = HAS_BIAS ? bias[co] : 0.0f;

    /* ------------------------ accumulation loop -------------------------- */
#pragma unroll 4
    for (int ci = 0; ci < C_in; ++ci)
    {
        float in_val = input[in_base + static_cast<size_t>(ci) * HW];
        acc += in_val * s_weight[ci];
    }

    /* ------------------------ write output ------------------------------- */
    size_t out_idx = (((static_cast<size_t>(n) * C_out + co) * H + h) * W) + w;
    output[out_idx] = acc;
}

/* ------------------------------------------------------------------------- */
/*                             HOST WRAPPER                                 */
/* ------------------------------------------------------------------------- */
void pointwise_conv2d_1x1(float       *d_output,
                          const float *d_input,
                          const float *d_weight,
                          const float *d_bias,       // nullptr if no bias
                          int N, int C_in, int C_out, int H, int W,
                          hipStream_t stream = 0)
{
    dim3 block(THREADS_PER_BLOCK, 1, 1);
    dim3 grid((W + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK,
              H,
              N * C_out);

    size_t smem_bytes = static_cast<size_t>(C_in) * sizeof(float);

    if (d_bias)
    {
        hipLaunchKernelGGL((conv1x1_pointwise_kernel<true>), grid, block,
                           smem_bytes, stream,
                           d_input, d_weight, d_bias, d_output,
                           N, C_in, C_out, H, W);
    }
    else
    {
        hipLaunchKernelGGL((conv1x1_pointwise_kernel<false>), grid, block,
                           smem_bytes, stream,
                           d_input, d_weight, nullptr, d_output,
                           N, C_in, C_out, H, W);
    }
}

