/*                          MINIMAL TEST DRIVER                             */
/* ------------------------------------------------------------------------- */
int main()
{
    const int N     = 16;
    const int C_in  = 3;
    const int C_out = 64;
    const int H     = 256;
    const int W     = 256;

    const size_t in_elems   = static_cast<size_t>(N) * C_in  * H * W;
    const size_t out_elems  = static_cast<size_t>(N) * C_out * H * W;
    const size_t w_elems    = static_cast<size_t>(C_out) * C_in;
    const size_t b_elems    = C_out;

    std::vector<float> h_input(in_elems);
    std::vector<float> h_weight(w_elems);
    std::vector<float> h_bias(b_elems);
    std::vector<float> h_output(out_elems, 0.0f);

    std::mt19937 rng(0);
    std::uniform_real_distribution<float> dist(-1.f, 1.f);
    for (auto &v : h_input)  v = dist(rng);
    for (auto &v : h_weight) v = dist(rng);
    for (auto &v : h_bias)   v = dist(rng);

    float *d_input = nullptr, *d_weight = nullptr, *d_bias = nullptr, *d_output = nullptr;
    HIP_CHECK(hipMalloc(&d_input,  in_elems  * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_weight, w_elems   * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_bias,   b_elems   * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_output, out_elems * sizeof(float)));

    HIP_CHECK(hipMemcpy(d_input,  h_input.data(),  in_elems  * sizeof(float), hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_weight, h_weight.data(), w_elems   * sizeof(float), hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_bias,   h_bias.data(),   b_elems   * sizeof(float), hipMemcpyHostToDevice));

    pointwise_conv2d_1x1(d_output, d_input, d_weight, d_bias,
                         N, C_in, C_out, H, W);

    HIP_CHECK(hipMemcpy(h_output.data(), d_output, out_elems * sizeof(float), hipMemcpyDeviceToHost));
    printf("Kernel executed. First output element: %f\n", h_output[0]);

    HIP_CHECK(hipFree(d_input));
    HIP_CHECK(hipFree(d_weight));
    HIP_CHECK(hipFree(d_bias));
    HIP_CHECK(hipFree(d_output));
    return 0;
}

