constexpr int TPB = 256;   // threads per block
constexpr int VEC = 4;     // vector width (float4)

__device__ __forceinline__ float leaky(float x, float slope) {
    return x < 0.0f ? x * slope : x;
}

__global__ __launch_bounds__(TPB)
void leaky_relu_kernel_vec4(const float* __restrict__ x,
                            float* __restrict__ y,
                            const float negative_slope,
                            const int n_vec) {   // number of float4 packs
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= n_vec) return;

    const float4* x4 = reinterpret_cast<const float4*>(x);
    float4 v = x4[tid];

    v.x = leaky(v.x, negative_slope);
    v.y = leaky(v.y, negative_slope);
    v.z = leaky(v.z, negative_slope);
    v.w = leaky(v.w, negative_slope);

    float4* y4 = reinterpret_cast<float4*>(y);
    y4[tid] = v;
}

int main() {
    const int batch_size = 16;
    const int dim         = 16384;
    const int numel       = batch_size * dim;   // 262,144 elements
    const float negative_slope = 0.01f;

    if (numel % VEC != 0) {
        fprintf(stderr, "Element count must be divisible by %d\n", VEC);
        return EXIT_FAILURE;
    }
    const int n_vec = numel / VEC;

    std::vector<float> h_x(numel);
    for (int i = 0; i < numel; ++i) {
        h_x[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX) * 2.0f - 1.0f;
    }
    std::vector<float> h_y(numel, 0.0f);

    float* d_x = nullptr;
    float* d_y = nullptr;
    HIP_CHECK(hipMalloc(&d_x, numel * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_y, numel * sizeof(float)));

    HIP_CHECK(hipMemcpy(d_x, h_x.data(), numel * sizeof(float), hipMemcpyHostToDevice));

    const int blocks = (n_vec + TPB - 1) / TPB;
    hipLaunchKernelGGL(leaky_relu_kernel_vec4,
                       dim3(blocks),
                       dim3(TPB),
                       0, 0,
                       d_x, d_y, negative_slope, n_vec);
    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    HIP_CHECK(hipMemcpy(h_y.data(), d_y, numel * sizeof(float), hipMemcpyDeviceToHost));

    bool ok = true;
    for (int i = 0; i < numel; ++i) {
        float ref = h_x[i] < 0.0f ? h_x[i] * negative_slope : h_x[i];
