constexpr float SELU_SCALE        = 1.0507009873554805f;
constexpr float SELU_SCALE_ALPHA  = 1.7580993408473766f;   // scale * alpha

__device__ __forceinline__ float selu_device(float v)
{
    return v > 0.0f ? v * SELU_SCALE
                    : SELU_SCALE_ALPHA * (expf(v) - 1.0f);
}

__device__ __forceinline__ float4 selu_vec4(float4 v)
{
    v.x = selu_device(v.x);
    v.y = selu_device(v.y);
    v.z = selu_device(v.z);
    v.w = selu_device(v.w);
    return v;
}

__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void selu_kernel(const float* __restrict__ in,
                 float*       __restrict__ out,
                 const int                n,           // total elements
                 const int                vec4_elems,  // n / 4
                 const int                rem)         // n % 4
{
    const int stride = gridDim.x * blockDim.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Vectorised path (float4)
    const float4* __restrict__ in4  = reinterpret_cast<const float4*>(in);
    float4*       __restrict__ out4 = reinterpret_cast<float4*>(out);

    for (int i = idx; i < vec4_elems; i += stride) {
        float4 v = in4[i];
        v        = selu_vec4(v);
        out4[i]  = v;
    }

    // Handle remaining 0–3 elements
    if (rem) {
        const int base = vec4_elems << 2;   // vec4_elems * 4
        for (int j = idx; j < rem; j += stride) {
            int id = base + j;
            if (id < n)
                out[id] = selu_device(in[id]);
        }
    }
}

