/*----------------------------------------------------------------------------
 * Kernel : L2-normalise every row of a 2-D float matrix in-place
 * Each block processes one row, using vectorised memory access (float4).
 *---------------------------------------------------------------------------*/
__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void l2norm_rows_kernel(float* __restrict__ data,
                        int rows,
                        int cols)
{
    extern __shared__ float sdata[];          // THREADS_PER_BLOCK * sizeof(float)
    const int tid        = threadIdx.x;
    const int row_idx    = blockIdx.x;

    if (row_idx >= rows) return;

    const int row_offset = row_idx * cols;

    /* ---- Phase 1 : partial sum of squares --------------------------------*/
    float local_sum = 0.0f;

    /* Process 4 elements per iteration where possible for coalesced 16-byte loads */
    const int vec_stride = blockDim.x * 4;
    int col = tid * 4;

    for (; col + 3 < cols; col += vec_stride) {
        float4 v4 = *reinterpret_cast<const float4*>(data + row_offset + col);
        local_sum += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }

    /* Handle remaining elements (if cols not multiple of 4) */
    for (int c = tid + (cols & ~3); c < cols; c += blockDim.x) {
        float v = data[row_offset + c];
        local_sum += v * v;
    }

    /* ---- Phase 2 : reduction within the block ----------------------------*/
    sdata[tid] = local_sum;
    __syncthreads();

    for (int stride = blockDim.x >> 1; stride; stride >>= 1) {
        if (tid < stride)
            sdata[tid] += sdata[tid + stride];
        __syncthreads();
    }

    float inv_norm = rsqrtf(sdata[0] + EPS);

    /* ---- Phase 3 : normalisation -----------------------------------------*/
    for (int c = tid; c < cols; c += blockDim.x) {
        data[row_offset + c] *= inv_norm;
    }
}

