// -----------------------------------------------------------------------------
// Tunables
// -----------------------------------------------------------------------------
constexpr int BLOCK_SIZE       = 256;  // threads per block (4 wavefronts)
constexpr int ITEMS_PER_THREAD = 16;   // elements per thread
constexpr int TILE_SIZE        = BLOCK_SIZE * ITEMS_PER_THREAD; // 4096
// -----------------------------------------------------------------------------
// Kernel : inclusive cumulative product along dim=1 (per row).
// Supports arbitrary n_cols via sequential tiles processed by the *same* block.
// One block processes one row; keeps running prefix in register for carry-over.
// -----------------------------------------------------------------------------
template<int BS, int IPT>
__global__ __launch_bounds__(BS, 4)
void cumprod_dim1_kernel_tiled(const float* __restrict__ in,
                               float*       __restrict__ out,
                               int n_rows,
                               int n_cols)
{
    const int row = blockIdx.x;
    if (row >= n_rows) return;

    const float* row_in  = in  + static_cast<long long>(row) * n_cols;
    float*       row_out = out + static_cast<long long>(row) * n_cols;

    extern __shared__ float smem[];    // size BS
    float* thread_prod = smem;

    // running prefix product from all previous tiles processed by THIS block
    float carry = 1.0f;

    for (int tile_start = 0; tile_start < n_cols; tile_start += BS * IPT) {

        // ----------------------------------------
        // 1) Compute per-thread local prefix products
        // ----------------------------------------
        const int base_idx = tile_start + threadIdx.x * IPT;

        float local[IPT];
        #pragma unroll
        for (int i = 0; i < IPT; ++i) {
            int global_idx = base_idx + i;
            float val = (global_idx < n_cols) ? row_in[global_idx] : 1.0f;
            local[i] = (i == 0) ? val : val * local[i - 1];
        }

        // store last product of this thread
        thread_prod[threadIdx.x] = local[IPT - 1];
        __syncthreads();

        // ----------------------------------------
        // 2) Inclusive scan over threads (Kogge-Stone)
        // ----------------------------------------
        for (int offset = 1; offset < BS; offset <<= 1) {
            float tmp = (threadIdx.x >= offset) ? thread_prod[threadIdx.x - offset] : 1.0f;
            __syncthreads();
            thread_prod[threadIdx.x] *= tmp;
            __syncthreads();
        }

        // factor to multiply this thread's locals
        float thread_factor = (threadIdx.x == 0) ? 1.0f : thread_prod[threadIdx.x - 1];
        thread_factor *= carry;

        // ----------------------------------------
        // 3) Write out scaled results
        // ----------------------------------------
        #pragma unroll
        for (int i = 0; i < IPT; ++i) {
            int global_idx = base_idx + i;
            if (global_idx < n_cols)
                row_out[global_idx] = local[i] * thread_factor;
        }

        // ----------------------------------------
        // 4) Update carry for next tile
        // ----------------------------------------
        __syncthreads();
        if (threadIdx.x == BS - 1) {
            // thread_prod[BS-1] now holds inclusive product of whole tile
            thread_prod[0] = thread_prod[BS - 1] * carry;
        }
        __syncthreads();
        carry = thread_prod[0];
        __syncthreads(); // ensure carry updated before next tile
    }
}

