constexpr int THREADS_PER_BLOCK = 256;
constexpr int VEC               = 4;   // float4 vectorization

/* -------------------------------------------------------------------------- */
/* Kernel 1: Per-block reduction of sum of squares                            */
/* -------------------------------------------------------------------------- */
__global__ __launch_bounds__(THREADS_PER_BLOCK, 4)
void reduce_sumsq_kernel(const float* __restrict__ x,
                         double* __restrict__ partial,
                         size_t n)
{
    extern __shared__ double sdata[];          /* THREADS_PER_BLOCK doubles */
    double thread_sum = 0.0;

    /* Cast to float4 for coalesced vector loads */
    const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x);
    size_t      vec_elems         = n / VEC;
    size_t      global_tid        = blockIdx.x * blockDim.x + threadIdx.x;
    size_t      grid_stride       = gridDim.x * blockDim.x;

    /* Vectorised loop */
    for (size_t idx = global_tid; idx < vec_elems; idx += grid_stride) {
        float4 v = x4[idx];
        thread_sum += static_cast<double>(v.x) * v.x +
                      static_cast<double>(v.y) * v.y +
                      static_cast<double>(v.z) * v.z +
                      static_cast<double>(v.w) * v.w;
    }

    /* Handle leftover (<4) elements – one element per logical thread id */
    size_t scalar_start = vec_elems * VEC + global_tid;
    for (size_t i = scalar_start; i < n; i += grid_stride) {
        double v = x[i];
        thread_sum += v * v;
    }

    /* Block-level reduction in shared memory (bank-conflict-free for doubles) */
    sdata[threadIdx.x] = thread_sum;
    __syncthreads();

    for (unsigned int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride)
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
        __syncthreads();
    }

    if (threadIdx.x == 0)
        partial[blockIdx.x] = sdata[0];
}

/* -------------------------------------------------------------------------- */
/* Kernel 2: Element-wise normalisation                                       */
/* -------------------------------------------------------------------------- */
__global__ __launch_bounds__(THREADS_PER_BLOCK, 4)
void normalize_kernel(const float* __restrict__ x,
                      float*       __restrict__ out,
                      float        inv_norm,
                      size_t       n)
{
    const float4* __restrict__ x4  = reinterpret_cast<const float4*>(x);
    float4*       __restrict__ o4  = reinterpret_cast<float4*>(out);
    size_t        vec_elems        = n / VEC;
    size_t        global_tid       = blockIdx.x * blockDim.x + threadIdx.x;
    size_t        grid_stride      = gridDim.x * blockDim.x;

    /* Vectorised portion */
    for (size_t idx = global_tid; idx < vec_elems; idx += grid_stride) {
        float4 v = x4[idx];
        v.x *= inv_norm;
        v.y *= inv_norm;
        v.z *= inv_norm;
        v.w *= inv_norm;
        o4[idx] = v;
    }

    /* Leftover elements (<4) */
    size_t scalar_start = vec_elems * VEC + global_tid;
    for (size_t i = scalar_start; i < n; i += grid_stride) {
        out[i] = x[i] * inv_norm;
    }
}

