void frobenius_norm_normalize(const float* d_x,
                              float*       d_out,
                              size_t       n,
                              hipStream_t  stream = 0)
{
    /* Heuristic grid sizing */
    hipDeviceProp_t prop;
    int device;
    HIP_CHECK(hipGetDevice(&device));
    HIP_CHECK(hipGetDeviceProperties(&prop, device));
    const size_t max_blocks = prop.multiProcessorCount * 8;

    size_t vec_elems  = (n + VEC - 1) / VEC;
    size_t red_blocks = (vec_elems + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK;
    red_blocks        = red_blocks ? (red_blocks > max_blocks ? max_blocks : red_blocks) : 1;

    /* Allocate partial buffer */
    double* d_partial;
    HIP_CHECK(hipMalloc(&d_partial, red_blocks * sizeof(double)));

    size_t smem_bytes = THREADS_PER_BLOCK * sizeof(double);
    reduce_sumsq_kernel<<<red_blocks, THREADS_PER_BLOCK, smem_bytes, stream>>>(
        d_x, d_partial, n);

    /* Copy partials back & finalise on host */
    double* h_partial = static_cast<double*>(malloc(red_blocks * sizeof(double)));
    HIP_CHECK(hipMemcpyAsync(h_partial, d_partial, red_blocks * sizeof(double),
                             hipMemcpyDeviceToHost, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    long double total = 0.0;
    for (size_t i = 0; i < red_blocks; ++i) total += h_partial[i];

    free(h_partial);
    HIP_CHECK(hipFree(d_partial));

    float inv_norm = (total > 0.0) ? 1.0f / static_cast<float>(std::sqrt(total)) : 0.0f;

    /* Normalisation launch */
    size_t norm_blocks = (vec_elems + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK;
    norm_blocks        = norm_blocks ? (norm_blocks > max_blocks ? max_blocks : norm_blocks) : 1;

    normalize_kernel<<<norm_blocks, THREADS_PER_BLOCK, 0, stream>>>(
        d_x, d_out, inv_norm, n);
}

