template<int ROWS, int COLS>
struct AccumFrag {
    float v[ROWS][COLS];
    __device__ void clear() {
        #pragma unroll
        for (int i = 0; i < ROWS; ++i)
            #pragma unroll
            for (int j = 0; j < COLS; ++j)
                v[i][j] = 0.f;
    }
};

__global__ __launch_bounds__(BLOCK_THREADS, 2)
void matmul_kernel(const float* __restrict__ A,
                   const float* __restrict__ B,
                   float* __restrict__ C,
                   int M, int N, int K)
{
    __shared__ float As[BM * BK];      // 128*32 = 4096 floats  (16 KB)
    __shared__ float Bs[BK * BN];      // 32*128 = 4096 floats  (16 KB)

    const int tx = threadIdx.x;          // 0..15
    const int ty = threadIdx.y;          // 0..15
    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;
    const int linear_tid = ty * TX + tx; // 0..255

    AccumFrag<8,8> acc;
    acc.clear();

    const bool full_m = (blockRow + BM) <= M;
    const bool full_n = (blockCol + BN) <= N;

    for (int kb = 0; kb < K; kb += BK) {

        // Load A and B tiles into shared memory --------------------------------
        #pragma unroll
        for (int s = 0; s < 16; ++s) {                 // 4096 / 256 = 16 elems per thread
            int idx      = s * BLOCK_THREADS + linear_tid;   // 0 .. 4095

            /* ---- A tile ---- */
            int aRowTile = idx / BK;           // 0 .. 127
            int aColTile = idx - aRowTile * BK;// == idx % BK
            int gArow    = blockRow + aRowTile;
            int gAcol    = kb       + aColTile;

            if (full_m) {                      // avoid per-element branch when inside
                As[idx] = (gAcol < K) ? A[gArow * K + gAcol] : 0.f;
            } else {
                As[idx] = (gArow < M && gAcol < K) ? A[gArow * K + gAcol] : 0.f;
            }

            /* ---- B tile ---- */
            int bRowTile = idx / BN;           // 0 .. 31
            int bColTile = idx - bRowTile * BN;// == idx % BN
            int gBrow    = kb + bRowTile;
            int gBcol    = blockCol + bColTile;

            if (full_n) {
                Bs[idx] = (gBrow < K) ? B[gBrow * N + gBcol] : 0.f;
            } else {
                Bs[idx] = (gBrow < K && gBcol < N) ? B[gBrow * N + gBcol] : 0.f;
            }
        }
        __syncthreads();

        // Compute on the loaded tiles -----------------------------------------
        #pragma unroll
        for (int k = 0; k < BK; ++k) {

            float bReg[8];
            #pragma unroll
            for (int j = 0; j < 8; ++j) {
                bReg[j] = Bs[k * BN + tx * 8 + j];   // contiguous across X
            }

            #pragma unroll
            for (int i = 0; i < 8; ++i) {
                float aVal = As[(ty * 8 + i) * BK + k];
                #pragma unroll
                for (int j = 0; j < 8; ++j)
                    acc.v[i][j] += aVal * bReg[j];
            }
        }
        __syncthreads();
    }

    // Store results ------------------------------------------------------------
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
        int gRow = blockRow + ty * 8 + i;
        if (gRow < M) {
            #pragma unroll
            for (int j = 0; j < 8; ++j) {
                int gCol = blockCol + tx * 8 + j;
                if (gCol < N)
                    C[gRow * N + gCol] = acc.v[i][j];
            }
        }
    }
}

