constexpr int THREADS_PER_BLOCK = 256;

/* 
 * 1-D transposed convolution kernel.
 * Each block handles one (batch,n) × (output_channel,out_c) pair
 * and a TILE of output positions along the length dimension.
 * We stage the weights of the current out_c into shared memory
 * (Cin × K floats) to drastically cut global reads.
 */
extern "C"
__global__ __launch_bounds__(THREADS_PER_BLOCK, 4)
void conv1d_transpose_kernel(const float* __restrict__ input,   // [N, Cin, Lin]
                             const float* __restrict__ weight,  // [Cin, Cout, K]
                             const float* __restrict__ bias,    // [Cout] (nullable)
                             float* __restrict__ output,        // [N, Cout, Lout]
                             int N, int Cin, int Cout,
                             int Lin, int K,
                             int stride, int padding, int out_pad,
                             int Lout)
{
    extern __shared__ float sh_w[]; // size = Cin * K

    int n      = blockIdx.z;   // batch index
    int out_c  = blockIdx.y;   // output channel handled by this block
    int tid    = threadIdx.x;

    /* Load weights for (out_c) into shared memory ---------------------- */
    int num_w = Cin * K;
    for (int idx = tid; idx < num_w; idx += blockDim.x) {
        int in_c = idx / K;
        int k    = idx % K;
        sh_w[idx] = weight[((in_c * Cout + out_c) * K) + k];
    }
    __syncthreads();

    /* Convenience offsets */
    const size_t in_batch_offset  = static_cast<size_t>(n) * Cin * Lin;
    const size_t out_batch_offset = static_cast<size_t>(n) * Cout * Lout;
    const float bias_val = bias ? bias[out_c] : 0.0f;

    /* Process potentially many output positions in strides of grid size */
    const int global_threads = gridDim.x * blockDim.x;
    for (int l_out = blockIdx.x * blockDim.x + tid; l_out < Lout; l_out += global_threads)
    {
        float acc = bias_val;

        /* For every kernel position ----------------- */
#pragma unroll 4
        for (int k = 0; k < K; ++k)
        {
            int lhs = l_out + padding - k;
            if (lhs < 0)         continue;
            if (lhs % stride)    continue;
            int l_in = lhs / stride;
            if (l_in >= Lin)     continue;

            /* For every input channel (weights already in shared memory) */
            size_t in_base = in_batch_offset + static_cast<size_t>(l_in);
            int w_idx_base = k;          /* sh_w index = in_c*K + k */

#pragma unroll 4
            for (int in_c = 0; in_c < Cin; ++in_c)
            {
                float in_val = input[in_base + static_cast<size_t>(in_c)*Lin];
                float w_val  = sh_w[in_c * K + w_idx_base];
                acc += in_val * w_val;
            }
        }

        /* Store result -------------------------------------------------- */
        output[out_batch_offset + static_cast<size_t>(out_c) * Lout + l_out] = acc;
    }
}

