    int tid = blockIdx.x * blockDim.x + threadIdx.x;      // linear thread id
    int grid_stride_elems = gridDim.x * blockDim.x * VEC; // elements processed per loop

    for (int base = tid * VEC; base < n; base += grid_stride_elems) {
        if (base + VEC - 1 < n) {
            // Aligned vector load/store
            float4 val = *reinterpret_cast<const float4*>(x + base);
            val.x = tanhf(val.x);
            val.y = tanhf(val.y);
            val.z = tanhf(val.z);
            val.w = tanhf(val.w);
            *reinterpret_cast<float4*>(y + base) = val;
        } else {
            // Tail elements
            for (int k = 0; k < VEC && base + k < n; ++k)
                y[base + k] = tanhf(x[base + k]);
        }
    }
}

