/* -----------------------------------------------------------
 * Helper macros for error checking
 * ----------------------------------------------------------- */
#define HIP_CHECK(cmd)                                                  \
    do {                                                                \
        hipError_t e = (cmd);                                           \
        if (e != hipSuccess) {                                          \
