/* -----------------------------------------------------------
 * Device utility : warp-level reduction (wavefront = 64)
 * ----------------------------------------------------------- */
__device__ inline float warp_reduce_sum(float val)
{
    for (int offset = 32; offset > 0; offset >>= 1)
        val += __shfl_down(val, offset);
    return val;
}

/* -----------------------------------------------------------
 * Kernel : compute sum of Hinge Loss values
 * ----------------------------------------------------------- */
__global__ __launch_bounds__(THREADS_PER_BLOCK, 4)
void hinge_loss_sum_kernel(const float* __restrict__ preds,
                            const float* __restrict__ targets,
                            int n,
                            float* __restrict__ g_sum)
{
    // Each thread processes strided elements
    int global_tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = gridDim.x * blockDim.x;

    float local_sum = 0.0f;

    for (int i = global_tid; i < n; i += total_threads)
    {
        float prod = preds[i] * targets[i];
        float diff = 1.0f - prod;
        // Branch-free clamp
        local_sum += diff > 0.0f ? diff : 0.0f;
    }

    // Warp reduction
    local_sum = warp_reduce_sum(local_sum);

    // Shared memory for inter-warp reduction
    __shared__ float shared[THREADS_PER_BLOCK / 64]; // one per warp
    int lane = threadIdx.x & 63;
    int warp = threadIdx.x >> 6;

    if (lane == 0)
        shared[warp] = local_sum;
    __syncthreads();

    // First warp reduces the partial sums
    if (warp == 0)
    {
        float block_sum = (lane < (THREADS_PER_BLOCK / 64)) ? shared[lane] : 0.0f;
        block_sum = warp_reduce_sum(block_sum);

        if (lane == 0)
            atomicAdd(g_sum, block_sum);
    }
}

