//------------------------------------------------------------------------------
// Scatter-based 3-D transposed convolution
//------------------------------------------------------------------------------
// Layouts (row–major, fastest-changing last):
//   input  : N, C_in, D_in, H_in, W_in
//   weight : C_in, C_out, kD, kH, kW
//   output : N, C_out, D_out, H_out, W_out
//------------------------------------------------------------------------------
__global__ __launch_bounds__(256)
void conv_transpose3d_kernel_scatter(const float *__restrict__ input,
                                     const float *__restrict__ weight,
                                     float *__restrict__ output,
                                     int N, int C_in, int C_out,
                                     int D_in, int H_in, int W_in,
                                     int kD, int kH, int kW,
                                     int stride_d, int stride_h, int stride_w,
                                     int pad_d, int pad_h, int pad_w,
                                     int dil_d, int dil_h, int dil_w,
                                     int D_out, int H_out, int W_out)
{
    long long total_in = (long long)N * C_in * D_in * H_in * W_in;
    long long tid = blockIdx.x * blockDim.x + threadIdx.x;

    for (long long in_idx = tid; in_idx < total_in; in_idx += (long long)gridDim.x * blockDim.x) {

        // Decompose flat input index -> (n, ic, id, ih, iw)
        long long t = in_idx;
        int iw  = t % W_in;   t /= W_in;
        int ih  = t % H_in;   t /= H_in;
        int id  = t % D_in;   t /= D_in;
        int ic  = t % C_in;   t /= C_in;
        int n   = (int)t;

        float in_val = input[in_idx];

        // Pre-compute part of weight base offset for this ic
        const long long w_ic_base = (long long)ic * C_out * kD * kH * kW;

        for (int kd = 0; kd < kD; ++kd) {
            int od = id * stride_d - pad_d + kd * dil_d;
            if (od < 0 || od >= D_out) continue;

            const long long w_kd_base = w_ic_base + (long long)kd * kH * kW * C_out;

            for (int kh = 0; kh < kH; ++kh) {
                int oh = ih * stride_h - pad_h + kh * dil_h;
                if (oh < 0 || oh >= H_out) continue;

                const long long w_kh_base = w_kd_base + (long long)kh * kW * C_out;

                for (int kw = 0; kw < kW; ++kw) {
                    int ow = iw * stride_w - pad_w + kw * dil_w;
                    if (ow < 0 || ow >= W_out) continue;

                    const float *w_ptr = weight + w_kh_base + (long long)kw * C_out;

                    // Iterate over output channels in increments of 4 for better memory access
                    for (int oc = 0; oc < C_out; oc += 4) {
                        float4 w4 = *reinterpret_cast<const float4*>(w_ptr + oc);

                        long long base_out = (((((long long)n * C_out + oc) * D_out + od)
                                               * H_out + oh) * W_out + ow);

                        atomicAdd(output + base_out,     in_val * w4.x);
                        atomicAdd(output + base_out + D_out * H_out * W_out, in_val * w4.y);
                        atomicAdd(output + base_out + 2LL * D_out * H_out * W_out, in_val * w4.z);
                        atomicAdd(output + base_out + 3LL * D_out * H_out * W_out, in_val * w4.w);
                    }
                }
            }
        }
    }
}

//------------------------------------------------------------------------------
// Bias addition kernel
//------------------------------------------------------------------------------
__global__ __launch_bounds__(256)
void add_bias_kernel(float *output, const float *bias,
                     long long spatial, int C_out, long long total_out)
{
    long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    for (long long idx = tid; idx < total_out; idx += (long long)gridDim.x * blockDim.x) {
        int oc = (idx / spatial) % C_out;
        output[idx] += bias[oc];
    }
}

