int main() {
    // Parameters
    const int batch_size  = 16;
    const int in_channels = 32;
    const int out_channels= 64;
    const int kernel_size = 3;
    const int depth  = 16;
    const int height = 32;
    const int width  = 32;
    const int stride = 2;
    const int padding= 1;
    const int dilation = 2;

    // Derived sizes
    const int D_out = (depth  - 1) * stride - 2 * padding +
                      dilation * (kernel_size - 1) + 1;
    const int H_out = (height - 1) * stride - 2 * padding +
                      dilation * (kernel_size - 1) + 1;
    const int W_out = (width  - 1) * stride - 2 * padding +
                      dilation * (kernel_size - 1) + 1;

    long long in_elems  = (long long)batch_size * in_channels * depth * height * width;
    long long w_elems   = (long long)in_channels * out_channels *
                          kernel_size * kernel_size * kernel_size;
    long long out_elems = (long long)batch_size * out_channels *
                          D_out * H_out * W_out;

    // Host buffers
    float *h_input  = (float*)malloc(sizeof(float) * in_elems);
    float *h_weight = (float*)malloc(sizeof(float) * w_elems);
    float *h_bias   = (float*)malloc(sizeof(float) * out_channels);
    float *h_output = (float*)malloc(sizeof(float) * out_elems);

    for (long long i = 0; i < in_elems;  ++i) h_input[i]  = frand();
    for (long long i = 0; i < w_elems;   ++i) h_weight[i] = frand();
    for (int       i = 0; i < out_channels; ++i) h_bias[i] = frand();

    // Device buffers
    float *d_input, *d_weight, *d_bias, *d_output;
    HIP_CHECK(hipMalloc(&d_input,  sizeof(float) * in_elems));
    HIP_CHECK(hipMalloc(&d_weight, sizeof(float) * w_elems));
    HIP_CHECK(hipMalloc(&d_bias,   sizeof(float) * out_channels));
    HIP_CHECK(hipMalloc(&d_output, sizeof(float) * out_elems));

    HIP_CHECK(hipMemcpy(d_input,  h_input,  sizeof(float) * in_elems,  hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_weight, h_weight, sizeof(float) * w_elems,   hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_bias,   h_bias,   sizeof(float) * out_channels, hipMemcpyHostToDevice));

    // Zero output
    HIP_CHECK(hipMemset(d_output, 0, sizeof(float) * out_elems));

    // Launch main scatter kernel
