                       kernel_size, kernel_size, kernel_size,
                       stride, stride, stride,
                       padding, padding, padding,
                       dilation, dilation, dilation,
                       D_out, H_out, W_out);

    // Add bias
    long long spatial = (long long)D_out * H_out * W_out;
    long long total_out = out_elems;
    int blocks_bias = (int)((total_out + threads - 1) / threads);
    hipLaunchKernelGGL(add_bias_kernel,
                       dim3(blocks_bias), dim3(threads), 0, 0,
                       d_output, d_bias, spatial, out_channels, total_out);

    HIP_CHECK(hipDeviceSynchronize());
    HIP_CHECK(hipMemcpy(h_output, d_output, sizeof(float) * out_elems, hipMemcpyDeviceToHost));

    // Print a few results for sanity
    for (int i = 0; i < 5 && i < out_elems; ++i)
