/* ----------------------- GPU KERNEL ----------------------- */
static __global__ __launch_bounds__(256, 4)
void argmin_dim1_kernel(const float* __restrict__ input,
                        int batch_size,
                        int dim1,
                        int dim2,
                        int* __restrict__ output)
{
    const int j      = blockIdx.x * blockDim.x + threadIdx.x;   // dim2 index
    const int batch  = blockIdx.y;                              // batch index

    if (batch >= batch_size || j >= dim2) return;

    const float* row_ptr = input + batch * dim1 * dim2 + j;     // (0, j) of current batch

    float min_val = row_ptr[0];
    int   min_idx = 0;

    // Unroll by 4 for better ILP
    int i = 1;
    for (; i + 3 < dim1; i += 4)
    {
        float v1 = row_ptr[i * dim2];
        float v2 = row_ptr[(i + 1) * dim2];
        float v3 = row_ptr[(i + 2) * dim2];
        float v4 = row_ptr[(i + 3) * dim2];

        if (v1 < min_val) { min_val = v1; min_idx = i; }
        if (v2 < min_val) { min_val = v2; min_idx = i + 1; }
        if (v3 < min_val) { min_val = v3; min_idx = i + 2; }
        if (v4 < min_val) { min_val = v4; min_idx = i + 3; }
    }
    // Handle remaining elements
    for (; i < dim1; ++i)
    {
        float v = row_ptr[i * dim2];
        if (v < min_val) { min_val = v; min_idx = i; }
    }

    output[batch * dim2 + j] = min_idx;
}

