constexpr int BLOCK_SIZE = 256;   // multiple of wavefront(64)

__launch_bounds__(BLOCK_SIZE, 4)
__global__ void maxpool2d_dilated_kernel(
        const float* __restrict__ in,
        float* __restrict__ out,
        int N, int C, int H, int W,
        int kernel_h, int kernel_w,
        int stride_h, int stride_w,
        int pad_h, int pad_w,
        int dilation_h, int dilation_w,
        int outH, int outW)
{
    const int total = N * C * outH * outW;
    int gid = blockIdx.x * blockDim.x + threadIdx.x;

    for (int tid = gid; tid < total; tid += blockDim.x * gridDim.x)
    {
        // Decompose flattened index -> (n, c, oh, ow)
        int tmp = tid;
        int ow = tmp % outW;  tmp /= outW;
        int oh = tmp % outH;  tmp /= outH;
        int c  = tmp % C;     tmp /= C;
        int n  = tmp;

        const int in_h_start = oh * stride_h - pad_h;
        const int in_w_start = ow * stride_w - pad_w;

        float max_val = -FLT_MAX;

        // Manually unrolled 2x2 kernel (kernel_h = kernel_w = 2)
        int ih0 = in_h_start;
        int ih1 = in_h_start + dilation_h;
        int iw0 = in_w_start;
        int iw1 = in_w_start + dilation_w;

        const int base_nc = (n * C + c) * H;

        if ((unsigned)ih0 < (unsigned)H) {
            const int row0 = (base_nc + ih0) * W;
            if ((unsigned)iw0 < (unsigned)W) {
                float v = in[row0 + iw0];
                max_val = v > max_val ? v : max_val;
            }
            if ((unsigned)iw1 < (unsigned)W) {
                float v = in[row0 + iw1];
                max_val = v > max_val ? v : max_val;
            }
        }
        if ((unsigned)ih1 < (unsigned)H) {
            const int row1 = (base_nc + ih1) * W;
            if ((unsigned)iw0 < (unsigned)W) {
                float v = in[row1 + iw0];
                max_val = v > max_val ? v : max_val;
            }
            if ((unsigned)iw1 < (unsigned)W) {
                float v = in[row1 + iw1];
                max_val = v > max_val ? v : max_val;
            }
        }

        out[((n * C + c) * outH + oh) * outW + ow] = max_val;
    }
}

