constexpr int THREADS_PER_BLOCK = 256;
constexpr float EPS = 1e-12f;

__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void kl_div_kernel(const float* __restrict__ preds,
                   const float* __restrict__ targets,
                   float* __restrict__ result,
                   const int num_classes)
{
    __shared__ float sdata[THREADS_PER_BLOCK];

    const int batch_idx = blockIdx.x;
    const int tid       = threadIdx.x;
    const int base      = batch_idx * num_classes;

    float local_sum = 0.0f;

    // Loop over classes – each iteration processes one element per thread.
    #pragma unroll 4
    for (int cls = tid; cls < num_classes; cls += THREADS_PER_BLOCK) {
        float t = targets[base + cls];
        float p = preds  [base + cls];

        t = t < EPS ? EPS : t;
        p = p < EPS ? EPS : p;

        local_sum += t * (__logf(t) - __logf(p));
    }

    sdata[tid] = local_sum;
    __syncthreads();

    // Block-wide reduction
    for (int stride = THREADS_PER_BLOCK >> 1; stride > 0; stride >>= 1) {
        if (tid < stride)
            sdata[tid] += sdata[tid + stride];
        __syncthreads();
    }

    if (tid == 0)
        atomicAdd(result, sdata[0]);
}

int main() {
    constexpr int BATCH_SIZE   = 128;
    constexpr int NUM_CLASSES  = 4096;
    const     int TOTAL_ELEMS  = BATCH_SIZE * NUM_CLASSES;

    std::vector<float> h_preds  (TOTAL_ELEMS);
    std::vector<float> h_targets(TOTAL_ELEMS);

    // Generate random logits and apply softmax per row
    std::mt19937 gen(0);
    std::normal_distribution<float> dist(0.f, 1.f);

    for (int row = 0; row < BATCH_SIZE; ++row) {
        float max_p = -INFINITY, max_t = -INFINITY;

        // Generate logits & track row-wise max
        for (int c = 0; c < NUM_CLASSES; ++c) {
            float lp = dist(gen);
            float lt = dist(gen);
            h_preds  [row * NUM_CLASSES + c] = lp;
            h_targets[row * NUM_CLASSES + c] = lt;
            max_p = lp > max_p ? lp : max_p;
            max_t = lt > max_t ? lt : max_t;
        }

        // Exponentiate & sum
        float sum_p = 0.f, sum_t = 0.f;
        for (int c = 0; c < NUM_CLASSES; ++c) {
            float ep = std::exp(h_preds  [row * NUM_CLASSES + c] - max_p);
            float et = std::exp(h_targets[row * NUM_CLASSES + c] - max_t);
            h_preds  [row * NUM_CLASSES + c] = ep;
            h_targets[row * NUM_CLASSES + c] = et;
            sum_p += ep;
            sum_t += et;
        }

        // Normalize to obtain probabilities
        for (int c = 0; c < NUM_CLASSES; ++c) {
            h_preds  [row * NUM_CLASSES + c] /= sum_p;
            h_targets[row * NUM_CLASSES + c] /= sum_t;
        }
    }

    float *d_preds, *d_targets, *d_result;
    CHECK(hipMalloc(&d_preds  , TOTAL_ELEMS * sizeof(float)));
    CHECK(hipMalloc(&d_targets, TOTAL_ELEMS * sizeof(float)));
    CHECK(hipMalloc(&d_result , sizeof(float)));

    CHECK(hipMemcpy(d_preds  , h_preds.data()  , TOTAL_ELEMS * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_targets, h_targets.data(), TOTAL_ELEMS * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemset(d_result , 0               , sizeof(float)));

    const dim3 blocks(BATCH_SIZE);
    const dim3 threads(THREADS_PER_BLOCK);

    hipLaunchKernelGGL(kl_div_kernel,
                       blocks,
                       threads,
                       0,            // shared memory already statically allocated
                       0,            // default stream
                       d_preds,
                       d_targets,
                       d_result,
                       NUM_CLASSES);

    CHECK(hipDeviceSynchronize());

    float h_result = 0.f;
    CHECK(hipMemcpy(&h_result, d_result, sizeof(float), hipMemcpyDeviceToHost));

    float kl_divergence = h_result / static_cast<float>(BATCH_SIZE);
    std::cout << "KL Divergence (batchmean): " << kl_divergence << std::endl;

    CHECK(hipFree(d_preds));
    CHECK(hipFree(d_targets));
    CHECK(hipFree(d_result));
    return 0;
}

