constexpr int   WAVE_SIZE         = 64;      // gfx942 wavefront size
constexpr int   THREADS_PER_BLOCK = 256;     // 4 waves per block
constexpr size_t SHMEM_BYTES      = 0;       // no dynamic LDS

/* ---------------- Warp-level helpers ---------------- */
__device__ __forceinline__ float warp_reduce_max(float v)
{
#pragma unroll
    for (int off = WAVE_SIZE >> 1; off > 0; off >>= 1)
        v = fmaxf(v, __shfl_xor(v, off));
    return v;
}

__device__ __forceinline__ float warp_reduce_sum(float v)
{
#pragma unroll
    for (int off = WAVE_SIZE >> 1; off > 0; off >>= 1)
        v += __shfl_xor(v, off);
    return v;
}

/* --------------- Block-level reductions --------------- */
__device__ float block_reduce_max(float v)
{
    constexpr int WARPS = THREADS_PER_BLOCK / WAVE_SIZE;
    __shared__ float warp_max[WARPS];

    const int lane = threadIdx.x & (WAVE_SIZE - 1);
    const int wid  = threadIdx.x / WAVE_SIZE;

    v = warp_reduce_max(v);
    if (lane == 0) warp_max[wid] = v;
    __syncthreads();

    v = (threadIdx.x < WARPS) ? warp_max[lane] : -FLT_MAX;
    if (wid == 0) v = warp_reduce_max(v);

    v = __shfl(v, 0);   // broadcast
    return v;
}

__device__ float block_reduce_sum(float v)
{
    constexpr int WARPS = THREADS_PER_BLOCK / WAVE_SIZE;
    __shared__ float warp_sum[WARPS];

    const int lane = threadIdx.x & (WAVE_SIZE - 1);
    const int wid  = threadIdx.x / WAVE_SIZE;

    v = warp_reduce_sum(v);
    if (lane == 0) warp_sum[wid] = v;
    __syncthreads();

    v = (threadIdx.x < WARPS) ? warp_sum[lane] : 0.0f;
    if (wid == 0) v = warp_reduce_sum(v);

    v = __shfl(v, 0);   // broadcast
    return v;
}

/* --------------------- Kernel --------------------- */
__launch_bounds__(THREADS_PER_BLOCK, 2)
__global__ void softmax_kernel(const float* __restrict__ x,
                               float*       __restrict__ y,
                               int num_rows,
                               int num_cols)
{
    const int row = blockIdx.x;
    if (row >= num_rows) return;

    const float* row_ptr = x + static_cast<size_t>(row) * num_cols;
    float*       out_ptr = y + static_cast<size_t>(row) * num_cols;

    /* Vectorized processing: 4 floats per iteration */
    const int tid      = threadIdx.x;
    const int vec_cols = num_cols >> 2;               // num_cols / 4
    const int stride   = THREADS_PER_BLOCK;

    const float4* __restrict__ row_ptr_v4 =
        reinterpret_cast<const float4*>(row_ptr);

    /* -------- Pass-1 : maximum -------- */
    float local_max = -FLT_MAX;

    for (int idx = tid; idx < vec_cols; idx += stride) {
        float4 v = row_ptr_v4[idx];
        local_max = fmaxf(local_max, v.x);
        local_max = fmaxf(local_max, v.y);
        local_max = fmaxf(local_max, v.z);
        local_max = fmaxf(local_max, v.w);
    }

    const float row_max = block_reduce_max(local_max);

    /* -------- Pass-2 : exponentials + sum -------- */
    float local_sum = 0.0f;

    for (int idx = tid; idx < vec_cols; idx += stride) {
        float4 v = row_ptr_v4[idx];

        float4 e;
        e.x = expf(v.x - row_max);
        e.y = expf(v.y - row_max);
        e.z = expf(v.z - row_max);
        e.w = expf(v.w - row_max);

        float* dst = out_ptr + (idx << 2);
        dst[0] = e.x;
        dst[1] = e.y;
        dst[2] = e.z;
        dst[3] = e.w;

        local_sum += e.x + e.y + e.z + e.w;
    }

    const float row_sum   = block_reduce_sum(local_sum);
    const float inv_denom = 1.0f / row_sum;

    /* -------- Pass-3 : normalization -------- */
    float4* out_ptr_v4 = reinterpret_cast<float4*>(out_ptr);

    for (int idx = tid; idx < vec_cols; idx += stride) {
        float4 o = out_ptr_v4[idx];
        o.x *= inv_denom;
        o.y *= inv_denom;
        o.z *= inv_denom;
        o.w *= inv_denom;
        out_ptr_v4[idx] = o;
    }

    /* Handle tail (when num_cols not multiple of 4) */
    if ((num_cols & 3) && tid == 0) {
        for (int col = (num_cols & ~3); col < num_cols; ++col) {
            float e = expf(row_ptr[col] - row_max);
            out_ptr[col] = e * inv_denom;
        }
    }
}

