#define TILE_H          8
#define TILE_W          8
#define BLOCK_THREADS   64            // one full wavefront
#define MAX_KERNEL_SIZE 7

#define HIP_CHECK(cmd)                                                     \
    do {                                                                   \
        hipError_t e = (cmd);                                              \
        if (e != hipSuccess) {                                             \
            printf("HIP error \"%s\" at %s:%d\n", hipGetErrorString(e),    \
                   __FILE__, __LINE__);                                    \
            exit(EXIT_FAILURE);                                            \
        }                                                                  \
    } while (0)

// Each thread block processes one (n,c) pair and a TILE_H x TILE_W output tile
extern "C"
__global__ __launch_bounds__(BLOCK_THREADS, 4)
void depthwise_conv2d_dw(const float *__restrict__ input,
                         const float *__restrict__ weight,
                         const float *__restrict__ bias,
                         float *__restrict__ output,
                         int N, int C,
                         int H_in, int W_in,
                         int H_out, int W_out,
                         int K, int stride, int padding,
                         int has_bias)
{
    int tid = threadIdx.x;                // 0 .. 63
    int tx  = tid % TILE_W;               // thread's within-tile x coord
    int ty  = tid / TILE_W;               // thread's within-tile y coord

    int ow0 = blockIdx.x * TILE_W;        // tile origin in output
    int oh0 = blockIdx.y * TILE_H;

    int n  = blockIdx.z / C;              // batch index
    int c  = blockIdx.z % C;              // channel index

    int ow = ow0 + tx;
    int oh = oh0 + ty;

    bool active = (ow < W_out) && (oh < H_out);

    int in_c_stride  = H_in * W_in;
    int in_n_stride  = C * in_c_stride;
    int out_c_stride = H_out * W_out;
    int out_n_stride = C * out_c_stride;

    const float *in_ptr  = input  + n * in_n_stride  + c * in_c_stride;
    const float *w_ptr   = weight + c * K * K;
    float       *out_ptr = output + n * out_n_stride + c * out_c_stride;

    // Shared-memory tile (add +1 padding per row to kill bank conflicts)
    const int tileH_in = (TILE_H - 1) * stride + K;
    const int tileW_in = (TILE_W - 1) * stride + K;
    const int s_stride = tileW_in + 1;                // padded stride
    extern __shared__ float s_mem[];

    // Input origin (top-left) for current tile
    int ih_origin = oh0 * stride - padding;
    int iw_origin = ow0 * stride - padding;

    // Cooperative load
    for (int lid = tid; lid < tileH_in * tileW_in; lid += BLOCK_THREADS)
    {
        int sy = lid / tileW_in;
        int sx = lid - sy * tileW_in;

        int ih = ih_origin + sy;
        int iw = iw_origin + sx;

        float v = 0.0f;
        if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in)
            v = in_ptr[ih * W_in + iw];

        s_mem[sy * s_stride + sx] = v;
    }
    __syncthreads();

    // Compute convolution
    if (active)
    {
        float acc = has_bias ? bias[c] : 0.0f;
        int s_off_base = (ty * stride) * s_stride + (tx * stride);

        for (int kh = 0; kh < K; ++kh)
        {
            int row_off = s_off_base + kh * s_stride;
            for (int kw = 0; kw < K; ++kw)
            {
                float val = s_mem[row_off + kw];
                float w   = w_ptr[kh * K + kw];
                acc += val * w;
            }
        }
        out_ptr[oh * W_out + ow] = acc;
    }
}

// ------------------------------ Host stub ------------------------------
int main()
{
    const int N        = 16;
    const int C        = 3;
    const int H_in     = 128;
    const int W_in     = 256;
    const int K        = 3;
    const int stride   = 1;
    const int padding  = 0;
    const bool useBias = false;

    if (K > MAX_KERNEL_SIZE) {
        printf("Kernel size exceeds MAX_KERNEL_SIZE\n");
        return EXIT_FAILURE;
    }

    const int H_out = (H_in + 2 * padding - K) / stride + 1;
    const int W_out = (W_in + 2 * padding - K) / stride + 1;

    size_t in_elems   = N * C * H_in * W_in;
    size_t out_elems  = N * C * H_out * W_out;
    size_t weight_e   = C * K * K;
    size_t bias_e     = C;

    std::vector<float> h_in(in_elems);
    std::vector<float> h_w(weight_e);
    std::vector<float> h_b(bias_e, 0.0f);
    std::vector<float> h_out(out_elems, 0.0f);

    std::mt19937 gen(static_cast<uint32_t>(
        std::chrono::high_resolution_clock::now().time_since_epoch().count()));
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);

    for (auto &v : h_in) v = dist(gen);
    for (auto &v : h_w)  v = dist(gen);
    if (useBias)
        for (auto &v : h_b) v = dist(gen);

    float *d_in  = nullptr;
    float *d_w   = nullptr;
    float *d_b   = nullptr;
    float *d_out = nullptr;

    HIP_CHECK(hipMalloc(&d_in,  in_elems * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_w,   weight_e * sizeof(float)));
    HIP_CHECK(hipMalloc(&d_out, out_elems * sizeof(float)));
    if (useBias)
        HIP_CHECK(hipMalloc(&d_b, bias_e * sizeof(float)));

    HIP_CHECK(hipMemcpy(d_in, h_in.data(), in_elems * sizeof(float),
                        hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(d_w,  h_w.data(),  weight_e * sizeof(float),
                        hipMemcpyHostToDevice));
    if (useBias)
        HIP_CHECK(hipMemcpy(d_b, h_b.data(), bias_e * sizeof(float),
                            hipMemcpyHostToDevice));

    dim3 block(BLOCK_THREADS, 1, 1);
    dim3 grid((W_out + TILE_W - 1) / TILE_W,
              (H_out + TILE_H - 1) / TILE_H,
              N * C);

    const int tileH_in = (TILE_H - 1) * stride + K;
    const int tileW_in = (TILE_W - 1) * stride + K;
    const int s_stride = tileW_in + 1;
    size_t smem_bytes  = tileH_in * s_stride * sizeof(float);

    hipLaunchKernelGGL(depthwise_conv2d_dw, grid, block, smem_bytes, 0,
                       d_in, d_w, useBias ? d_b : nullptr, d_out,
                       N, C,
                       H_in, W_in,
                       H_out, W_out,
                       K, stride, padding,
                       useBias ? 1 : 0);
    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    HIP_CHECK(hipMemcpy(h_out.data(), d_out, out_elems * sizeof(float),
                        hipMemcpyDeviceToHost));

    HIP_CHECK(hipFree(d_in));
    HIP_CHECK(hipFree(d_w));
    HIP_CHECK(hipFree(d_out));
    if (useBias) HIP_CHECK(hipFree(d_b));

    printf("Depthwise convolution finished (output size = %zu elements).\n",
           h_out.size());
    return 0;
}

