template<int TILE_M, int TILE_N, int TILE_K>
__launch_bounds__(256, 4)
__global__ void tensor3d_matmul_kernel(const float* __restrict__ A,
                                       const float* __restrict__ B,
                                       float* __restrict__ C,
                                       int N, int M, int K, int L)
{
    constexpr int VEC_A = TILE_K / TILE_N; // how many K-elements each thread loads for A (assumes divisible)
    constexpr int VEC_B = TILE_K / TILE_M; // how many K-elements each thread loads for B

    const int n  = blockIdx.z;                    // batch index
    const int m0 = blockIdx.y * TILE_M;           // starting row of this tile in M
    const int l0 = blockIdx.x * TILE_N;           // starting col of this tile in L

    const int t_row = threadIdx.y;                // 0..TILE_M-1 ( 16 )
    const int t_col = threadIdx.x;                // 0..TILE_N-1 ( 16 )

    const int g_m = m0 + t_row;                   // global row this thread is responsible for
    const int g_l = l0 + t_col;                   // global column this thread is responsible for

    float accum = 0.0f;

    __shared__ float Asub[TILE_M][TILE_K + 1];    // +1 to break bank conflicts
    __shared__ float Bsub[TILE_K][TILE_N + 1];

    for (int k0 = 0; k0 < K; k0 += TILE_K) {

        /* --------- load A tile : each thread loads VEC_A contiguous elements ---------- */
        int k_base_a = t_col * VEC_A;             // within the TILE_K range
        #pragma unroll
        for (int i = 0; i < VEC_A; ++i) {
            int k_idx = k0 + k_base_a + i;
            float val = 0.0f;
            if (g_m < M && k_idx < K)
                val = A[((n * M + g_m) * K) + k_idx];
            Asub[t_row][k_base_a + i] = val;
        }

        /* --------- load B tile : each thread loads VEC_B elements ---------- */
        int k_base_b = t_row * VEC_B;
        #pragma unroll
        for (int i = 0; i < VEC_B; ++i) {
            int k_idx = k0 + k_base_b + i;
            float val = 0.0f;
            if (k_idx < K && g_l < L)
                val = B[k_idx * L + g_l];
            Bsub[k_base_b + i][t_col] = val;
        }

        __syncthreads();

        /* ---- compute partial products for this K tile ----- */
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk)
            accum = fmaf(Asub[t_row][kk], Bsub[kk][t_col], accum);

        __syncthreads();
    }

    if (g_m < M && g_l < L)
        C[((n * M + g_m) * L) + g_l] = accum;
}

int main()
{
    constexpr int N = 16;
    constexpr int M = 1024;
    constexpr int K = 2048;
    constexpr int L = 768;

    /* tuned tile sizes:   16x16 thread-block (256 thr)   */
    constexpr int TILE_M = 16;
    constexpr int TILE_N = 16;
    constexpr int TILE_K = 64;

    const size_t bytesA = static_cast<size_t>(N) * M * K * sizeof(float);
    const size_t bytesB = static_cast<size_t>(K) * L * sizeof(float);
    const size_t bytesC = static_cast<size_t>(N) * M * L * sizeof(float);

    std::vector<float> hA(bytesA / sizeof(float));
    std::vector<float> hB(bytesB / sizeof(float));
    std::vector<float> hC(bytesC / sizeof(float), 0.0f);

    for (size_t i = 0; i < hA.size(); ++i)
        hA[i] = static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX) - 0.5f;

    for (size_t i = 0; i < hB.size(); ++i)
        hB[i] = static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX) - 0.5f;

    float *dA = nullptr, *dB = nullptr, *dC = nullptr;
    HIP_CHECK(hipMalloc(&dA, bytesA));
    HIP_CHECK(hipMalloc(&dB, bytesB));
    HIP_CHECK(hipMalloc(&dC, bytesC));

    HIP_CHECK(hipMemcpy(dA, hA.data(), bytesA, hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(dB, hB.data(), bytesB, hipMemcpyHostToDevice));

    dim3 block(TILE_N, TILE_M, 1);          // 16 x 16 threads
    dim3 grid( (L + TILE_N - 1) / TILE_N,
               (M + TILE_M - 1) / TILE_M,
               N );

    hipLaunchKernelGGL(HIP_KERNEL_NAME(tensor3d_matmul_kernel<TILE_M, TILE_N, TILE_K>),
                       grid, block, 0, 0,
                       dA, dB, dC, N, M, K, L);

    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipMemcpy(hC.data(), dC, bytesC, hipMemcpyDeviceToHost));

    HIP_CHECK(hipFree(dA));
    HIP_CHECK(hipFree(dB));
    HIP_CHECK(hipFree(dC));

    std::cout << "Computation finished." << std::endl;
    return 0;
}

#include <hip/hip_runtime.h>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <iostream>

#define THREADS        64              // 1 wavefront
#define VEC            4               // columns per thread
#define K_PER_BLOCK    (THREADS * VEC) // columns per block

//— GPU kernel --------------------------------------------------------------
__launch_bounds__(THREADS, 8)
__global__ void tensor4d_matmul(const float *__restrict__ A,   // (b,i,j,l)
                                const float *__restrict__ B,   // (l,k)
                                float       *__restrict__ C,   // (b,i,j,k)
                                int BATCH, int I, int J, int L, int K)
{
    const int tid = threadIdx.x;

    /* decode logical coordinates -----------------------------------------*/
    const int kBlocks = (K + K_PER_BLOCK - 1) / K_PER_BLOCK;
    const int j       = blockIdx.x / kBlocks;          // 0 … J-1
    const int kBlock  = blockIdx.x - j * kBlocks;      // 0 … kBlocks-1
    const int i       = blockIdx.y;                    // 0 … I-1
    const int b       = blockIdx.z;                    // 0 … BATCH-1
    if (j >= J || i >= I || b >= BATCH) return;

    /* shared memory holds the whole A-slice for this (b,i,j) -------------*/
    extern __shared__ float sA[];                      // length L

    const size_t A_row_off = (((size_t)b * I + i) * J + j) * L;
    const size_t C_row_off = (((size_t)b * I + i) * J + j) * K;

    /* cooperative load of A[b,i,j,:] into LDS ----------------------------*/
    for (int l = tid; l < L; l += THREADS)
        sA[l] = A[A_row_off + l];
    __syncthreads();

    /* each thread computes VEC columns starting at k_base ----------------*/
    const int k_base = kBlock * K_PER_BLOCK + tid * VEC;

    float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
    const bool full_vec = (k_base + VEC - 1 < K);

    /* main reduction loop -------------------------------------------------*/
    for (int l = 0; l < L; ++l)
    {
        const float a_val = sA[l];
        const size_t b_offset = (size_t)l * K + k_base;

        float b0 = 0.f, b1 = 0.f, b2 = 0.f, b3 = 0.f;

        if (full_vec)
        {
            const float4 *b4 = reinterpret_cast<const float4*>(&B[b_offset]);
            float4 bv = *b4;           // 16-byte aligned guaranteed
            b0 = bv.x;  b1 = bv.y;  b2 = bv.z;  b3 = bv.w;
        }
        else
        {
            if (k_base + 0 < K) b0 = B[b_offset + 0];
            if (k_base + 1 < K) b1 = B[b_offset + 1];
            if (k_base + 2 < K) b2 = B[b_offset + 2];
            if (k_base + 3 < K) b3 = B[b_offset + 3];
        }

        acc0 += a_val * b0;
        acc1 += a_val * b1;
        acc2 += a_val * b2;
        acc3 += a_val * b3;
    }

    /* write back ----------------------------------------------------------*/
    float *cPtr = &C[C_row_off + k_base];
    if (k_base + 0 < K) cPtr[0] = acc0;
    if (k_base + 1 < K) cPtr[1] = acc1;
    if (k_base + 2 < K) cPtr[2] = acc2;
    if (k_base + 3 < K) cPtr[3] = acc3;
}

