constexpr int THREADS_PER_BLOCK = 256;   // multiple of 64 (wavefront size)
constexpr float EPS = 1e-12f;

/* Vectorized float4 load helper */
static __device__ __forceinline__ float4 load_float4(const float* p)
{
    return *reinterpret_cast<const float4*>(p);
}

/* Kernel: each block handles one row (batch element) */
__global__ __launch_bounds__(THREADS_PER_BLOCK, 4)
void l1_normalize_kernel(const float* __restrict__ in,
                         float* __restrict__       out,
                         int                       dim)
{
    extern __shared__ float ssum[];          // THREADS_PER_BLOCK floats

    const int row   = blockIdx.x;
    const int tid   = threadIdx.x;
    const int stride = THREADS_PER_BLOCK;

    const float* row_ptr = in + static_cast<size_t>(row) * dim;

    /* First pass: accumulate L1 norm (vectorized) */
    float partial = 0.f;

    // Vector width 4 if possible
    const int vecDim = dim >> 2;             // dim / 4
    const int vecIdxStart = tid;
    for (int v = vecIdxStart; v < vecDim; v += stride)
    {
        float4 vec = load_float4(row_ptr + (v << 2));
        partial += fabsf(vec.x) + fabsf(vec.y) + fabsf(vec.z) + fabsf(vec.w);
    }

    /* Handle remaining elements if dim not divisible by 4 (rare) */
    for (int idx = (vecDim << 2) + tid; idx < dim; idx += stride)
        partial += fabsf(row_ptr[idx]);

    /* Reduction within block */
    ssum[tid] = partial;
    __syncthreads();

    for (int offset = THREADS_PER_BLOCK >> 1; offset > 0; offset >>= 1) {
        if (tid < offset)
            ssum[tid] += ssum[tid + offset];
        __syncthreads();
    }

    const float inv_sum = 1.0f / (ssum[0] + EPS);

    /* Second pass: write normalized values (vectorized) */
    for (int v = vecIdxStart; v < vecDim; v += stride)
    {
        float4 vec = load_float4(row_ptr + (v << 2));
        vec.x *= inv_sum;
        vec.y *= inv_sum;
        vec.z *= inv_sum;
        vec.w *= inv_sum;
        *reinterpret_cast<float4*>(out + static_cast<size_t>(row) * dim + (v << 2)) = vec;
    }

    for (int idx = (vecDim << 2) + tid; idx < dim; idx += stride)
        out[static_cast<size_t>(row) * dim + idx] = row_ptr[idx] * inv_sum;
}

void l1_normalize(const float* d_in,
                  float*       d_out,
                  int          batch,
                  int          dim,
                  hipStream_t  stream = nullptr)
{
    dim3 grid(batch);
    dim3 block(THREADS_PER_BLOCK);
    size_t shared_bytes = THREADS_PER_BLOCK * sizeof(float);

    hipLaunchKernelGGL(l1_normalize_kernel,
                       grid,
                       block,
                       shared_bytes,
                       stream,
                       d_in,
                       d_out,
                       dim);
}

