// -----------------------------------------------------------------------------
// Utility: warp-synced reduction returning argmax
// -----------------------------------------------------------------------------
__device__ __forceinline__
void warp_argmax(float &best_val, int &best_idx)
{
    unsigned mask = 0xffffffffu;

    for (int offset = 32; offset > 0; offset >>= 1) {
        float other_val = __shfl_down(best_val, offset, 64);
        int   other_idx = __shfl_down(best_idx, offset, 64);
        if (other_val > best_val) {
            best_val = other_val;
            best_idx = other_idx;
        }
    }
}

// -----------------------------------------------------------------------------
// Kernel specialised for reduce-dim == 2 (fastest varying axis)
// Each block handles one (B,D1) row, 64 threads cooperate.
// -----------------------------------------------------------------------------
__global__ __launch_bounds__(64, 4)
void argmax_dim2_kernel(const float *__restrict__ x,
                        int   *__restrict__ out,
                        int B, int D1, int D2)
{
    const int b  = blockIdx.y;
    const int d1 = blockIdx.x;
    const int tid = threadIdx.x;

    const int row_offset = ((b * D1) + d1) * D2;

    float best_val = -FLT_MAX;
    int   best_idx = -1;

    for (int k = tid; k < D2; k += blockDim.x) {
        float v = x[row_offset + k];
        if (v > best_val) {
            best_val = v;
            best_idx = k;
        }
    }

    // Warp-level argmax
    warp_argmax(best_val, best_idx);

    if (tid == 0) {
        out[b * D1 + d1] = best_idx;
    }
}

// -----------------------------------------------------------------------------
// Kernel specialised for reduce-dim == 1
// Block handles one (B,D2) column, 64 threads cooperate.
// -----------------------------------------------------------------------------
__global__ __launch_bounds__(64, 4)
void argmax_dim1_kernel(const float *__restrict__ x,
                        int   *__restrict__ out,
                        int B, int D1, int D2)
{
    const int  b  = blockIdx.x;
    const int  d2 = blockIdx.y;
    const int  tid = threadIdx.x;

    float best_val = -FLT_MAX;
    int   best_idx = -1;

    // Base ptr at start of batch row + column d2
    const float *row_ptr = x + (b * D1 * D2) + d2;

    for (int d1 = tid; d1 < D1; d1 += blockDim.x) {
        float v = row_ptr[d1 * D2];
        if (v > best_val) {
            best_val = v;
            best_idx = d1;
        }
    }

    warp_argmax(best_val, best_idx);

    if (tid == 0) {
        out[b * D2 + d2] = best_idx;
    }
}

// -----------------------------------------------------------------------------
// Kernel specialised for reduce-dim == 0
// Block handles one (D1,D2) position, 32 threads are enough (batch is small).
// -----------------------------------------------------------------------------
__global__ __launch_bounds__(32, 4)
void argmax_dim0_kernel(const float *__restrict__ x,
                        int   *__restrict__ out,
                        int B, int D1, int D2)
{
    const int d1 = blockIdx.x;
    const int d2 = blockIdx.y;
    const int tid = threadIdx.x;

    float best_val = -FLT_MAX;
    int   best_idx = -1;

    for (int b = tid; b < B; b += blockDim.x) {
        float v = x[((b * D1) + d1) * D2 + d2];
        if (v > best_val) {
            best_val = v;
            best_idx = b;
        }
    }

    warp_argmax(best_val, best_idx);

    if (tid == 0) {
        out[d1 * D2 + d2] = best_idx;
    }
}

// -----------------------------------------------------------------------------
// Host driver
// -----------------------------------------------------------------------------
void launch_argmax(const float *d_in, int *d_out,
                   int B, int D1, int D2, int dim,
                   hipStream_t stream = 0)
{
    if (dim == 2) {
        dim3 grid(D1, B);
        dim3 block(64);
        hipLaunchKernelGGL(argmax_dim2_kernel, grid, block, 0, stream,
                           d_in, d_out, B, D1, D2);
    } else if (dim == 1) {
        dim3 grid(B, D2);
        dim3 block(64);
        hipLaunchKernelGGL(argmax_dim1_kernel, grid, block, 0, stream,
                           d_in, d_out, B, D1, D2);
    } else if (dim == 0) {
        dim3 grid(D1, D2);
        dim3 block(32);
        hipLaunchKernelGGL(argmax_dim0_kernel, grid, block, 0, stream,
                           d_in, d_out, B, D1, D2);
    } else {
        fprintf(stderr, "Unsupported reduction dim %d\n", dim);
        exit(EXIT_FAILURE);
    }
}

