__global__ __launch_bounds__(BLOCK_THREADS, 2)
void tril_matmul_kernel(const float* __restrict__ A,
                        const float* __restrict__ B,
                        float* __restrict__       C,
                        const int                 N)
{
    const int tx  = threadIdx.x;                     // 0 .. TILE-1
    const int ty  = threadIdx.y;
    const int row = blockIdx.y * TILE + ty;
    const int col = blockIdx.x * TILE + tx;

    /*  All blocks with y < x are strictly above the main diagonal.*/
    if (blockIdx.y < blockIdx.x) return;
    if (row >= N || col >= N)    return;

    __shared__ float As[TILE][TILE + 1];             // +1 avoids bank conflicts
    __shared__ float Bs[TILE][TILE + 1];

    float acc = 0.0f;

    const int tStart = col / TILE;
    const int tEnd   = min(row, N - 1) / TILE;

    for (int t = tStart; t <= tEnd; ++t) {
        const int a_col = t * TILE + tx;             // column index in A
        const int b_row = t * TILE + ty;             //    row index in B

        /*  Load A tile (only where valid & in lower–triangular region) */
        As[ty][tx] = (a_col < N && row >= a_col) ? A[row * N + a_col] : 0.0f;

        /*  Load B tile (only where valid & in lower–triangular region) */
        Bs[ty][tx] = (b_row < N && b_row >= col) ? B[b_row * N + col] : 0.0f;

        __syncthreads();

#pragma unroll
        for (int k = 0; k < TILE; ++k)
            acc += As[ty][k] * Bs[k][tx];

        __syncthreads();
    }

    /*  Store only lower–triangular elements */
    if (row >= col)
        C[row * N + col] = acc;
}

int main()
{
    constexpr int N = 4096;
    const size_t  bytes = static_cast<size_t>(N) * N * sizeof(float);

    float *hA = static_cast<float*>(malloc(bytes));
    float *hB = static_cast<float*>(malloc(bytes));
    float *hC = static_cast<float*>(malloc(bytes));

    std::srand(static_cast<unsigned>(std::time(nullptr)));

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            float va = static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX);
            float vb = static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX);
            hA[i * N + j] = (i >= j) ? va : 0.0f;
            hB[i * N + j] = (i >= j) ? vb : 0.0f;
        }

    float *dA, *dB, *dC;
    CHECK(hipMalloc(&dA, bytes));
    CHECK(hipMalloc(&dB, bytes));
    CHECK(hipMalloc(&dC, bytes));

    CHECK(hipMemcpy(dA, hA, bytes, hipMemcpyHostToDevice));
    CHECK(hipMemcpy(dB, hB, bytes, hipMemcpyHostToDevice));

    dim3 block(TILE, TILE);
    const int gridDim = (N + TILE - 1) / TILE;
    dim3 grid(gridDim, gridDim);

    hipLaunchKernelGGL(tril_matmul_kernel, grid, block, 0, 0, dA, dB, dC, N);
    CHECK(hipGetLastError());
    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(hC, dC, bytes, hipMemcpyDeviceToHost));

    /*  Spot-check correctness */
    for (int test = 0; test < 16; ++test) {
        int r = std::rand() % N;
        int c = std::rand() % (r + 1);
        float ref = 0.0f;
        for (int k = c; k <= r; ++k)
            ref += hA[r * N + k] * hB[k * N + c];
        float diff = std::fabs(ref - hC[r * N + c]);
        if (diff > 1e-2f) {
            fprintf(stderr, "Mismatch at (%d,%d): GPU=%f  REF=%f  DIFF=%f\n",
                    r, c, hC[r * N + c], ref, diff);
