constexpr int BLOCK_THREADS = 128;          // threads / block
constexpr int BLOCK_OUT      = 128;         // output elements / block (length dimension)

__global__ void avgpool1d_kernel_opt(const float* __restrict__ x,
                                     float* __restrict__ y,
                                     int N, int C, int L,
                                     int K, int S, int P,
                                     int OutL)
{
    extern __shared__ float s_data[];        // dynamically sized

    /* identify (n,c) this block processes */
    int n = blockIdx.z;
    int c = blockIdx.y;

    /* first output index along length handled by this block */
    int out_start = blockIdx.x * BLOCK_OUT;
    if (out_start >= OutL)
        return;

    /* pointer bases */
    const float* x_base = x + ((n * C + c) * L);
    float*       y_base = y + ((n * C + c) * OutL);

    /* input range that must be loaded to cover this block’s outputs             *
     * inclusive start index in input tensor: l_start_tile                       */
    int l_start_tile = out_start * S - P;
    int tile_len     = (BLOCK_OUT - 1) * S + K;   // length of shared-mem tile

    /* cooperative load of tile into shared memory */
    for (int t = threadIdx.x; t < tile_len; t += blockDim.x)
    {
        int li = l_start_tile + t;
        float val = (li >= 0 && li < L) ? x_base[li] : 0.0f; // zero-pad outside valid range
        s_data[t] = val;
    }
    __syncthreads();

    /* each thread computes multiple output elements (strided by warp) */
    for (int o_local = threadIdx.x; o_local < BLOCK_OUT && (out_start + o_local) < OutL;
         o_local += blockDim.x)
    {
        int lstart  = out_start * S - P + o_local * S;   // window start in input
        int offset  = o_local * S;                       // index into shared mem

        /* accumulate K values from shared memory */
        float sum = 0.0f;
        #pragma unroll
        for (int k = 0; k <  K; ++k)
            sum += s_data[offset + k];

        /* determine valid element count (do not include padding in divisor) */
        int lend        = lstart + K;
        int valid_start = lstart < 0 ? 0 : lstart;
        int valid_end   = lend   > L ? L : lend;
        int count       = valid_end - valid_start;
        if (count <= 0) count = 1;   // safety, should not occur

        y_base[out_start + o_local] = sum / static_cast<float>(count);
    }
}

/* convenience wrapper */
void avgpool1d(const float* d_x,
               float*       d_y,
               int N, int C, int L,
               int K, int S, int P)
{
    int OutL = static_cast<int>(std::floor((L + 2 * P - K) / static_cast<float>(S) + 1));

    dim3 block(BLOCK_THREADS);
    dim3 grid((OutL + BLOCK_OUT - 1) / BLOCK_OUT, C, N);

    size_t shmem_bytes = static_cast<size_t>((BLOCK_OUT - 1) * S + K) * sizeof(float);

    hipLaunchKernelGGL(avgpool1d_kernel_opt,
                       grid, block, shmem_bytes, 0,
                       d_x, d_y, N, C, L, K, S, P, OutL);
}

int main()
{
    const int N = 16;
