    hipCheck(hipMalloc(&d_x, in_elems  * sizeof(float)), "hipMalloc d_x");
    hipCheck(hipMalloc(&d_y, out_elems * sizeof(float)), "hipMalloc d_y");

    hipCheck(hipMemcpy(d_x, h_x.data(), in_elems * sizeof(float), hipMemcpyHostToDevice),
             "hipMemcpy H2D");

    avgpool1d(d_x, d_y, N, C, L, K, S, P);

    hipCheck(hipMemcpy(h_y.data(), d_y, out_elems * sizeof(float), hipMemcpyDeviceToHost),
