// -------------------------------------------------------------------------------------------------
// GPU kernel: computes total Smooth-L1 loss over `numel` elements.
// Uses warp-level shuffle reduction, minimal shared memory, vectorised inner loop.
// -------------------------------------------------------------------------------------------------
__global__ __launch_bounds__(BLOCK_SIZE, 4)
void smooth_l1_reduce_kernel(const float* __restrict__ preds,
                             const float* __restrict__ targets,
                             float*       __restrict__ g_sum,
