    constexpr unsigned int VEC = 4;                  // process 4 elements/iteration
    const unsigned int tid    = threadIdx.x;
    const unsigned int lane   = tid & (WAVE_SIZE - 1);
    const unsigned int warpId = tid >> 6;            // tid / 64
    const size_t n_threads    = gridDim.x * blockDim.x;

    float local_sum = 0.0f;

    // Vectorised loop – every thread walks strided by full grid, 4 elems at a time.
    for (size_t idx = (size_t)blockIdx.x * blockDim.x + tid; idx + (VEC - 1) < numel; idx += n_threads * VEC)
    {
        float4 p = *reinterpret_cast<const float4*>(preds   + idx);
        float4 t = *reinterpret_cast<const float4*>(targets + idx);

        float4 d;
        d.x = p.x - t.x;
        d.y = p.y - t.y;
        d.z = p.z - t.z;
        d.w = p.w - t.w;

        float4 ad;
        ad.x = fabsf(d.x);
        ad.y = fabsf(d.y);
        ad.z = fabsf(d.z);
        ad.w = fabsf(d.w);

        // Smooth-L1 elementwise
        local_sum += (ad.x < 1.f) ? 0.5f * d.x * d.x : ad.x - 0.5f;
        local_sum += (ad.y < 1.f) ? 0.5f * d.y * d.y : ad.y - 0.5f;
        local_sum += (ad.z < 1.f) ? 0.5f * d.z * d.z : ad.z - 0.5f;
        local_sum += (ad.w < 1.f) ? 0.5f * d.w * d.w : ad.w - 0.5f;
    }

    // Handle remaining tail (<4) elements if any
    for (size_t idx = (size_t)blockIdx.x * blockDim.x + tid + ((numel % VEC) ? (numel - (numel % VEC)) : numel);
         idx < numel;
         idx += n_threads)
    {
        float diff  = preds[idx] - targets[idx];
        float adiff = fabsf(diff);
        local_sum  += (adiff < 1.f) ? 0.5f * diff * diff : adiff - 0.5f;
    }

    // Warp-level reduction
    for (int offset = WAVE_SIZE >> 1; offset > 0; offset >>= 1)
        local_sum += __shfl_down(local_sum, offset);

    // First lane of each warp writes to shared mem
    __shared__ float warp_partial[WAVES_PER_BLOCK];
    if (lane == 0) warp_partial[warpId] = local_sum;
    __syncthreads();

    // First warp reduces the block’s partials
    if (warpId == 0)
    {
        float block_sum = (lane < WAVES_PER_BLOCK) ? warp_partial[lane] : 0.f;
        for (int offset = WAVE_SIZE >> 1; offset > 0; offset >>= 1)
            block_sum += __shfl_down(block_sum, offset);
        if (lane == 0) atomicAdd(g_sum, block_sum);
    }
}

// -------------------------------------------------------------------------------------------------
// Simple host driver demonstrating the kernel
// -------------------------------------------------------------------------------------------------
int main()
{
    const size_t BATCH    = 128;
    const size_t FEATURES = 4096;
    const size_t NUMEL    = BATCH * FEATURES;
    const size_t BYTES    = NUMEL * sizeof(float);

    // Generate input data
    std::vector<float> h_preds(NUMEL), h_tgts(NUMEL);
    std::mt19937 rng(123);
    std::uniform_real_distribution<float> dist(-1.f, 1.f);
    for (size_t i = 0; i < NUMEL; ++i)
    {
        h_preds[i] = dist(rng);
        h_tgts[i]  = dist(rng);
    }

    // Allocate device memory
    float *d_preds = nullptr, *d_tgts = nullptr, *d_sum = nullptr;
    CHECK(hipMalloc(&d_preds, BYTES));
    CHECK(hipMalloc(&d_tgts, BYTES));
    CHECK(hipMalloc(&d_sum, sizeof(float)));

    // Copy inputs
    CHECK(hipMemcpy(d_preds, h_preds.data(), BYTES, hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_tgts, h_tgts.data(), BYTES, hipMemcpyHostToDevice));

    float zero = 0.f;
    CHECK(hipMemcpy(d_sum, &zero, sizeof(float), hipMemcpyHostToDevice));

    // Kernel launch configuration
    int grid = std::min<int>((NUMEL + BLOCK_SIZE * 4 - 1) / (BLOCK_SIZE * 4), LAUNCH_MAX_BLOCKS);
    hipLaunchKernelGGL(smooth_l1_reduce_kernel,
                       dim3(grid),
                       dim3(BLOCK_SIZE),
                       0,
                       0,
                       d_preds,
                       d_tgts,
                       d_sum,
                       NUMEL);
    CHECK(hipGetLastError());
    CHECK(hipDeviceSynchronize());

    float h_sum = 0.f;
    CHECK(hipMemcpy(&h_sum, d_sum, sizeof(float), hipMemcpyDeviceToHost));

    std::cout << "Smooth-L1 loss (mean): "
              << h_sum / static_cast<float>(NUMEL) << std::endl;

    CHECK(hipFree(d_preds));
    CHECK(hipFree(d_tgts));
    CHECK(hipFree(d_sum));

    return 0;
}

