//////////////////////////////////////////////////////////////////
// 3-D transposed convolution, NCDHW layout, groups = 1
// Tile strategy:
//   – one block  handles one spatial location (n,d,h,w)
//   – 128 threads compute up to 128 output channels
// Memory optimisations:
//   – entire input patch placed in LDS (shared memory)
//   – pre-compute per-IC weight base pointer to cut address arithmetic
//////////////////////////////////////////////////////////////////
extern "C"
__launch_bounds__(128, 4)
__global__ void conv_transpose3d_kernel(
        const float* __restrict__ in ,
        const float* __restrict__ w  ,
        const float* __restrict__ bias,   // can be nullptr
              float* __restrict__ out,
        int  N,  int Ci, int Co,
        int  Di, int Hi, int Wi,
        int  Do, int Ho, int Wo,
        int  Kd, int Kh, int Kw,
        int  Sd, int Sh, int Sw,
        int  Pd, int Ph, int Pw,
        int  Od, int Oh, int Ow)
{
    constexpr int TILE_OC = 128;
    const int tid = threadIdx.x;

    //----------------------------------------------
    // Map grid indices → (n, d_out, h_out, w_out, oc)
    //----------------------------------------------
    if (blockIdx.y * TILE_OC + tid >= Co) return;

    int  idx    = blockIdx.x;         // flattened spatial index
    int  w_out  = idx % Wo; idx /= Wo;
    int  h_out  = idx % Ho; idx /= Ho;
    int  d_out  = idx % Do; idx /= Do;
    int  n      = idx;

    const int oc = blockIdx.y * TILE_OC + tid;

    //----------------------------------------------
    // Constant strides
    //----------------------------------------------
    const int in_D_stride  = Hi * Wi;
    const int in_C_stride  = Di * in_D_stride;
    const int in_N_stride  = Ci * in_C_stride;

    const int w_Kd_stride  = Kh * Kw;               // stride for kd
    const int w_Co_stride  = Kd * w_Kd_stride;      // stride for oc
    const int w_Ci_stride  = Co * w_Co_stride;      // stride for ic

    const int out_D_stride = Ho * Wo;
    const int out_C_stride = Do * out_D_stride;
    const int out_N_stride = Co * out_C_stride;

    //----------------------------------------------
    // Load input patch to LDS
    //----------------------------------------------
    extern __shared__ float s_in[];                 // size = Ci*Kd*Kh*Kw

    const int patchElems = Ci * Kd * Kh * Kw;

    for (int lin = tid; lin < patchElems; lin += TILE_OC) {
        int t  = lin;
        const int kw = t % Kw; t /= Kw;
        const int kh = t % Kh; t /= Kh;
        const int kd = t % Kd; t /= Kd;
        const int ic = t;

        // Map kernel position back to input idx
        const int d_nom = d_out + Pd - kd;
        const int h_nom = h_out + Ph - kh;
        const int w_nom = w_out + Pw - kw;

        float val = 0.0f;
        if ((d_nom >= 0) && (d_nom % Sd == 0)) {
            const int d_in = d_nom / Sd;
            if ((d_in < Di) && (h_nom >= 0) && (h_nom % Sh == 0)) {
                const int h_in = h_nom / Sh;
                if ((h_in < Hi) && (w_nom >= 0) && (w_nom % Sw == 0)) {
                    const int w_in = w_nom / Sw;
                    if (w_in < Wi) {
                        const size_t in_idx =
                            static_cast<size_t>(n)  * in_N_stride +
                            static_cast<size_t>(ic) * in_C_stride +
                            static_cast<size_t>(d_in) * in_D_stride +
                            static_cast<size_t>(h_in) * Wi +
                            static_cast<size_t>(w_in);
                        val = in[in_idx];
                    }
                }
            }
        }
        s_in[lin] = val;
    }
    __syncthreads();

    //----------------------------------------------
    // Accumulate over IC and kernel
    //----------------------------------------------
    float acc = 0.0f;

    for (int ic = 0; ic < Ci; ++ic) {
        const float* w_ic = w + static_cast<size_t>(ic) * w_Ci_stride + static_cast<size_t>(oc) * w_Co_stride;
        const float* s_ic = s_in + static_cast<size_t>(ic) * Kd * Kh * Kw;

        for (int kd = 0; kd < Kd; ++kd) {
            const float* w_kd = w_ic + kd * w_Kd_stride;
            const float* s_kd = s_ic + kd * Kh * Kw;

            for (int kh = 0; kh < Kh; ++kh) {
                const float* w_kh = w_kd + kh * Kw;
                const float* s_kh = s_kd + kh * Kw;

#pragma unroll
                for (int kw = 0; kw < Kw; ++kw) {
                    acc = fmaf(s_kh[kw], w_kh[kw], acc);
                }
            }
        }
    }

    if (bias != nullptr) acc += bias[oc];

    const size_t out_idx =
        static_cast<size_t>(n)  * out_N_stride +
        static_cast<size_t>(oc) * out_C_stride +
        static_cast<size_t>(d_out) * out_D_stride +
        static_cast<size_t>(h_out) * Wo +
        static_cast<size_t>(w_out);

    out[out_idx] = acc;
}

//////////////////////////////////////////////////////////////////
// Minimal driver to sanity-check the kernel
//////////////////////////////////////////////////////////////////
int main() {
    // Dimensions (same as PyTorch snippet)
    const int N  = 16;
    const int Ci = 32;
    const int Co = 64;

    const int Kd = 3, Kh = 5, Kw = 5;
    const int Sd = 1, Sh = 1, Sw = 1;
    const int Pd = 0, Ph = 0, Pw = 0;
    const int Od = 0, Oh = 0, Ow = 0;

    const int Di = 64, Hi = 64, Wi = 64;
    const int Do = (Di - 1) * Sd - 2 * Pd + Kd + Od;
    const int Ho = (Hi - 1) * Sh - 2 * Ph + Kh + Oh;
    const int Wo = (Wi - 1) * Sw - 2 * Pw + Kw + Ow;

    const size_t in_elems  = static_cast<size_t>(N) * Ci * Di * Hi * Wi;
    const size_t w_elems   = static_cast<size_t>(Ci) * Co * Kd * Kh * Kw;
    const size_t out_elems = static_cast<size_t>(N) * Co * Do * Ho * Wo;

    float* h_in   = (float*)malloc(in_elems  * sizeof(float));
    float* h_w    = (float*)malloc(w_elems   * sizeof(float));
    float* h_bias = (float*)malloc(Co        * sizeof(float));
    float* h_out  = (float*)malloc(out_elems * sizeof(float));

    for (size_t i = 0; i < in_elems; ++i)  h_in[i]  = (float)rand() / (float)RAND_MAX - 0.5f;
    for (size_t i = 0; i < w_elems;  ++i)  h_w[i]   = (float)rand() / (float)RAND_MAX - 0.5f;
    for (int     i = 0; i < Co;      ++i)  h_bias[i]= (float)rand() / (float)RAND_MAX - 0.5f;

    float *d_in, *d_w, *d_bias, *d_out;
    CHECK(hipMalloc(&d_in  , in_elems  * sizeof(float)));
    CHECK(hipMalloc(&d_w   , w_elems   * sizeof(float)));
    CHECK(hipMalloc(&d_bias, Co        * sizeof(float)));
    CHECK(hipMalloc(&d_out , out_elems * sizeof(float)));

    CHECK(hipMemcpy(d_in  , h_in  , in_elems  * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_w   , h_w   , w_elems   * sizeof(float), hipMemcpyHostToDevice));
    CHECK(hipMemcpy(d_bias, h_bias, Co        * sizeof(float), hipMemcpyHostToDevice));

    constexpr int BLOCK = 128;
    dim3 block(BLOCK);
    dim3 grid(static_cast<uint32_t>(N * Do * Ho * Wo),
              static_cast<uint32_t>((Co + BLOCK - 1)/ BLOCK));

    const size_t sharedBytes = static_cast<size_t>(Ci) * Kd * Kh * Kw * sizeof(float);

    hipLaunchKernelGGL(conv_transpose3d_kernel,
                       grid, block,
                       sharedBytes, 0,
                       d_in, d_w, d_bias, d_out,
                       N, Ci, Co,
                       Di, Hi, Wi,
                       Do, Ho, Wo,
                       Kd, Kh, Kw,
                       Sd, Sh, Sw,
                       Pd, Ph, Pw,
                       Od, Oh, Ow);

    CHECK(hipGetLastError());
    CHECK(hipMemcpy(h_out, d_out, out_elems * sizeof(float), hipMemcpyDeviceToHost));

    printf("Run complete. First output element = %f\n", h_out[0]);

    CHECK(hipFree(d_in));
    CHECK(hipFree(d_w));
    CHECK(hipFree(d_bias));
    CHECK(hipFree(d_out));
    free(h_in);
    free(h_w);
    free(h_bias);
    free(h_out);
    return 0;
}

#include <hip/hip_runtime.h>
#include <iostream>
#include <vector>
#include <random>
#include <cassert>

#define HIP_CHECK(stmt)                                                         \
    {                                                                           \
        hipError_t _err = stmt;                                                 \
        if (_err != hipSuccess) {                                               \
            std::cerr << "HIP error: " << hipGetErrorString(_err)               \
                      << " at " << __FILE__ << ":" << __LINE__ << std::endl;    \
            std::exit(EXIT_FAILURE);                                            \
        }                                                                       \
    }

constexpr int TILE_M = 64;   // rows of C per block
constexpr int TILE_N = 64;   // cols of C per block
constexpr int TILE_K = 16;   // reduction size per iteration

constexpr int THREADS_X = 16;
constexpr int THREADS_Y = 16;
constexpr int THREADS_PER_BLOCK = THREADS_X * THREADS_Y;

__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void matmul_AtB_kernel(const float* __restrict__ A,   // (M,K) row-major
                       const float* __restrict__ B,   // (N,K) row-major (will be accessed transposed)
                       float* __restrict__ C,         // (M,N) row-major
                       int M, int N, int K)
{
    __shared__ float As[TILE_M][TILE_K];  // tile of A
    __shared__ float Bs[TILE_K][TILE_N];  // tile of B^T   (K in rows, N in cols)

    const int block_row = blockIdx.y * TILE_M;  // starting row of C for this block
    const int block_col = blockIdx.x * TILE_N;  // starting col of C for this block

    const int local_row_chunk = threadIdx.y * 4; // each thread handles 4 rows
    const int local_col_chunk = threadIdx.x * 4; // each thread handles 4 cols

    float acc[4][4] = {0};

    for (int k0 = 0; k0 < K; k0 += TILE_K) {
        // 1. load A tile (TILE_M x TILE_K)
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int a_row = block_row + local_row_chunk + i;
            int a_col = k0 + threadIdx.x;  // 0..TILE_K-1 because THREADS_X==TILE_K
            float val = 0.0f;
            if (a_row < M && a_col < K)
                val = A[a_row * K + a_col];
            As[local_row_chunk + i][threadIdx.x] = val;
        }

        // 2. load B tile (TILE_K x TILE_N)  -- read B row-major and transpose on the fly
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int b_row_in_B = block_col + local_row_chunk + i; // row index in B (N dimension)
            int b_col_in_B = k0 + threadIdx.x;               // col index in B (K dimension)
            float val = 0.0f;
            if (b_row_in_B < N && b_col_in_B < K)
                val = B[b_row_in_B * K + b_col_in_B];        // B is (N,K)
            Bs[threadIdx.x][local_row_chunk + i] = val;      // store transposed
        }

        __syncthreads();

        // 3. compute small 4x4 sub-tile
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            float b_vals[4] = {
                Bs[kk][local_col_chunk + 0],
                Bs[kk][local_col_chunk + 1],
                Bs[kk][local_col_chunk + 2],
                Bs[kk][local_col_chunk + 3]
            };

            #pragma unroll
            for (int ii = 0; ii < 4; ++ii) {
                float a_val = As[local_row_chunk + ii][kk];
                acc[ii][0] += a_val * b_vals[0];
                acc[ii][1] += a_val * b_vals[1];
                acc[ii][2] += a_val * b_vals[2];
                acc[ii][3] += a_val * b_vals[3];
            }
        }

        __syncthreads();
    }

    // 4. write back results
    #pragma unroll
    for (int ii = 0; ii < 4; ++ii) {
        int c_row = block_row + local_row_chunk + ii;
        if (c_row >= M) break;
        #pragma unroll
        for (int jj = 0; jj < 4; ++jj) {
            int c_col = block_col + local_col_chunk + jj;
            if (c_col < N)
                C[c_row * N + c_col] = acc[ii][jj];
        }
    }
}

void launch_matmul(const float* dA,
                   const float* dB,
                   float* dC,
                   int M, int N, int K,
                   hipStream_t stream = nullptr)
{
    dim3 block(THREADS_X, THREADS_Y);
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (M + TILE_M - 1) / TILE_M);

    hipLaunchKernelGGL(matmul_AtB_kernel,
                       grid,
                       block,
                       0,
                       stream,
                       dA, dB, dC, M, N, K);
}

int main()
{
    const int M = 1024;
    const int K = 4096;
    const int N = 2048;

    std::vector<float> hA(static_cast<size_t>(M) * K);
    std::vector<float> hB(static_cast<size_t>(N) * K);
    std::vector<float> hC(static_cast<size_t>(M) * N, 0.0f);

    std::mt19937 rng(0);
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
    for (auto& v : hA) v = dist(rng);
    for (auto& v : hB) v = dist(rng);

    float *dA = nullptr, *dB = nullptr, *dC = nullptr;
    size_t bytesA = static_cast<size_t>(M) * K * sizeof(float);
    size_t bytesB = static_cast<size_t>(N) * K * sizeof(float);
    size_t bytesC = static_cast<size_t>(M) * N * sizeof(float);

    HIP_CHECK(hipMalloc(&dA, bytesA));
    HIP_CHECK(hipMalloc(&dB, bytesB));
    HIP_CHECK(hipMalloc(&dC, bytesC));

    HIP_CHECK(hipMemcpy(dA, hA.data(), bytesA, hipMemcpyHostToDevice));
    HIP_CHECK(hipMemcpy(dB, hB.data(), bytesB, hipMemcpyHostToDevice));

    launch_matmul(dA, dB, dC, M, N, K);

    HIP_CHECK(hipMemcpy(hC.data(), dC, bytesC, hipMemcpyDeviceToHost));

    HIP_CHECK(hipFree(dA));
    HIP_CHECK(hipFree(dB));
    HIP_CHECK(hipFree(dC));

    std::cout << "Computation complete.\n";
    return 0;
}
